QT_ISI(29,{"5242":["(Maha Suci Allah) Maha Suci dari sifat-sifat semua makhluk (Yang di tangan kekuasaan-Nyalah) yang berada dalam pengaturan-Nyalah (segala kerajaan) segala kekuasaan dan pengaruh (dan Dia Maha Kuasa atas segala sesuatu).",[["تَبَـٰرَكَ","Berbahagialah"],["ٱلَّذِى","Dia"],["بِيَدِهِ","di Tangan Siapa"],["ٱلْمُلْكُ","(ialah) Kekuasaan"],["وَهُوَ","dan Dia"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌ","Maha Berkuasa"]]],"5243":["(Yang menjadikan mati) di dunia (dan hidup) di akhirat, atau yang menjadikan mati dan hidup di dunia. Nuthfah pada asalnya sebagai barang mati, kemudian jadilah ia hidup; pengertian hidup ialah karena ia mempunyai perasaan. Pengertian mati adalah kebalikannya. Pengertian lafal al-khalqu berdasarkan makna yang kedua ini berarti memastikan (supaya Dia menguji kalian) atau mencoba kalian di dalam kehidupan ini (siapa di antara kalian yang lebih baik amalnya) maksudnya yang paling taat kepada Allah. (Dan Dia Maha Perkasa) di dalam melakukan pembalasan terhadap orang yang durhaka kepada-Nya (lagi Maha Pengampun) kepada orang yang bertobat kepada-Nya.",[["ٱلَّذِى","Dia yang"],["خَلَقَ","dicipta"],["ٱلْمَوْتَ","kematian"],["وَٱلْحَيَوٰةَ","dan kehidupan"],["لِيَبْلُوَكُمْ","supaya Dia menguji kamu"],["أَيُّكُمْ","yang mana antara kamu"],["أَحْسَنُ","(adalah) terbaik"],["عَمَلًۭا ۚ","(dalam) perbuatan"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْغَفُورُ","Yang Maha Pengampun"]]],"5244":["(Yang telah menciptakan tujuh langit berlapis-lapis) yakni sebagian di antaranya berada di atas sebagian yang lain tanpa bersentuhan. (Kamu sekali-kali tidak melihat pada ciptaan Yang Maha Pemurah) pada tujuh langit yang berlapis-lapis itu atau pada makhluk yang lain (sesuatu yang tidak seimbang) yang berbeda dan tidak seimbang. (Maka lihatlah berulang-ulang) artinya lihatlah kembali ke langit (adakah kamu lihat) padanya (keretakan?) maksudnya retak dan berbelah-belah.",[["ٱلَّذِى","Dia yang"],["خَلَقَ","dicipta"],["سَبْعَ","tujuh"],["سَمَـٰوَٰتٍۢ","syurga"],["طِبَاقًۭا ۖ","satu di atas yang lain"],["مَّا","Tidak"],["تَرَىٰ","kamu lihat"],["فِى","dalam"],["خَلْقِ","(the) penciptaan"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["مِن","sebarang"],["تَفَـٰوُتٍۢ ۖ","kesalahan"],["فَٱرْجِعِ","Jadi kembalilah"],["ٱلْبَصَرَ","penglihatan itu"],["هَلْ","boleh"],["تَرَىٰ","kamu lihat"],["مِن","sebarang"],["فُطُورٍۢ","kecacatan"]]],"5245":["(Kemudian pandanglah sekali lagi) ulangilah kembali penglihatanmu berkali-kali (niscaya akan berbalik) akan kembali (penglihatanmu itu kepadamu dalam keadaan hina) karena tidak menemukan sesuatu cacat (dan penglihatanmu itu pun dalam keadaan payah) yakni tidak melihat sama sekali adanya cacat.",[["ثُمَّ","Kemudian"],["ٱرْجِعِ","kembali"],["ٱلْبَصَرَ","penglihatan itu"],["كَرَّتَيْنِ","dua kali (sekali lagi)"],["يَنقَلِبْ","Akan kembali"],["إِلَيْكَ","kepada kamu"],["ٱلْبَصَرُ","penglihatan itu"],["خَاسِئًۭا","merendah diri"],["وَهُوَ","semasa itu"],["حَسِيرٌۭ","(adalah) penat"]]],"5246":["(Dan sesungguhnya Kami telah menghiasi langit yang dekat) yang dekat dengan bumi (dengan lampu-lampu) dengan bintang-bintang (dan Kami jadikan bintang-bintang itu alat-alat pelempar) alat untuk melempar dan merajam (setan-setan) bilamana mereka mencuri pembicaraan para malaikat dengan telinga mereka; umpamanya terpisah batu meteor dari bintang-bintang itu yang bentuknya bagaikan segumpal api, lalu mengejar setan dan membunuhnya atau membuatnya cacat. Pengertian ini bukan berarti bahwa bintang-bintang itu lenyap dari tempatnya (dan Kami sediakan bagi mereka siksa neraka yang menyala-nyala) yang besar apinya.",[["وَلَقَدْ","Dan sungguh"],["زَيَّنَّا","Kami telah mencantikkan"],["ٱلسَّمَآءَ","syurga itu"],["ٱلدُّنْيَا","terdekat"],["بِمَصَـٰبِيحَ","dengan lampu"],["وَجَعَلْنَـٰهَا","dan Kami telah menjadikan mereka"],["رُجُومًۭا","(sebagai) peluru berpandu"],["لِّلشَّيَـٰطِينِ ۖ","untuk syaitan"],["وَأَعْتَدْنَا","dan telah Kami sediakan"],["لَهُمْ","bagi mereka"],["عَذَابَ","hukuman"],["ٱلسَّعِيرِ","(dari) Api"]]],"5247":["(Dan orang-orang yang kafir kepada Rabb mereka, memperoleh azab Jahanam. Dan itulah seburuk-buruk tempat kembali) yakni neraka Jahanam.",[["وَلِلَّذِينَ","Dan bagi mereka yang"],["كَفَرُوا۟","kufur"],["بِرَبِّهِمْ","pada Tuhan mereka"],["عَذَابُ","(adalah) hukuman"],["جَهَنَّمَ ۖ","(dari) Neraka"],["وَبِئْسَ","dan celaka adalah"],["ٱلْمَصِيرُ","destinasi"]]],"5248":["(Apabila mereka dilemparkan ke dalamnya mereka mendengar suara neraka yang mengerikan) yaitu suara yang tidak enak didengar sebagaimana suara keledai (sedang neraka itu menggelegar) yakni mendidih.",[["إِذَآ","Apabila"],["أُلْقُوا۟","mereka dilemparkan"],["فِيهَا","di dalamnya"],["سَمِعُوا۟","mereka akan mendengar"],["لَهَا","daripadanya"],["شَهِيقًۭا","sedutan"],["وَهِىَ","semasa itu"],["تَفُورُ","mendidih"]]],"5249":["(Hampir-hampir neraka itu terpecah-pecah) menurut suatu qiraat lafal tamayyazu dibaca tatamayyazu sesuai dengan asalnya, artinya terbelah-belah (lantaran marah) karena murka kepada orang kafir. (Setiap kali dilemparkan ke dalamnya sekumpulan orang) segolongan di antara orang-orang kafir (penjaga-penjaga neraka itu bertanya kepada mereka) dengan pertanyaan yang mengandung nada celaan, (\"Apakah belum pernah datang kepada kalian seorang pemberi peringatan?\") maksudnya seorang rasul yang memberikan peringatan kepada kalian akan azab Allah swt.",[["تَكَادُ","Ia hampir"],["تَمَيَّزُ","pecah"],["مِنَ","daripada"],["ٱلْغَيْظِ ۖ","kemarahan"],["كُلَّمَآ","setiap masa"],["أُلْقِىَ","dilemparkan"],["فِيهَا","di dalamnya"],["فَوْجٌۭ","satu kumpulan"],["سَأَلَهُمْ","(akan) bertanya kepada mereka"],["خَزَنَتُهَآ","penjaganya"],["أَلَمْ","tidak"],["يَأْتِكُمْ","datang kepada kamu"],["نَذِيرٌۭ","seorang pemberi amaran"]]],"5250":["(Mereka menjawab, \"Benar ada, sesungguhnya telah datang kepada kami seorang pemberi peringatan, maka kami mendustakannya dan kami katakan, Allah tidak menurunkan sesuatu pun; tidak lain) tiadalah (kamu hanyalah di dalam kesesatan yang besar.\") Kalimat in antum illaa fii dhalaalin kabiir dapat dianggap sebagai perkataan para malaikat penjaga neraka kepada orang-orang kafir sewaktu mereka dijelaskan sebagai orang-orang yang mendustakan rasul-rasul. Kalimat ini pun dapat pula dianggap sebagai perkataan orang-orang kafir sebagai alasan mereka tidak percaya kepada rasul-rasul.",[["قَالُوا۟","Mereka akan berkata"],["بَلَىٰ","ya"],["قَدْ","sesungguhnya"],["جَآءَنَا","datang kepada kami"],["نَذِيرٌۭ","seorang pemberi amaran"],["فَكَذَّبْنَا","tetapi kami menafikan"],["وَقُلْنَا","dan kami berkata"],["مَا","Tidak"],["نَزَّلَ","telah menurunkan"],["ٱللَّهُ","Allah"],["مِن","sebarang"],["شَىْءٍ","perkara"],["إِنْ","Tidak"],["أَنتُمْ","kamu (adalah)"],["إِلَّا","tetapi"],["فِى","dalam"],["ضَلَـٰلٍۢ","ralat"],["كَبِيرٍۢ","yang besar"]]],"5251":["(Dan mereka berkata, \"Sekiranya kami mendengarkan) maksudnya mendengar yang disertai pemahaman (atau memikirkan) memikirkan apa yang didengarnya, yaitu peringatan rasul-rasul kepada mereka (niscaya tidaklah kami termasuk penghuni-penghuni neraka yang menyala-nyala\").",[["وَقَالُوا۟","Dan mereka akan berkata"],["لَوْ","Jika"],["كُنَّا","kami ada"],["نَسْمَعُ","mendengar"],["أَوْ","atau"],["نَعْقِلُ","beralasan"],["مَا","tidak"],["كُنَّا","kami (akan) telah"],["فِىٓ","antara"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلسَّعِيرِ","(dari) Api"]]],"5252":["(Mereka mengakui) orang-orang kafir itu mengaku di saat tiada gunanya lagi pengakuan (dosa mereka) yaitu dosa mendustakan peringatan-peringatan. (Maka kebinasaanlah) dapat dibaca fasuhqan dan fasuhuqan (bagi penghuni-penghuni neraka yang menyala-nyala) mereka dijauhkan dari rahmat Allah swt.",[["فَٱعْتَرَفُوا۟","Kemudian mereka (akan) mengaku"],["بِذَنۢبِهِمْ","dosa mereka"],["فَسُحْقًۭا","jadi jauh dengan"],["لِّأَصْحَـٰبِ","(para) sahabat"],["ٱلسَّعِيرِ","(dari) Api"]]],"5253":["(Sesungguhnya orang-orang yang takut kepada Rabbnya) mereka yang takut kepada-Nya (dalam sendirian) sewaktu mereka tidak kelihatan oleh orang lain, mereka tetap taat kepada-Nya. Dengan demikian berarti bila mereka berada secara terang-terangan maka lebih takut lagi (mereka akan memperoleh ampunan dan pahala yang besar) yang dimaksud adalah surga.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَخْشَوْنَ","bertakwa"],["رَبَّهُم","Tuhan mereka"],["بِٱلْغَيْبِ","ghaib"],["لَهُم","bagi mereka"],["مَّغْفِرَةٌۭ","(ialah) pengampunan"],["وَأَجْرٌۭ","dan ganjaran"],["كَبِيرٌۭ","yang besar"]]],"5254":["(Dan rahasiakanlah) hai manusia (perkataan kalian atau lahirkanlah ia; sesungguhnya Dia) yakni Allah swt. (Maha Mengetahui segala isi hati) Maha Mengetahui apa yang tersimpan di dalam kalbu dan apa yang kalian ucapkan. Asbabun nuzul ayat ini ialah karena orang-orang musyrik mengatakan, sebagian di antara mereka kepada sebagian yang lain, \"Rahasiakanlah pembicaraan kalian, niscaya Tuhannya Muhammad tidak akan dapat mendengarkannya.\"",[["وَأَسِرُّوا۟","Dan sembunyikan"],["قَوْلَكُمْ","ucapan kamu"],["أَوِ","atau"],["ٱجْهَرُوا۟","mengisytiharkan"],["بِهِۦٓ ۖ","ia"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِيمٌۢ","(adalah) Yang Maha Mengetahui"],["بِذَاتِ","daripada apa (yang ada)"],["ٱلصُّدُورِ","buah dada"]]],"5255":["(Apakah Tuhan yang telah menciptakan tidak mengetahui) apa yang kalian rahasiakan itu, yakni apakah ilmu-Nya tidak dapat menjangkau hal tersebut (sedangkan Dia Maha Halus) ilmu-Nya (lagi Maha Waspada).",[["أَلَا","tidak"],["يَعْلَمُ","mengetahui"],["مَنْ","(Yang Esa) Siapa"],["خَلَقَ","dicipta"],["وَهُوَ","Dan Dia"],["ٱللَّطِيفُ","(adalah) Yang Halus"],["ٱلْخَبِيرُ","yang Maha Mengetahui"]]],"5256":["(Dialah yang menjadikan bumi itu mudah bagi kalian) mudah untuk dipakai berjalan di atas permukaannya (maka berjalanlah di segala penjurunya) pada semua arahnya (dan makanlah sebagian dari rezeki-Nya) yang sengaja diciptakan buat kalian. (Dan hanya kepada-Nyalah kalian dibangkitkan) dari kubur untuk mendapatkan pembalasan.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَرْضَ","bumi"],["ذَلُولًۭا","tunduk"],["فَٱمْشُوا۟","jadi berjalanlah"],["فِى","dalam"],["مَنَاكِبِهَا","(the) laluannya"],["وَكُلُوا۟","dan makan"],["مِن","daripada"],["رِّزْقِهِۦ ۖ","rezekiNya"],["وَإِلَيْهِ","dan kepada-Nya"],["ٱلنُّشُورُ","(ialah) Kebangkitan"]]],"5257":["(Apakah kalian merasa aman) dapat dibaca secara tahqiq dan dapat pula dibaca secara tashil (terhadap kekuasaan Allah yang di langit) yakni pengaruh dan kekuasaan-Nya yang di langit (bahwa Dia akan menjungkir balikkan) berkedudukan menjadi badal dari lafal man (bumi bersama kalian, sehingga dengan tiba-tiba bumi itu berguncang) menjadi gempa dan menindih kalian.",[["ءَأَمِنتُم","Adakah kamu berasa selamat"],["مَّن","(daripadaNya) Siapa"],["فِى","(berada) dalam"],["ٱلسَّمَآءِ","syurga itu"],["أَن","tidak"],["يَخْسِفَ","Dia akan menyebabkan untuk menelan"],["بِكُمُ","kamu"],["ٱلْأَرْضَ","bumi"],["فَإِذَا","apabila"],["هِىَ","ia"],["تَمُورُ","bergoyang"]]],"5258":["(Atau apakah kalian merasa aman terhadap kekuasaan Allah yang di langit bahwa Dia akan mengirimkan) lafal an yursila menjadi badal dari lafal man (kepada kalian badai yang berbatu) yakni angin dahsyat yang menghujani kalian dengan batu. (Maka kelak kalian akan mengetahui) di saat kalian menyaksikan azab-Nya (bagaimana peringatan-Ku) yakni azab-Ku; maksudnya bahwa azab-Ku itu adalah benar.",[["أَمْ","Atau"],["أَمِنتُم","adakah kamu berasa selamat"],["مَّن","(daripadaNya) Siapa"],["فِى","(berada) dalam"],["ٱلسَّمَآءِ","syurga itu"],["أَن","bahawa"],["يُرْسِلَ","Dia akan hantar"],["عَلَيْكُمْ","terhadap kamu"],["حَاصِبًۭا ۖ","ribut batu"],["فَسَتَعْلَمُونَ","Kemudian kamu akan tahu"],["كَيْفَ","bagaimana"],["نَذِيرِ","(adalah) amaran aku"]]],"5259":["(Dan sesungguhnya orang-orang sebelum mereka telah mendustakan) umat-umat sebelum mereka. (Maka alangkah hebatnya kemurkaan-Ku) keingkaran-Ku terhadap mereka disebabkan kedustaan mereka, yaitu sewaktu mereka dibinasakan, bahwasanya pembinasaan-Ku itu adalah benar.",[["وَلَقَدْ","Dan sesungguhnya"],["كَذَّبَ","dinafikan"],["ٱلَّذِينَ","mereka"],["مِن","daripada"],["قَبْلِهِمْ","sebelum mereka"],["فَكَيْفَ","dan bagaimana"],["كَانَ","adalah"],["نَكِيرِ","penolakan aku"]]],"5260":["(Apakah mereka tidak melihat) tidak memperhatikan (burung-burung yang berada di atas mereka) yakni di udara (yang mengembangkan sayapnya) melebarkan sayapnya (dan mengatupkannya?) menutupkannya sesudah dikembangkan. (Tidak ada yang menahan mereka) agar jangan jatuh ke bumi sewaktu mengembangkan dan mengatupkan sayapnya (selain Yang Maha Penyayang) yakni dengan kekuasaan-Nya. (Sesungguhnya Dia Maha Melihat segala sesuatu) makna yang dimaksud, apakah mereka tidak menyimpulkan dengan tetapnya burung-burung di udara tentang kekuasaan Kami, bahwa Kami dapat menimpakan kepada mereka azab yang telah disebutkan di atas tadi dan azab lainnya.",[["أَوَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["إِلَى","[ke]"],["ٱلطَّيْرِ","burung-burung itu"],["فَوْقَهُمْ","di atas mereka"],["صَـٰٓفَّـٰتٍۢ","melebarkan (sayapnya)"],["وَيَقْبِضْنَ ۚ","dan lipat"],["مَا","Tidak"],["يُمْسِكُهُنَّ","memegang mereka"],["إِلَّا","kecuali"],["ٱلرَّحْمَـٰنُ ۚ","Yang Maha Pemurah"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِكُلِّ","(adalah) setiap"],["شَىْءٍۭ","perkara"],["بَصِيرٌ","Maha Melihat"]]],"5261":["(Atau siapakah) berkedudukan menjadi mubtada (dia) menjadi khabar dari mubtada (yang) menjadi badal dari lafal haadza (menjadi tentara) yakni penolong-penolong (kalian) berkedudukan menjadi shilah dari lafal alladzii (yang akan menolong kalian) menjadi sifat dari lafal jundun (selain daripada Allah Yang Maha Penyayang) yang dapat menolak datangnya azab bagi kalian; yakni tiada seseorang pun yang dapat menolong kalian (tidak lain) tiadalah (orang-orang kafir itu hanyalah dalam keadaan tertipu) mereka tertipu oleh setan, bahwasanya azab tidak akan turun atas mereka.",[["أَمَّنْ","siapa"],["هَـٰذَا","ini"],["ٱلَّذِى","yang satu"],["هُوَ","dia"],["جُندٌۭ","(adalah) tentera"],["لَّكُمْ","bagi kamu"],["يَنصُرُكُم","untuk membantu kamu"],["مِّن","daripada"],["دُونِ","selain"],["ٱلرَّحْمَـٰنِ ۚ","Yang Maha Pemurah"],["إِنِ","Tidak"],["ٱلْكَـٰفِرُونَ","(ialah) orang-orang yang kafir"],["إِلَّا","tetapi"],["فِى","dalam"],["غُرُورٍ","khayalan"]]],"5262":["(Atau siapakah dia yang memberi kalian rezeki jika Dia menahan) yakni Allah Yang Maha Penyayang menahan (rezeki-Nya) yakni hujan-Nya terhadap kalian. Jawab syaratnya tidak disebutkan, karena dapat disimpulkan dari kalimat sebelumnya. Lengkapnya, siapakah yang dapat memberi kalian rezeki? Tentu tiada seorang pun yang dapat memberikan rezeki kepada kalian selain-Nya. (Tetapi mereka terus-menerus) berkelanjutan (di dalam kesombongan) dalam kesombongannya (dan menjauhkan diri) dari kebenaran.",[["أَمَّنْ","siapa"],["هَـٰذَا","ini"],["ٱلَّذِى","yang satu"],["يَرْزُقُكُمْ","untuk menyediakan kamu"],["إِنْ","jika"],["أَمْسَكَ","Dia menahan"],["رِزْقَهُۥ ۚ","rezekiNya"],["بَل","Bahkan"],["لَّجُّوا۟","mereka berterusan"],["فِى","dalam"],["عُتُوٍّۢ","kebanggaan"],["وَنُفُورٍ","dan kebencian"]]],"5263":["(Maka apakah orang yang berjalan terjungkal) yakni terbalik (di atas mukanya itu lebih banyak mendapat petunjuk, ataukah orang yang berjalan tegap) yakni secara wajar dengan kakinya (di atas jalan) tuntunan (yang lurus) khabar dari mubtada yang kedua tidak disebutkan karena cukup hanya ditunjukkan oleh makna yang terkandung di dalam khabar yang pertama, yakni lebih banyak mendapat petunjuk. Perumpamaan ini menggambarkan tentang keadaan orang yang kafir pada permintaan yang pertama, dan orang yang beriman pada perumpamaan yang kedua, yakni manakah di antara keduanya yang lebih banyak mendapat petunjuk?",[["أَفَمَن","Maka adakah dia yang"],["يَمْشِى","berjalan-jalan"],["مُكِبًّا","jatuh"],["عَلَىٰ","pada"],["وَجْهِهِۦٓ","mukanya"],["أَهْدَىٰٓ","lebih baik dibimbing"],["أَمَّن","atau (dia) yang"],["يَمْشِى","berjalan-jalan"],["سَوِيًّا","tegak"],["عَلَىٰ","pada"],["صِرَٰطٍۢ","(the) Jalan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"5264":["(Katakanlah! \"Dialah Yang menjadikan kalian) yakni yang telah menciptakan kalian (dan menjadikan bagi kalian pendengaran, penglihatan dan hati\") atau kalbu. (Tetapi amat sedikit kalian bersyukur) huruf maa adalah huruf zaidah, dan jumlah kalimat ini merupakan jumlah isti'naf atau kalimat baru yang memberitakan tentang syukur mereka yang amat sedikit terhadap nikmat-nikmat tersebut.",[["قُلْ","Katakanlah"],["هُوَ","Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنشَأَكُمْ","menghasilkan kamu"],["وَجَعَلَ","dan dibuat"],["لَكُمُ","bagi kamu"],["ٱلسَّمْعَ","pendengaran"],["وَٱلْأَبْصَـٰرَ","dan penglihatan"],["وَٱلْأَفْـِٔدَةَ ۖ","dan perasaan"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَشْكُرُونَ","kamu ucapkan terima kasih"]]],"5265":["(Katakanlah! \"Dialah Yang menjadikan kalian berkembang biak) artinya menciptakan kalian dapat berkembang biak (di muka bumi, dan hanya kepada-Nyalah kalian kelak dikumpulkan\") untuk menjalani hisab.",[["قُلْ","Katakanlah"],["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["ذَرَأَكُمْ","memperbanyakkan kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَإِلَيْهِ","dan kepada-Nya"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"5266":["(Dan mereka berkata) kepada orang-orang yang beriman, (\"Kapankah datangnya Janji itu) yakni janji datangnya hari semua makhluk dihimpun (jika kalian adalah orang-orang yang benar?\") dalam hal ini.",[["وَيَقُولُونَ","Dan mereka berkata"],["مَتَىٰ","Apabila"],["هَـٰذَا","(adalah) ini"],["ٱلْوَعْدُ","janji"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"5267":["(Katakanlah!, \"Sesungguhnya ilmu) tentang kedatangan hari tersebut (hanya pada sisi Allah, dan sesungguhnya aku hanyalah seorang pemberi peringatan yang menjelaskan.\") Yakni yang jelas peringatannya.",[["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["ٱلْعِلْمُ","pengetahuan itu"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["وَإِنَّمَآ","dan hanya"],["أَنَا۠","aku"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌۭ","yang nyata"]]],"5268":["(Ketika mereka melihat azab itu) sesudah mereka dihimpunkan (sudah dekat) artinya, dekat sekali (menjadi muramlah) menjadi hitam muramlah (muka orang-orang kafir itu. Dan dikatakan) kepada mereka, yakni para malaikat penjaga neraka berkata kepada mereka (\"Inilah) azab (yang dahulu kalian terhadapnya) yakni sewaktu kalian diancam dengan azab ini (selalu menganggapnya sebagai yang diada-adakan.\") Yakni kalian menduga, bahwasanya kalian tidak akan dibangkitkan menjadi hidup kembali. Hal ini menceritakan keadaan di masa mendatang, akan tetapi ungkapannya memberikan pengertian sudah terjadi. Ini tiada lain karena subjeknya pasti benar-benar terjadi.",[["فَلَمَّا","Tetapi apabila"],["رَأَوْهُ","mereka (akan) melihatnya"],["زُلْفَةًۭ","menghampiri"],["سِيٓـَٔتْ","(akan) tertekan"],["وُجُوهُ","(the) muka"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["وَقِيلَ","dan ia akan dikatakan"],["هَـٰذَا","Ini"],["ٱلَّذِى","(ialah) yang"],["كُنتُم","kamu pernah"],["بِهِۦ","baginya"],["تَدَّعُونَ","panggilan"]]],"5269":["(Katakanlah!, \"Terangkanlah kepadaku jika Allah mematikan aku dan orang-orang yang bersama dengan aku) yakni orang-orang mukmin, kami binasa karena azab-Nya, sebagaimana yang kalian maksudkan (atau memberi rahmat kepada kami) maksudnya, Dia tidak mengazab kami (tetapi siapakah yang dapat melindungi orang-orang yang kafir dari siksa yang pedih?\") Tentu saja tiada seorang pun yang dapat melindungi mereka dari azab-Nya.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Pernahkah kamu melihat"],["إِنْ","jika"],["أَهْلَكَنِىَ","memusnahkan aku"],["ٱللَّهُ","Allah"],["وَمَن","dan sesiapa"],["مَّعِىَ","(ada) dengan aku"],["أَوْ","atau"],["رَحِمَنَا","mengasihani kami"],["فَمَن","kemudian siapa"],["يُجِيرُ","(boleh) melindungi"],["ٱلْكَـٰفِرِينَ","orang kafir"],["مِنْ","daripada"],["عَذَابٍ","azab"],["أَلِيمٍۢ","yang pedih"]]],"5270":["(Katakanlah!, \"Dialah Allah Yang Maha Penyayang kami beriman kepada-Nya dan kepada-Nyalah kami bertawakal. Kelak kalian akan mengetahui) bilamana mereka menyaksikan azab itu. Lafal fasata`lamuuna dapat pula dibaca fasaya`lamuuna, artinya kelak mereka akan mengetahui di saat mereka menyaksikan azab (siapakah yang berada dalam kesesatan yang nyata.\") Kami-kah atau mereka?",[["قُلْ","Katakanlah"],["هُوَ","Dia"],["ٱلرَّحْمَـٰنُ","(adalah) Yang Maha Pemurah"],["ءَامَنَّا","kami beriman"],["بِهِۦ","dalam Dia"],["وَعَلَيْهِ","dan kepada-Nya"],["تَوَكَّلْنَا ۖ","kami meletakkan amanah (kami)."],["فَسَتَعْلَمُونَ","Jadi kamu akan tahu"],["مَنْ","yang"],["هُوَ","(adalah) ia"],["فِى","(iaitu) dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍۢ","yang nyata"]]],"5271":["(Katakanlah, \"Terangkanlah kepadaku jika sumber air kalian menjadi kering;) yakni airnya masuk jauh ke dalam bumi (maka siapakah yang akan mendatangkan air yang mengalir bagi kalian?\") Sehingga air itu menyumber dan dapat dicapai oleh tangan atau oleh timba-timba, sebagaimana air yang kalian miliki sekarang? Tiada seorang pun yang dapat mendatangkannya selain Allah swt. Maka, mengapa kalian mengingkari adanya hari berbangkit, yaitu hari di mana Dia membangkitkan kalian menjadi hidup kembali. Disunahkan bagi pembaca surah ini, bila bacaannya sampai kepada lafal ma`iin, hendaknya ia mengucapkan kalimat jawabannya, yaitu \"allaahu rabbul 'aalamiina/Allah Rabb semesta alam yang dapat mengeluarkannya. Demikianlah menurut keterangan yang dikemukakan di dalam hadis. Dan ayat ini dibacakan terhadap sebagian orang-orang yang bersifat angkara murka, maka menurut perawinya, bahwa cangkul dan sekop penggali tanah terus menghunjam ke tanah, akan tetapi sumber air tidak muncul-muncul juga; ia telah pergi jauh meresap ke dalam bumi yang tidak dapat dicapainya. Kami berlindung kepada Allah dari perbuatan berani melawan Allah dan ayat-ayat-Nya.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Pernahkah kamu melihat"],["إِنْ","jika"],["أَصْبَحَ","menjadi"],["مَآؤُكُمْ","air kamu"],["غَوْرًۭا","tenggelam"],["فَمَن","kemudian siapa"],["يَأْتِيكُم","boleh membawa kamu"],["بِمَآءٍۢ","air"],["مَّعِينٍۭ","mengalir"]]],"5272":["(Nun) adalah salah satu dari huruf hijaiah, hanya Allahlah yang mengetahui arti dan maksudnya (demi qalam) yang dipakai untuk menulis nasib semua makhluk di Lohmahfuz (dan apa yang mereka tulis) apa yang ditulis oleh para malaikat berupa kebaikan dan kesalehan.",[["نٓ ۚ","Nun"],["وَٱلْقَلَمِ","Oleh pena"],["وَمَا","dan apa"],["يَسْطُرُونَ","mereka menulis"]]],"5273":["(Kamu sekali-kali bukanlah) hai Muhammad (orang gila, berkat nikmat Rabbmu) yang telah mengaruniakan kenabian kepadamu, dan juga nikmat-nikmat-Nya yang lain. Ayat ini merupakan jawaban terhadap perkataan orang-orang kafir, yang mengatakan bahwa Muhammad adalah orang gila.",[["مَآ","Tidak"],["أَنتَ","kamu (adalah)"],["بِنِعْمَةِ","dengan rahmat"],["رَبِّكَ","Tuhanmu"],["بِمَجْنُونٍۢ","orang gila"]]],"5274":["(Dan sesungguhnya bagi kamu benar-benar pahala yang besar yang tidak putus-putusnya) tiada pernah terputus.",[["وَإِنَّ","Dan sesungguhnya"],["لَكَ","bagi kamu"],["لَأَجْرًا","sesungguhnya (adalah) pahala"],["غَيْرَ","tanpa"],["مَمْنُونٍۢ","tamat"]]],"5275":["(Dan sesungguhnya kamu benar-benar berbudi pekerti) beragama (yang agung.)",[["وَإِنَّكَ","Dan sesungguhnya, kamu"],["لَعَلَىٰ","pasti (adalah)"],["خُلُقٍ","(dari) akhlak yang mulia"],["عَظِيمٍۢ","yang besar"]]],"5276":["(Maka kelak kamu akan melihat dan mereka pun akan melihat.)",[["فَسَتُبْصِرُ","Jadi kamu akan melihat"],["وَيُبْصِرُونَ","dan mereka akan melihat"]]],"5277":["(Siapakah di antara kalian yang gila) yang tidak waras akalnya, kamukah atau mereka. Lafal al-maftuun ini wazannya sama dengan lafal al-ma`quul, berasal dari mashdar al-futuun, artinya gila.",[["بِأَييِّكُمُ","yang mana antara kamu"],["ٱلْمَفْتُونُ","(ialah) orang yang ditimpa musibah"]]],"5278":["(Sesungguhnya Rabbmu, Dialah Yang Paling Mengetahui siapa yang sesat dari jalan-Nya dan Dialah Yang Paling mengetahui orang-orang yang mendapat petunjuk) lafal a`lamu di sini bermakna 'aalimun, yakni Dia mengetahui siapa yang sesat dari jalan-Nya dan Dialah Yang mengetahui orang-orang yang mendapat petunjuk.",[["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِمَن","daripada (dia) yang"],["ضَلَّ","telah sesat"],["عَن","daripada"],["سَبِيلِهِۦ","cara dia"],["وَهُوَ","dan Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِٱلْمُهْتَدِينَ","daripada orang-orang yang mendapat petunjuk"]]],"5279":["(Maka janganlah kamu ikuti orang-orang yang mendustakan ayat-ayat Allah.)",[["فَلَا","Jadi (jangan)"],["تُطِعِ","patuh"],["ٱلْمُكَذِّبِينَ","orang yang menafikan"]]],"5280":["(Mereka menginginkan) mengharapkan (supaya) merupakan mashdariyah (kamu bersikap lunak) bersikap lembut terhadap mereka (lalu mereka bersikap lunak) pula terhadapmu; diathafkan kepada lafal tudhinu. Seandainya dijadikan sebagai jawab dari tamanni yang tersimpulkan dari lafal wadduu, maka sebelum huruf fa diperkirakan adanya lafal hum. Yakni, seandainya kamu bersikap lunak terhadap mereka, maka mereka pun akan bersikap lunak pula terhadapmu.",[["وَدُّوا۟","Mereka mahu"],["لَوْ","bahawa"],["تُدْهِنُ","kamu harus berkompromi"],["فَيُدْهِنُونَ","jadi mereka akan berkompromi"]]],"5281":["(Dan janganlah kamu ikuti setiap orang yang banyak bersumpah) dengan cara yang batil (lagi hina) yakni rendah.",[["وَلَا","Dan jangan"],["تُطِعْ","patuh"],["كُلَّ","setiap"],["حَلَّافٍۢ","kebiasaan mengumpat"],["مَّهِينٍ","tidak bernilai"]]],"5282":["(Yang banyak mencela) atau sering mengumpat (yang kian ke mari menghambur fitnah) yakni berjalan ke sana dan ke mari di antara orang-orang dengan maksud merusak mereka, yakni menghasut mereka.",[["هَمَّازٍۢ","Pemfitnah"],["مَّشَّآءٍۭ","sedang berjalan"],["بِنَمِيمٍۢ","dengan gosip jahat"]]],"5283":["(Yang banyak menghalangi perbuatan baik) artinya sangat kikir tidak mau membelanjakan hartanya kepada hak-hak yang diwajibkan atas dirinya (yang melampaui batas) sangat aniaya (lagi banyak dosa) banyak melakukan perbuatan dosa.",[["مَّنَّاعٍۢ","Seorang pencegah"],["لِّلْخَيْرِ","daripada (yang) baik"],["مُعْتَدٍ","pelanggar"],["أَثِيمٍ","berdosa"]]],"5284":["(Yang kaku kasar) wataknya kaku lagi kasar (selain dari itu, yang terkenal kejahatannya) dia adalah seseorang yang dianggap sebagai orang Quraisy, padahal dia bukan dari kalangan mereka, yaitu Walid bin Mughirah. Ayahnya menjulukinya sebagai orang Quraisy setelah ia berumur delapan belas tahun. Ibnu Abbas r.a. mengatakan, bahwa kami belum pernah mengetahui, bahwa Allah swt. menyifati seseorang dengan sifat-sifat yang tercela sebagaimana yang telah dilakukan-Nya terhadap Walid, sehingga keaiban itu tetap menempel pada diri Walid untuk selama-lamanya. Dan bertaalluq kepada lafal zaniim, zharaf yang terdapat pada sebelumnya.",[["عُتُلٍّۭ","kejam"],["بَعْدَ","selepas"],["ذَٰلِكَ","(semua) itu"],["زَنِيمٍ","tidak berguna sama sekali"]]],"5285":["(Karena dia mempunyai banyak harta dan anak) bentuk asalnya adalah lian, dan bertaalluq kepada makna yang menunjukkan terhadap pengertiannya.",[["أَن","Kerana"],["كَانَ","(dia) ialah"],["ذَا","seorang pemilik"],["مَالٍۢ","(dari) kekayaan"],["وَبَنِينَ","dan kanak-kanak"]]],"5286":["(Apabila dibacakan kepadanya ayat-ayat Kami) yakni Alquran (ia berkata) bahwa Alquran itu (dongeng-dongengan orang-orang dahulu kala.\") Yaitu hanyalah kedustaan yang sengaja dibuat-buat guna menyenangkan hati kami sewaktu ia disebutkan atau diceritakan. Menurut suatu qiraat ada lafal a-an dengan memakai dua huruf Hamzah yang kedua-duanya difathahkan.",[["إِذَا","Apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِ","kepadanya"],["ءَايَـٰتُنَا","Ayat Kami"],["قَالَ","katanya"],["أَسَـٰطِيرُ","Cerita"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"5287":["(Kelak akan Kami beri tanda dia di belalainya) Kami akan menjadikan tanda pada hidungnya, yang menyebabkannya cacat seumur hidup. Maka dia terpotong-potong hidungnya ketika perang Badar.",[["سَنَسِمُهُۥ","Kami akan menjenamakan dia"],["عَلَى","pada"],["ٱلْخُرْطُومِ","muncung"]]],"5288":["(Sesungguhnya Kami telah mencoba mereka) Kami telah menguji orang-orang musyrik Mekah dengan paceklik dan kelaparan (sebagaimana Kami telah mencoba pemilik-pemilik kebun) atau ladang (ketika mereka bersumpah bahwa mereka sungguh-sungguh akan memetik hasilnya) akan memetik buahnya (di pagi hari) di pagi buta, supaya orang-orang miskin tidak mengetahuinya. Maka orang-orang yang memiliki kebun itu mempunyai alasan bila mereka tidak memberikan sedekah kepada mereka; tidak sebagaimana bapak-bapak mereka yang selalu memberikan sebagian dari hasilnya buat orang-orang miskin sebagai sedekahnya.",[["إِنَّا","Sesungguhnya Kami"],["بَلَوْنَـٰهُمْ","telah mencuba mereka"],["كَمَا","seperti"],["بَلَوْنَآ","Kami cuba"],["أَصْحَـٰبَ","(para) sahabat"],["ٱلْجَنَّةِ","(dari) taman itu"],["إِذْ","apabila"],["أَقْسَمُوا۟","mereka bersumpah"],["لَيَصْرِمُنَّهَا","untuk memetik buahnya"],["مُصْبِحِينَ","(pada) pagi"]]],"5289":["(Dan mereka tidak mengecualikan) di dalam sumpah mereka itu kepada kehendak Allah swt. Ayat ini merupakan jumlah isti'naf atau kalimat permulaan; yakni, kelakuan mereka seperti itu; mereka tidak pernah menggantungkan sumpahnya itu kepada kehendak Allah swt.",[["وَلَا","Dan tidak"],["يَسْتَثْنُونَ","membuat pengecualian"]]],"5290":["(Lalu kebun itu diliputi malapetaka dari Rabbmu) berupa api yang melahap kesemuanya di waktu malam (ketika mereka sedang tidur.)",[["فَطَافَ","Jadi datanglah"],["عَلَيْهَا","atasnya"],["طَآئِفٌۭ","satu lawatan"],["مِّن","daripada"],["رَّبِّكَ","Tuhanmu"],["وَهُمْ","sedangkan mereka"],["نَآئِمُونَ","sedang tidur"]]],"5291":["(Maka jadilah kebun itu hitam seperti malam yang gelap gulita) yakni menjadi hangus terbakar semuanya, sehingga tampak hitam.",[["فَأَصْبَحَتْ","Jadi ia menjadi"],["كَٱلصَّرِيمِ","seolah-olah dituai"]]],"5292":["(Lalu mereka panggil-memanggil di pagi hari.)",[["فَتَنَادَوْا۟","Dan mereka memanggil satu sama lain"],["مُصْبِحِينَ","(pada) pagi"]]],"5293":["(\"Pergilah di waktu pagi ini ke kebun kalian) ke ladang kalian; lafal ini menafsirkan pengertian yang terkandung di dalam lafal tanadauw; atau huruf an dianggap sebagai an mashdariyah (jika kalian hendak memetik buahnya\") ingin memetik hasilnya; jawab syaratnya ditunjukkan oleh pengertian kalimat sebelumnya.",[["أَنِ","Itu"],["ٱغْدُوا۟","Pergi awal"],["عَلَىٰ","kepada"],["حَرْثِكُمْ","tanaman kamu"],["إِن","jika"],["كُنتُمْ","kamu akan"],["صَـٰرِمِينَ","memetik buahnya"]]],"5294":["(Maka pergilah mereka saling berbisik-bisikan) yakni dengan secara diam-diam.",[["فَٱنطَلَقُوا۟","Jadi mereka pergi"],["وَهُمْ","sedangkan mereka"],["يَتَخَـٰفَتُونَ","merendahkan suara (mereka)."]]],"5295":["(\"Pada hari ini janganlah ada seorang miskin pun masuk ke dalam kebun kalian.\") Ayat ini merupakan penafsiran dari makna yang terkandung pada ayat sebelumnya; atau huruf an dianggap sebagai huruf mashdariyah.",[["أَن","Itu"],["لَّا","Tidak"],["يَدْخُلَنَّهَا","akan memasukinya"],["ٱلْيَوْمَ","hari ini"],["عَلَيْكُم","ke atas kamu"],["مِّسْكِينٌۭ","mana-mana orang miskin"]]],"5296":["(Dan berangkatlah mereka di pagi hari dengan niat menghalangi) orang-orang miskin (seraya merasa mampu) yakni mampu untuk menghalangi orang-orang miskin, menurut dugaan mereka sendiri.",[["وَغَدَوْا۟","Dan mereka pergi awal"],["عَلَىٰ","dengan"],["حَرْدٍۢ","keazaman"],["قَـٰدِرِينَ","mampu"]]],"5297":["(Tatkala mereka melihat kebun itu) dalam keadaan hangus terbakar (mereka berkata, \"Sesungguhnya kita benar-benar orang-orang yang sesat.\") Bukankah ini kebun kita. Kemudian setelah mereka mengetahui, bahwa itu adalah benar-benar kebun mereka, lalu mereka mengatakan:",[["فَلَمَّا","Tetapi apabila"],["رَأَوْهَا","mereka melihatnya"],["قَالُوٓا۟","mereka berkata"],["إِنَّا","Sesungguhnya kami"],["لَضَآلُّونَ","(adalah) pasti hilang"]]],"5298":["(Bahkan kita dihalangi) dari memperoleh buahnya disebabkan kita telah menghalang-halangi orang-orang miskin dari memperoleh bagiannya.",[["بَلْ","Bahkan"],["نَحْنُ","Kami"],["مَحْرُومُونَ","(adalah) dilucutkan"]]],"5299":["(Berkatalah seorang yang paling baik pikirannya di antara mereka) yaitu orang yang terbaik di antara mereka (\"Bukankah aku mengatakan kepada kalian, mengapa tidak) kenapa tidak (kalian bertasbih?\") kepada Allah seraya bertobat kepada-Nya.",[["قَالَ","Berkata"],["أَوْسَطُهُمْ","(yang) paling sederhana daripada mereka"],["أَلَمْ","tidak"],["أَقُل","aku beritahu"],["لَّكُمْ","kamu"],["لَوْلَا","'Kenapa tidak"],["تُسَبِّحُونَ","kamu mengagungkan (Allah)?'"]]],"5300":["(Mereka mengucapkan, \"Maha Suci Rabb kami, sesungguhnya kami adalah orang-orang yang zalim.\") Karena kami telah menghalang-halangi orang-orang miskin dari haknya.",[["قَالُوا۟","Mereka berkata"],["سُبْحَـٰنَ","Maha Suci"],["رَبِّنَآ","(kepada) Tuhan kami"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kami] dulu"],["ظَـٰلِمِينَ","orang yang zalim"]]],"5301":["(Lalu sebagian mereka menghadapi sebagian yang lain seraya cela-mencela.)",[["فَأَقْبَلَ","Kemudian didekati"],["بَعْضُهُمْ","sebahagian mereka"],["عَلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["يَتَلَـٰوَمُونَ","menyalahkan antara satu sama lain"]]],"5302":["(Mereka berkata, \"Aduhai) huruf ya di sini bermakna tanbih (celakalah kita) binasalah kita (sesungguhnya kita ini benar-benar orang-orang yang melampaui batas.)",[["قَالُوا۟","Mereka berkata"],["يَـٰوَيْلَنَآ","Wahai celaka kami"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","[kami] dulu"],["طَـٰغِينَ","penderhaka"]]],"5303":["(Mudah-mudahan Rabb kita memberikan ganti kepada kita) dapat dibaca yubdilanaa dan yubaddilanaa (yang lebih baik daripada itu; sesungguhnya kita mengharapkan ampunan dari Rabb kita.\") Supaya Dia menerima tobat kita dan mendatangkan kepada kita kebun yang lebih baik dari kebun kita yang dahulu. Menurut suatu riwayat disebutkan, bahwa setelah itu mereka diberi kebun yang lebih baik dari yang semula.",[["عَسَىٰ","barangkali"],["رَبُّنَآ","Tuhan kami"],["أَن","[bahawa]"],["يُبْدِلَنَا","akan menggantikan kita"],["خَيْرًۭا","yang lebih baik"],["مِّنْهَآ","daripadanya"],["إِنَّآ","Sesungguhnya kami"],["إِلَىٰ","kepada"],["رَبِّنَا","Tuhan kami"],["رَٰغِبُونَ","berpaling khusyuk"]]],"5304":["(Seperti itulah) sebagaimana azab Kami kepada mereka (azab) di dunia, bagi orang yang menentang perintah Kami dari kalangan orang-orang kafir Mekah dan lain-lainnya. (Dan sesungguhnya azab akhirat lebih besar jika mereka mengetahui) jika mereka mengetahuinya, niscaya mereka tidak akan menentang perintah Kami. Ayat ini diturunkan sewaktu orang-orang kafir Mekah mengatakan, bahwa jika Dia membangkitkan kami, niscaya kami akan diberi pahala yang lebih baik daripada kalian.",[["كَذَٰلِكَ","begitu"],["ٱلْعَذَابُ ۖ","(adalah) hukuman"],["وَلَعَذَابُ","Dan pasti azabnya"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["أَكْبَرُ ۚ","(adalah) lebih besar"],["لَوْ","jika"],["كَانُوا۟","mereka"],["يَعْلَمُونَ","mengetahui"]]],"5305":["(Sesungguhnya bagi orang-orang yang bertakwa surga-surga yang penuh kenikmatan di sisi Rabbnya.)",[["إِنَّ","Sesungguhnya"],["لِلْمُتَّقِينَ","untuk orang yang soleh"],["عِندَ","dengan"],["رَبِّهِمْ","Tuhan mereka"],["جَنَّـٰتِ","(adalah) Taman-taman"],["ٱلنَّعِيمِ","(dari) Kegembiraan"]]],"5306":["(Maka apakah patut Kami menjadikan orang-orang Islam itu sama dengan orang-orang yang berdosa?) maksudnya mendapatkan pahala yang sama dengan orang-orang kafir.",[["أَفَنَجْعَلُ","Kemudian Kami akan merawat"],["ٱلْمُسْلِمِينَ","kaum muslimin"],["كَٱلْمُجْرِمِينَ","seperti penjenayah"]]],"5307":["(Mengapa kalian berbuat demikian; bagaimanakah kalian mengambil keputusan?) dengan keputusan yang rusak ini?",[["مَا","Apa"],["لَكُمْ","(adalah) untuk kamu"],["كَيْفَ","Bagaimana"],["تَحْكُمُونَ","(adakah) kamu menilai"]]],"5308":["(Atau adakah) artinya, benarkah (kalian mempunyai kitab) yang diturunkan dari Allah (yang kalian mempelajarinya) yang kalian membacanya.",[["أَمْ","Atau"],["لَكُمْ","(adalah) untuk kamu"],["كِتَـٰبٌۭ","sebuah buku"],["فِيهِ","di mana"],["تَدْرُسُونَ","kamu belajar"]]],"5309":["(Bahwa di dalamnya kalian benar-benar boleh memilih apa yang kalian sukai) kalian boleh memilih sesuka hati.",[["إِنَّ","Sesungguhnya"],["لَكُمْ","bagi kamu"],["فِيهِ","di dalamnya"],["لَمَا","apa"],["تَخَيَّرُونَ","kamu pilih"]]],"5310":["(Atau apakah kalian memperoleh janji-janji) perjanjian-perjanjian (yang diperkuat dengan sumpah dari Kami) yang telah diperkuat oleh Kami (yang tetap berlaku sampai hari kiamat) lafal ilaa yaumil qiyaamah ini bertaalluq kepadanya makna yang terkandung di dalam lafal 'alainaa, dan di dalam kalam ini terkandung makna qasam atau sumpah, yakni Kami telah bersumpah untuk mewajibkannya bagi kalian (sesungguhnya kalian benar-benar dapat mengambil keputusan) sekehendak kalian tentangnya?",[["أَمْ","Atau"],["لَكُمْ","bagi kamu"],["أَيْمَـٰنٌ","sumpah"],["عَلَيْنَا","daripada kami"],["بَـٰلِغَةٌ","mencapai"],["إِلَىٰ","kepada"],["يَوْمِ","(the) Hari"],["ٱلْقِيَـٰمَةِ ۙ","Kiamat"],["إِنَّ","sesungguhnya"],["لَكُمْ","bagi kamu"],["لَمَا","(ialah) apa"],["تَحْكُمُونَ","kamu menilai"]]],"5311":["(Tanyakanlah kepada mereka, \"Siapakah di antara mereka terhadap hal tersebut) hukum atau keputusan yang mereka ambil buat diri mereka sendiri, yaitu bahwasanya mereka kelak di akhirat akan diberi pahala yang lebih utama dari orang-orang mukmin (yang bertanggung jawab?\") yang menanggungnya bagi mereka.",[["سَلْهُمْ","Tanya mereka"],["أَيُّهُم","yang mana antara mereka"],["بِذَٰلِكَ","untuk itu"],["زَعِيمٌ","(adalah) bertanggungjawab"]]],"5312":["(Atau apakah mereka mempunyai) di sisi mereka (sekutu-sekutu?) yang sepakat dengan mereka tentang ucapan itu, yaitu mereka akan menjamin bagi mereka dalam hal ini. Maka apabila memang demikian keadaannya (maka hendaklah mereka mendatangkan sekutu-sekutu mereka) yang akan memberikan jaminan tentang hal itu bagi mereka (jika mereka adalah orang-orang yang benar.)",[["أَمْ","Atau"],["لَهُمْ","(adalah) untuk mereka"],["شُرَكَآءُ","rakan kongsi"],["فَلْيَأْتُوا۟","Kemudian biarkan mereka membawa"],["بِشُرَكَآئِهِمْ","rakan kongsi mereka"],["إِن","jika"],["كَانُوا۟","mereka adalah"],["صَـٰدِقِينَ","jujur"]]],"5313":["Ingatlah (pada hari betis disingkapkan) ungkapan ini menggambarkan tentang dahsyatnya keadaan pada hari kiamat, yaitu sewaktu hisab dan pembalasan dilaksanakan. Dikatakan \"kasyafatil harbu 'an saaqin\", artinya perang itu berkobar dengan sengitnya (dan mereka dipanggil untuk bersujud) sebagai ujian buat keimanan mereka (maka mereka tidak kuasa) karena punggung mereka lekat bertumpuk menjadi satu, sehingga mereka tidak dapat bersujud.",[["يَوْمَ","(The) Hari"],["يُكْشَفُ","akan terbongkar"],["عَن","daripada"],["سَاقٍۢ","tulang kering"],["وَيُدْعَوْنَ","dan mereka akan dipanggil"],["إِلَى","kepada"],["ٱلسُّجُودِ","sujud"],["فَلَا","tetapi tidak"],["يَسْتَطِيعُونَ","mereka akan dapat"]]],"5314":["(Seraya tunduk ke bawah) lafal khaasyi`atan ini merupakan hal dari dhamir yang terkandung pada lafal yad`uuna, artinya, dalam keadaan terhina (pandangan mereka) maksudnya, mereka tidak dapat mengangkat pandangan matanya (lagi mereka diliputi) mereka diselimuti (kehinaan. Dan sesungguhnya mereka dahulu diseru) sewaktu di dunia (untuk bersujud sedang mereka dalam keadaan sejahtera) akan tetapi mereka tidak mau melakukannya, yakni tidak mau salat.",[["خَـٰشِعَةً","Merendah diri"],["أَبْصَـٰرُهُمْ","mata mereka"],["تَرْهَقُهُمْ","akan menutupi mereka"],["ذِلَّةٌۭ ۖ","penghinaan"],["وَقَدْ","Dan sesungguhnya"],["كَانُوا۟","mereka adalah"],["يُدْعَوْنَ","dipanggil"],["إِلَى","kepada"],["ٱلسُّجُودِ","sujud"],["وَهُمْ","sedangkan mereka"],["سَـٰلِمُونَ","(adalah) bunyi"]]],"5315":["(Maka serahkanlah kepada-Ku) berikanlah kepada Aku (orang-orang yang mendustakan perkataan ini) yang mendustakan Alquran. (Nanti Kami akan menarik mereka dengan berangsur-angsur) Kami akan mengambil mereka secara berangsur-angsur (dari arah yang tidak mereka ketahui.)",[["فَذَرْنِى","Jadi tinggalkan Aku"],["وَمَن","dan sesiapa"],["يُكَذِّبُ","menafikan"],["بِهَـٰذَا","ini"],["ٱلْحَدِيثِ ۖ","Kenyataan"],["سَنَسْتَدْرِجُهُم","Kami akan memimpin mereka secara progresif"],["مِّنْ","daripada"],["حَيْثُ","di mana"],["لَا","tidak"],["يَعْلَمُونَ","mereka tahu"]]],"5316":["(Dan Aku memberi tangguh kepada mereka) Aku menangguhkan mereka. (Sesungguhnya rencana-Ku amat teguh) amat kuat dan tak dapat ditinggalkan.",[["وَأُمْلِى","Dan aku akan memberi tangguh"],["لَهُمْ ۚ","kepada mereka"],["إِنَّ","Sesungguhnya"],["كَيْدِى","rancangan aku"],["مَتِينٌ","(adalah) tegas"]]],"5317":["(Ataukah) yakni apakah (kamu meminta kepada mereka) atas penyampaian risalahmu (upah dengan utang, lalu mereka karena utang itu) karena apa yang harus mereka bayarkan kepadamu (merasa keberatan) karena itu lalu mereka tidak mau beriman kepada Alquran.",[["أَمْ","Atau"],["تَسْـَٔلُهُمْ","kamu bertanya kepada mereka"],["أَجْرًۭا","bayaran"],["فَهُم","jadi mereka"],["مِّن","daripada"],["مَّغْرَمٍۢ","(yang) hutang"],["مُّثْقَلُونَ","(ada) terbeban"]]],"5318":["(Ataukah ada pada mereka ilmu tentang yang gaib) yaitu mengenai apa yang tertulis di Lohmahfuz (lalu mereka menulis) daripadanya apa yang mereka katakan itu.",[["أَمْ","Atau"],["عِندَهُمُ","(ada) bersama mereka"],["ٱلْغَيْبُ","yang ghaib"],["فَهُمْ","jadi mereka"],["يَكْتُبُونَ","menulisnya"]]],"5319":["(Maka bersabarlah kamu terhadap ketetapan Rabbmu) terhadap mereka, sesuai dengan apa yang dikehendaki-Nya (dan janganlah kamu seperti orang yang berada dalam perut ikan paus) dalam hal ketergesa-gesaannya dan ketidaksabarannya, yaitu sebagaimana Nabi Yunus a.s. (ketika ia berdoa) kepada Rabbnya (sedangkan ia dalam keadaan marah) terhadap kaumnya, hatinya penuh dengan kemarahan sewaktu ia berada di dalam perut ikan besar itu.",[["فَٱصْبِرْ","Jadi bersabarlah"],["لِحُكْمِ","untuk (the) keputusan"],["رَبِّكَ","Tuhanmu"],["وَلَا","dan jangan"],["تَكُن","jadilah"],["كَصَاحِبِ","seperti (the) pendamping"],["ٱلْحُوتِ","(dari) ikan"],["إِذْ","apabila"],["نَادَىٰ","dia memanggil"],["وَهُوَ","sedangkan dia"],["مَكْظُومٌۭ","(telah) tertekan"]]],"5320":["(Kalau sekiranya ia tidak segera mendapat) tidak segera disusul oleh (nikmat) yakni rahmat (dari Rabbnya, benar-benar ia dicampakkan) dari perut ikan besar itu (ke tanah yang tandus) tanah yang tidak ada tumbuh-tumbuhannya (dalam keadaan tercela) akan tetapi Allah mengasihaninya sehingga ia dicampakkan tidak dalam keadaan tercela.",[["لَّوْلَآ","Jika tidak"],["أَن","bahawa"],["تَدَٰرَكَهُۥ","mendahuluinya"],["نِعْمَةٌۭ","sebuah nikmat"],["مِّن","daripada"],["رَّبِّهِۦ","Tuhannya"],["لَنُبِذَ","nescaya dia akan tercampak"],["بِٱلْعَرَآءِ","ke (the) pantai telanjang"],["وَهُوَ","sedangkan dia"],["مَذْمُومٌۭ","(telah) dipersalahkan"]]],"5321":["(Lalu Rabbnya memilihnya) memberinya kenabian (dan menjadikannya termasuk orang-orang yang saleh) yakni sebagian dari para nabi.",[["فَٱجْتَبَـٰهُ","Tetapi memilih dia"],["رَبُّهُۥ","Tuhannya"],["فَجَعَلَهُۥ","dan menjadikan dia"],["مِنَ","daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"5322":["(Dan sesungguhnya orang-orang kafir itu benar-benar hampir menggelincirkan kamu) dapat dibaca layuzliquunaka dan layazliquunaka (dengan pandangan mereka) mereka memandangmu dengan pandangan yang sangat tajam, sehingga pandangannya hampir-hampir membuatmu pingsan dan menjatuhkanmu dari tempat atau kedudukanmu (tatkala mereka mendengar peringatan) yakni Alquran (dan mereka berkata) karena dengki, (\"Sesungguhnya ia benar-benar orang gila.\") Mereka dengki karena Alquran yang diturunkan kepadanya itu.",[["وَإِن","Dan sesungguhnya"],["يَكَادُ","akan hampir"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَيُزْلِقُونَكَ","pasti membuat kamu tergelincir"],["بِأَبْصَـٰرِهِمْ","dengan rupa mereka"],["لَمَّا","apabila"],["سَمِعُوا۟","mereka dengar"],["ٱلذِّكْرَ","Mesej"],["وَيَقُولُونَ","dan mereka berkata"],["إِنَّهُۥ","Sesungguhnya dia"],["لَمَجْنُونٌۭ","(adalah) pasti marah"]]],"5323":["(Dan tidak lain dia) yakni Alquran itu (hanyalah peringatan) pelajaran (bagi seluruh umat) yaitu jin dan manusia, dan tiada menimbulkan kegilaan disebabkannya.",[["وَمَا","Dan tidak"],["هُوَ","ia (adalah)"],["إِلَّا","tetapi"],["ذِكْرٌۭ","satu Peringatan"],["لِّلْعَـٰلَمِينَ","kepada dunia"]]],"5324":["(Hari yang benar) yaitu hari kiamat, dikatakan demikian karena pada hari itu dibenarkan hal-hal yang diingkari, seperti mengenai adanya hari kebangkitan, hari hisab dan hari pembalasan. Atau dinamakan demikian karena pada hari itu ditampakkan kepada mereka hal-hal tersebut.",[["ٱلْحَآقَّةُ","Realiti Yang Tidak Dapat Dielakkan"]]],"5325":["(Apakah hari yang benar itu) ungkapan ini mengandung makna yang menggambarkan tentang keagungan hari kiamat; dan berkedudukan sebagai mubtada yang sekaligus sebagai khabar dari lafal al-haaqqah yang pertama.",[["مَا","Apa"],["ٱلْحَآقَّةُ","(ialah) Realiti Yang Tidak Dapat Dielakkan"]]],"5326":["(Dan tahukah kamu) sudah tahukah kamu (apakah hari yang benar itu?) ungkapan ini menambah keagungan hari kiamat. Maa yang pertama menjadi mubtada sedangkan maa yang kedua menjadi khabarnya. Dan maa yang kedua berikut khabarnya berkedudukan sebagai maf'ul kedua dari lafal adraa.",[["وَمَآ","Dan apa"],["أَدْرَىٰكَ","akan membuat kamu tahu"],["مَا","apa"],["ٱلْحَآقَّةُ","(ialah) Realiti Yang Tidak Dapat Dielakkan"]]],"5327":["(Kaum Tsamud dan kaum 'Ad telah mendustakan hari yang menggentarkan) yakni hari kiamat, hari kiamat dinamakan demikian karena kedahsyatan dan kengerian yang terjadi pada hari itu sangat menggentarkan hati.",[["كَذَّبَتْ","dinafikan"],["ثَمُودُ","kaum Thamud"],["وَعَادٌۢ","dan Aad"],["بِٱلْقَارِعَةِ","Musibah yang Melanda"]]],"5328":["(Adapun kaum Tsamud, maka mereka telah dibinasakan dengan teriakan yang dahsyat) teriakan yang kerasnya melampaui batas.",[["فَأَمَّا","Jadi untuk"],["ثَمُودُ","kaum Thamud"],["فَأُهْلِكُوا۟","mereka telah musnah"],["بِٱلطَّاغِيَةِ","oleh kuat (letupan)"]]],"5329":["(Adapun kaum Ad maka mereka telah dibinasakan dengan angin yang sangat keras) sangat keras suaranya (lagi amat kuat) kuat lagi keras; angin tersebut ditimpakan atas kaum Ad, sekalipun mereka kuat lagi keras tetapi menghadapi angin ini mereka tidak berarti apa-apa.",[["وَأَمَّا","Dan untuk"],["عَادٌۭ","Aad"],["فَأُهْلِكُوا۟","mereka telah musnah"],["بِرِيحٍۢ","oleh angin"],["صَرْصَرٍ","menjerit"],["عَاتِيَةٍۢ","ganas"]]],"5330":["(Yang Allah tundukkan angin itu) artinya Allah mengirimkannya dengan kekuasaan-Nya (kepada mereka selama tujuh malam dan delapan hari) dimulai pada pagi hari Rabu, tanggal dua puluh dua bulan Syawal; angin itu terjadi di pertengahan musim dingin (terus-menerus) atau secara berturut-turut. Keadaan angin itu diserupakan dengan pekerjaan yang dilakukan oleh tukang setrika, yaitu sewaktu ia mengulang-ulang setrikaannya pada penyakit yang diobatinya. Yakni, ia mengulang-ulanginya dari satu waktu ke waktu yang lainnya hingga penyakitnya lenyap sama sekali (maka kamu lihat kaum 'Ad pada waktu itu mati bergelimpangan) mereka tercampakkan ke dalam keadaan binasa (seakan-akan mereka batang) pokok (pohon kurma yang lapuk) yang jatuh karena keropos atau lapuk.",[["سَخَّرَهَا","Yang Dia kenakan"],["عَلَيْهِمْ","ke atas mereka"],["سَبْعَ","(untuk) tujuh"],["لَيَالٍۢ","malam-malam"],["وَثَمَـٰنِيَةَ","dan lapan"],["أَيَّامٍ","hari"],["حُسُومًۭا","(dalam) berturut-turut"],["فَتَرَى","jadi kamu akan melihat"],["ٱلْقَوْمَ","manusia"],["فِيهَا","di dalamnya"],["صَرْعَىٰ","jatuh"],["كَأَنَّهُمْ","seolah-olah mereka"],["أَعْجَازُ","batang"],["نَخْلٍ","(daripada) kurma"],["خَاوِيَةٍۢ","hampa"]]],"5331":["(Maka apakah kamu melihat bekas-bekas mereka?) lafal baaqiyah adalah sifat dari lafal nafsin yang diperkirakan keberadaannya; yaitu apakah kamu melihat seseorang pun yang tinggal di antara mereka? Atau lafal baaqiyah ini huruf ta-nya untuk menunjukkan makna mubalaghah, yakni bekas-bekasnya? Tentu saja tidak.",[["فَهَلْ","Kemudian lakukan"],["تَرَىٰ","kamu lihat"],["لَهُم","daripada mereka"],["مِّنۢ","sebarang"],["بَاقِيَةٍۢ","tinggal"]]],"5332":["(Dan telah datang Firaun dan orang-orang yang mengikutinya) beserta para pengikutnya. Menurut suatu qiraat, lafal qabilahu dibaca qablahu sehingga artinya, orang-orang kafir yang sebelumnya (dan negeri-negeri yang dijungkirbalikkan) penduduknya dijungkirbalikkan berikut negeri-negeri tempat tinggal mereka; yang dimaksud adalah negeri-negeri tempat tinggal kaum Nabi Luth (karena kesalahan yang besar) karena mereka mengerjakan perbuatan-perbuatan dosa besar.",[["وَجَآءَ","Dan datang"],["فِرْعَوْنُ","Firaun"],["وَمَن","dan (mereka)"],["قَبْلَهُۥ","sebelum dia"],["وَٱلْمُؤْتَفِكَـٰتُ","dan kota-kota yang terbalik"],["بِٱلْخَاطِئَةِ","dengan dosa"]]],"5333":["(Maka masing-masing mereka mendurhakai rasul Rabb mereka) mendurhakai Nabi Luth dan nabi-nabi lainnya (lalu Allah menyiksa mereka dengan siksaan yang sangat keras) siksaan yang lebih keras daripada siksaan-siksaan lainnya.",[["فَعَصَوْا۟","Dan mereka menderhaka"],["رَسُولَ","(the) Rasul"],["رَبِّهِمْ","(dari) Tuhan mereka"],["فَأَخَذَهُمْ","maka Dia menangkap mereka"],["أَخْذَةًۭ","(dengan) sawan"],["رَّابِيَةً","melebihi"]]],"5334":["(Sesungguhnya Kami tatkala air naik) naik ke atas, sehingga segala sesuatu termasuk gunung-gunung dan lain-lainnya semuanya tenggelam yaitu, pada masa banjir besar (Kami bawa kalian) bapak moyang kalian, karena kalian pada zaman itu masih berada di dalam tulang sulbi mereka (ke dalam bahtera) atau perahu yang dibuat oleh Nabi Nuh. Akhirnya, selamatlah Nabi Nuh beserta orang-orang yang beriman bersamanya yang berada di dalam bahtera itu, sedangkan yang lainnya semua mati tenggelam.",[["إِنَّا","Sesungguhnya Kami"],["لَمَّا","apabila"],["طَغَا","melimpah"],["ٱلْمَآءُ","air itu"],["حَمَلْنَـٰكُمْ","Kami membawa kamu"],["فِى","dalam"],["ٱلْجَارِيَةِ","pelayaran (kapal)"]]],"5335":["(Agar Kami jadikan peristiwa itu) atau perbuatan ini, yaitu diselamatkan-Nya orang-orang yang beriman dan ditenggelamkan-Nya orang-orang yang kafir (peringatan bagi kalian) pelajaran (dan agar diperhatikan) supaya hal itu tetap diingat (oleh telinga yang mau mendengar) mau menerima apa yang didengarnya.",[["لِنَجْعَلَهَا","Supaya Kami berjaya"],["لَكُمْ","bagi kamu"],["تَذْكِرَةًۭ","peringatan"],["وَتَعِيَهَآ","dan akan menyedarinya"],["أُذُنٌۭ","sebuah telinga"],["وَٰعِيَةٌۭ","sedar"]]],"5336":["(Maka apabila sangkakala ditiup sekali tiup) yaitu, untuk tiupan yang kedua kalinya, sebagai pemula untuk dijalankannya peradilan di antara semua makhluk.",[["فَإِذَا","Kemudian apabila"],["نُفِخَ","ditiup"],["فِى","dalam"],["ٱلصُّورِ","sangkakala"],["نَفْخَةٌۭ","satu letupan"],["وَٰحِدَةٌۭ","bujang"]]],"5337":["(Dan diangkatlah) diangkatlah ke atas (bumi dan gunung-gunung, lalu dibenturkan keduanya) diadukan (sekali bentur.)",[["وَحُمِلَتِ","Dan diangkat"],["ٱلْأَرْضُ","bumi"],["وَٱلْجِبَالُ","dan pergunungan"],["فَدُكَّتَا","dan dihancurkan"],["دَكَّةًۭ","(dengan) menghancurkan"],["وَٰحِدَةًۭ","bujang"]]],"5338":["(Maka pada hari itu terjadilah hari kiamat) yakni hari terakhir.",[["فَيَوْمَئِذٍۢ","Kemudian (pada) hari itu"],["وَقَعَتِ","akan berlaku"],["ٱلْوَاقِعَةُ","Kejadian"]]],"5339":["(Dan terbelahlah langit, karena pada hari itu langit menjadi lemah) melemah.",[["وَٱنشَقَّتِ","Dan akan berpecah"],["ٱلسَّمَآءُ","syurga itu"],["فَهِىَ","jadi ia"],["يَوْمَئِذٍۢ","(ada) pada hari itu"],["وَاهِيَةٌۭ","lemah"]]],"5340":["(Dan malaikat-malaikat) lafal al-malaku adalah bentuk jamak dari lafal malaa'ikah, artinya malaikat-malaikat (berada di penjuru-penjuru langit) berada di seantero langit. (Dan diangkatlah Arasy Rabbmu di atas mereka) oleh malaikat-malaikat tersebut (pada hari itu yang jumlahnya ada delapan malaikat) ada delapan malaikat atau delapan barisan malaikat.",[["وَٱلْمَلَكُ","Dan para Malaikat"],["عَلَىٰٓ","(akan) pada"],["أَرْجَآئِهَا ۚ","tepinya"],["وَيَحْمِلُ","dan akan menanggung"],["عَرْشَ","(the) Takhta"],["رَبِّكَ","Tuhanmu"],["فَوْقَهُمْ","di atas mereka"],["يَوْمَئِذٍۢ","hari itu"],["ثَمَـٰنِيَةٌۭ","lapan"]]],"5341":["(Pada hari itu kalian dihadapkan) untuk menjalani hisab (tiada yang tersembunyi) dapat dibaca laa takhfaa dan laa yakhfaa (dari keadaan kalian barang sedikit pun) yaitu dari hal-hal yang kalian rahasiakan.",[["يَوْمَئِذٍۢ","Hari itu"],["تُعْرَضُونَ","kamu akan dipamerkan"],["لَا","tidak"],["تَخْفَىٰ","akan disembunyikan"],["مِنكُمْ","antara kamu"],["خَافِيَةٌۭ","sebarang rahsia"]]],"5342":["(Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kanannya, maka dia berkata) kepada golongannya untuk mengetahui apa yang dia rahasiakan: (\"Ambillah) terimalah (bacalah kitabku ini.\") Di dalam ungkapan ini terdapat perselisihan pendapat, manakah di antara lafal haa-umu dan iqra`uu yang menjadi amil dari lafal kitabiyah ini?",[["فَأَمَّا","Kemudian untuk"],["مَنْ","(dia) siapa"],["أُوتِىَ","diberikan"],["كِتَـٰبَهُۥ","rekodnya"],["بِيَمِينِهِۦ","di tangan kanannya"],["فَيَقُولُ","akan berkata"],["هَآؤُمُ","Di sini"],["ٱقْرَءُوا۟","membaca"],["كِتَـٰبِيَهْ","rekod aku"]]],"5343":["(\"Sesungguhnya aku yakin) aku telah merasa yakin (bahwa sesungguhnya aku akan menemui hisab terhadap diriku.\")",[["إِنِّى","Sesungguhnya aku"],["ظَنَنتُ","sudah pasti"],["أَنِّى","bahawa aku"],["مُلَـٰقٍ","(akan) bertemu"],["حِسَابِيَهْ","akaun aku"]]],"5344":["(Maka orang itu berada dalam kehidupan yang diridai) lafal raadhiyah berarti mardhiyah, artinya diridai.",[["فَهُوَ","Jadi dia"],["فِى","(akan) masuk"],["عِيشَةٍۢ","sebuah kehidupan"],["رَّاضِيَةٍۢ","menyenangkan"]]],"5345":["(Dalam surga yang tinggi.)",[["فِى","Dalam"],["جَنَّةٍ","sebuah Taman"],["عَالِيَةٍۢ","dinaikkan"]]],"5346":["(Buah-buahannya) buah-buahan yang dipetiknya (dekat) sangat dekat yaitu dapat dicapai oleh orang yang berdiri, orang yang duduk, dan malah orang yang berbaring.",[["قُطُوفُهَا","Gugusan buah-buahannya"],["دَانِيَةٌۭ","tergantung dekat"]]],"5347":["Maka dikatakan kepada mereka: (\"Makan dan minumlah dengan nyaman) lafal hanii'an berkedudukan sebagai hal, dengan sedap (disebabkan amal yang telah kalian kerjakan pada hari-hari yang telah lalu\") sewaktu kalian di dunia.",[["كُلُوا۟","makan"],["وَٱشْرَبُوا۟","dan minum"],["هَنِيٓـًٔۢا","(dalam) kepuasan"],["بِمَآ","bagi apa"],["أَسْلَفْتُمْ","kamu hantar sebelum kamu"],["فِى","dalam"],["ٱلْأَيَّامِ","hari-hari"],["ٱلْخَالِيَةِ","lalu"]]],"5348":["(Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kirinya, maka dia berkata, \"Aduhai) wahai; lafal ya di sini menunjukkan makna tanbih (alangkah baiknya kiranya tidak diberikan kepadaku kitabku.)",[["وَأَمَّا","Tetapi untuk"],["مَنْ","(dia) siapa"],["أُوتِىَ","diberikan"],["كِتَـٰبَهُۥ","rekodnya"],["بِشِمَالِهِۦ","di tangan kirinya"],["فَيَقُولُ","akan berkata"],["يَـٰلَيْتَنِى","O! aku harap"],["لَمْ","tidak"],["أُوتَ","Aku telah diberikan"],["كِتَـٰبِيَهْ","rekod aku"]]],"5349":["(Dan aku tidak mengetahui apa hisab terhadap diriku.)",[["وَلَمْ","Dan tidak"],["أَدْرِ","Aku telah tahu"],["مَا","apa"],["حِسَابِيَهْ","(ialah) akaun aku"]]],"5350":["(Wahai kiranya kematian itulah) kematian di dunia (yang menyelesaikan segala sesuatu.) Yang memutuskan hidupku dan tidak akan dibangkitkan lagi.",[["يَـٰلَيْتَهَا","O! Aku berharap ia"],["كَانَتِ","telah"],["ٱلْقَاضِيَةَ","penghujungnya"]]],"5351":["(Hartaku sekali-kali tidak memberi manfaat kepadaku.)",[["مَآ","Tidak"],["أَغْنَىٰ","telah mendapat manfaat"],["عَنِّى","aku"],["مَالِيَهْ ۜ","kekayaan aku"]]],"5352":["(Telah hilang kekuasaanku dariku\") kekuatanku dan argumentasi atau hujahku. Huruf Ha yang terdapat dalam lafal kitabiyah, hisabiyah, maliyah, dan sulthaniyah, semuanya adalah ha saktah yang tetap dibaca baik dalam keadaan Waqaf maupun dalam keadaan Washal. Demikian itu karena mengikut mushhaf imam/induk dan karena mengikut dalil naqli. Akan tetapi sekali pun demikian, ada pula sebagian ulama yang tidak membacakannya bila diwashalkan.",[["هَلَكَ","sudah tiada"],["عَنِّى","daripada aku"],["سُلْطَـٰنِيَهْ","kewibawaan aku"]]],"5353":["(\"Peganglah dia) khithab atau perintah dalam ayat ini ditujukan kepada para malaikat penjaga neraka Jahanam (lalu belenggulah dia.\") Ikatlah kedua tangannya menjadi satu dengan kepalanya ke dalam belenggu.",[["خُذُوهُ","Tangkap dia"],["فَغُلُّوهُ","dan membelenggunya"]]],"5354":["(\"Kemudian ke dalam neraka Jahanam) neraka yang apinya menyala-nyala (masukkanlah dia\") jebloskanlah dia ke dalamnya.",[["ثُمَّ","Kemudian"],["ٱلْجَحِيمَ","(ke dalam) api Neraka"],["صَلُّوهُ","bakar dia"]]],"5355":["(\"Kemudian dengan rantai yang panjangnya tujuh puluh hasta) menurut ukuran hasta malaikat (belitlah dia\") lilitlah dia dengan rantai itu sesudah ia dimasukkan ke dalam neraka. Huruf fa di sini tidak dapat mencegah hubungan antara fi'il dan zharaf yang mendahuluinya.",[["ثُمَّ","Kemudian"],["فِى","ke dalam"],["سِلْسِلَةٍۢ","rantai"],["ذَرْعُهَا","panjangnya"],["سَبْعُونَ","(adalah) tujuh puluh"],["ذِرَاعًۭا","hasta"],["فَٱسْلُكُوهُ","masukkan dia"]]],"5356":["(\"Sesungguhnya dia dahulu tidak beriman kepada Allah Yang Maha Besar.\")",[["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["لَا","tidak"],["يُؤْمِنُ","beriman"],["بِٱللَّهِ","kepada Allah"],["ٱلْعَظِيمِ","yang Maha Agung"]]],"5357":["(\"Dan juga dia tidak mendorong untuk memberi makan orang miskin.\")",[["وَلَا","Dan (tidak) tidak"],["يَحُضُّ","rasa terdesak"],["عَلَىٰ","pada"],["طَعَامِ","(yang) memberi makan"],["ٱلْمِسْكِينِ","(dari) orang-orang miskin"]]],"5358":["(Maka tiada seorang teman pun baginya pada hari ini di sini) maksudnya, pada hari ini tiada kaum kerabat yang bermanfaat bagi dirinya.",[["فَلَيْسَ","Jadi tidak"],["لَهُ","baginya"],["ٱلْيَوْمَ","hari ini"],["هَـٰهُنَا","di sini"],["حَمِيمٌۭ","mana-mana kawan yang setia"]]],"5359":["(Dan tiada pula makanan sedikit pun baginya kecuali dari darah dan nanah) yaitu nanah dan darah ahli neraka, atau shadiid, yaitu nama sejenis pohon yang ada di dalam neraka.",[["وَلَا","Dan tidak"],["طَعَامٌ","sebarang makanan"],["إِلَّا","kecuali"],["مِنْ","daripada"],["غِسْلِينٍۢ","(the) pelepasan luka"]]],"5360":["(Tidak ada yang memakannya kecuali orang-orang yang berdosa) orang-orang yang kafir.",[["لَّا","Tidak"],["يَأْكُلُهُۥٓ","akan memakannya"],["إِلَّا","kecuali"],["ٱلْخَـٰطِـُٔونَ","orang berdosa"]]],"5361":["(Maka) huruf laa di sini adalah huruf zaidah (Aku bersumpah dengan apa yang kalian lihat) makhluk-makhluk yang kalian lihat.",[["فَلَآ","Tetapi tidak"],["أُقْسِمُ","aku bersumpah"],["بِمَا","oleh apa"],["تُبْصِرُونَ","kamu lihat"]]],"5362":["(Dan dengan apa yang tidak kalian lihat) di antara makhluk-makhluk itu.",[["وَمَا","Dan apa"],["لَا","tidak"],["تُبْصِرُونَ","kamu lihat"]]],"5363":["(Sesungguhnya dia) yakni Alquran itu (adalah benar-benar perkataan utusan yang mulia) yang disampaikan oleh malaikat Jibril dari Allah swt.",[["إِنَّهُۥ","Sesungguhnya ia (adalah)"],["لَقَوْلُ","sesungguhnya (perkataan) itu"],["رَسُولٍۢ","(dari) seorang Rasul"],["كَرِيمٍۢ","mulia"]]],"5364":["(Dan Alquran itu bukanlah perkataan seorang penyair. Sedikit sekali kalian beriman kepadanya.)",[["وَمَا","Dan tidak"],["هُوَ","ia"],["بِقَوْلِ","(ialah) perkataan"],["شَاعِرٍۢ ۚ","(dari) seorang penyair"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تُؤْمِنُونَ","kamu beriman"]]],"5365":["(Dan bukan pula perkataan tukang tenung. Sedikit sekali kalian mengambil pelajaran darinya) lafal tu'minuuna pada ayat di atas dan lafal tadzakkaruuna, kedua-duanya dapat pula dibaca yu'minuuna dan yadzakkaruuna. Huruf maa-nya merupakan huruf zaidah yang berfungsi mengukuhkan makna. Makna ayat, bahwasanya mereka itu hanya beriman kepada hal-hal yang sedikit sekali, dan mereka pun hanya ingat sedikit tentang hal-hal yang didatangkan oleh Nabi saw. yaitu berupa kebaikan, silaturahmi, dan memelihara kehormatan. Maka hal-hal tersebut tiada memberi manfaat kepada mereka barang sedikit pun.",[["وَلَا","Dan tidak"],["بِقَوْلِ","(ia adalah) perkataan"],["كَاهِنٍۢ ۚ","(dari) tukang ramal"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَذَكَّرُونَ","kamu ambil iktibar"]]],"5366":["Bahkan Alquran itu (diturunkan dari Rabb semesta alam.)",[["تَنزِيلٌۭ","(Ia adalah) wahyu"],["مِّن","daripada"],["رَّبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"5367":["(Seandainya dia mengada-adakan) yakni Nabi Muhammad (sebagian perkataan atas nama Kami) seumpamanya dia mengatakan dari Kami, padahal Kami tidak pernah mengatakannya.",[["وَلَوْ","Dan jika"],["تَقَوَّلَ","dia (telah) mengada-adakan"],["عَلَيْنَا","terhadap Kami"],["بَعْضَ","beberapa"],["ٱلْأَقَاوِيلِ","kata-kata"]]],"5368":["(Niscaya benar-benar Kami pegang) niscaya Kami tangkap (dia) sebagai hukuman baginya (dengan kekuatan) dan kekuasaan-Ku.",[["لَأَخَذْنَا","Sesungguhnya Kami (akan) merampas"],["مِنْهُ","dia"],["بِٱلْيَمِينِ","dengan tangan kanan"]]],"5369":["(Kemudian benar-benar Kami potong urat tali jantungnya) yang apabila urat itu terputus maka orang itu akan mati.",[["ثُمَّ","Kemudian"],["لَقَطَعْنَا","sesungguhnya Kami (akan) putuskan"],["مِنْهُ","daripada dia"],["ٱلْوَتِينَ","aorta"]]],"5370":["(Maka sekali-kali tidak ada seorang pun dari kalian) lafal min ahadin adalah isimnya maa, sedangkan huruf min adalah huruf zaidah yang mengandung makna mengukuhkan kenafiannya. Dan lafal minkum adalah hal dari lafal ahadin (yang dapat menghalang-halangi Kami daripadanya) tiada seorang pun yang dapat mencegah-Ku daripadanya. Lafal haajiziina adalah khabar dari maa, dan ia dijamakkan karena lafal ahadan di dalam konteks nafi yang maknanya mengandung pengertian jamak. Dan dhamir yang terdapat di dalam lafal `anhu merujuk kepada Nabi saw.; yakni tiada seorang pun yang dapat mencegah Kami dari hukumannya.",[["فَمَا","Dan tidak"],["مِنكُم","daripada kamu"],["مِّنْ","sebarang"],["أَحَدٍ","satu"],["عَنْهُ","[daripada dia]"],["حَـٰجِزِينَ","(siapa yang boleh) menghalang (ia)"]]],"5371":["(Dan sesungguhnya dia itu) Alquran itu (benar-benar suatu pelajaran bagi orang-orang yang bertakwa.)",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَتَذْكِرَةٌۭ","(adalah) sesungguhnya peringatan"],["لِّلْمُتَّقِينَ","bagi orang yang bertakwa"]]],"5372":["(Dan sesungguhnya Kami benar-benar mengetahui, bahwa di antara kalian) hai manusia (ada orang-orang yang mendustakan) Alquran dan ada pula yang mempercayainya.",[["وَإِنَّا","Dan sesungguhnya, Kami"],["لَنَعْلَمُ","pasti tahu"],["أَنَّ","bahawa"],["مِنكُم","antara kamu"],["مُّكَذِّبِينَ","(adalah) orang yang menafikan"]]],"5373":["(Dan sesungguhnya dia itu) Alquran itu (menjadi penyesalan bagi orang-orang kafir) di saat mereka melihat pahala yang diterima oleh orang-orang yang beriman kepadanya, dan hukuman yang diterima oleh orang-orang yang mendustakannya.",[["وَإِنَّهُۥ","Dan sesungguhnya, ia"],["لَحَسْرَةٌ","(adalah) pasti suatu penyesalan"],["عَلَى","ke atas"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"5374":["(Dan sesungguhnya dia itu) Alquran itu (benar-benar perkara hak yang diyakini) atau keyakinan yang hak.",[["وَإِنَّهُۥ","Dan sesungguhnya, ia (adalah)"],["لَحَقُّ","sesungguhnya (yang) benar"],["ٱلْيَقِينِ","(dari) kepastian"]]],"5375":["(Maka bertasbihlah) sucikanlah Dia (dengan menyebut nama) huruf ba di sini adalah huruf zaidah (Rabbmu Yang Maha Besar) Maha Suci Dia.",[["فَسَبِّحْ","Maka bertasbihlah"],["بِٱسْمِ","(nama)"],["رَبِّكَ","Tuhanmu"],["ٱلْعَظِيمِ","yang Maha Agung"]]],"5376":["(Seseorang telah meminta) yakni berdoa meminta (kedatangan azab yang akan menimpa.)",[["سَأَلَ","Ditanya"],["سَآئِلٌۢ","seorang penyoal"],["بِعَذَابٍۢ","tentang suatu hukuman"],["وَاقِعٍۢ","pasti berlaku"]]],"5377":["(Untuk orang-orang kafir, yang tidak seorang pun dapat menolaknya) dia adalah Nadhr bin Haris, ia mengatakan di dalam permintaannya, sebagaimana yang disitir oleh firman-Nya, \"Ya Allah, jika betul (Alquran) ini, dialah yang benar dari sisi Engkau...\" (Q.S. Al-Anfal 32)",[["لِّلْكَـٰفِرِينَ","Kepada orang-orang kafir"],["لَيْسَ","tidak"],["لَهُۥ","daripadanya"],["دَافِعٌۭ","sebarang pencegah"]]],"5378":["(Yang datang dari Allah) lafal minallaah ini berkaitan erat dengan lafal Waaqi' yang ada di akhir ayat pertama (yang mempunyai tempat-tempat naik) tempat-tempat naik bagi para malaikat, yaitu langit.",[["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["ذِى","Pemilik"],["ٱلْمَعَارِجِ","(dari) cara-cara pendakian"]]],"5379":["(Naiklah) dapat dibaca ta`ruju dan ya`ruju (malaikat-malaikat dan Jibril) Malaikat Jibril (kepada-Nya) kepada tempat turun bagi perintah-Nya di langit (dalam sehari) lafal fii yaumin bertaalluq kepada lafal yang tidak disebutkan, azab menimpa orang-orang kafir pada hari kiamat (yang kadarnya lima puluh ribu tahun) ini menurut apa yang dirasakan oleh orang kafir, karena penderitaan dan kesengsaraan yang mereka temui di hari itu. Adapun orang yang beriman merasakan hal itu amat pendek, bahkan lebih pendek daripada satu kali salat fardu yang dilakukan sewaktu di dunia. Demikianlah menurut keterangan yang disebutkan di dalam hadis.",[["تَعْرُجُ","Naik"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["وَٱلرُّوحُ","dan Roh"],["إِلَيْهِ","kepada-Nya"],["فِى","dalam"],["يَوْمٍۢ","sehari"],["كَانَ","[adalah]"],["مِقْدَارُهُۥ","sukatannya"],["خَمْسِينَ","(adalah) lima puluh"],["أَلْفَ","ribu"],["سَنَةٍۢ","tahun"]]],"5380":["(Maka bersabarlah kamu) ayat ini diturunkan sebelum ada perintah berperang (dengan sabar yang baik) sabar yang tidak disertai dengan gelisah.",[["فَٱصْبِرْ","Jadi bersabarlah"],["صَبْرًۭا","sebuah kesabaran"],["جَمِيلًا","kebaikan"]]],"5381":["(Sesungguhnya mereka memandangnya) memandang azab itu (jauh) artinya mustahil akan terjadi.",[["إِنَّهُمْ","Sesungguhnya mereka"],["يَرَوْنَهُۥ","lihatlah"],["بَعِيدًۭا","(sebagai) jauh"]]],"5382":["(Sedangkan Kami memandangnya dekat) pasti terjadi.",[["وَنَرَىٰهُ","Tetapi Kami melihatnya"],["قَرِيبًۭا","dekat"]]],"5383":["(Pada hari ketika langit) lafal ayat ini bertaalluq kepada lafal yang tidak disebutkan, yaitu azab itu terjadi pada hari ketika langit (menjadi seperti luluhan perak) seperti leburan perak.",[["يَوْمَ","(The) Hari"],["تَكُونُ","akan menjadi"],["ٱلسَّمَآءُ","langit"],["كَٱلْمُهْلِ","seperti tembaga cair"]]],"5384":["(Dan gunung-gunung menjadi seperti bulu) maksudnya bagaikan bulu domba ringannya, terbawa terbang oleh angin.",[["وَتَكُونُ","Dan akan menjadi"],["ٱلْجِبَالُ","pergunungan"],["كَٱلْعِهْنِ","seperti bulu"]]],"5385":["(Dan tidak ada seorang teman akrab pun menanyakan temannya) tiada karib kerabat yang menanyakan kerabatnya, karena pada hari itu masing-masing orang disibukkan oleh keadaannya sendiri.",[["وَلَا","Dan tidak"],["يَسْـَٔلُ","akan bertanya"],["حَمِيمٌ","seorang kawan"],["حَمِيمًۭا","(tentang) kawan"]]],"5386":["(Sedangkan mereka saling melihat) sebagian teman-teman akrab itu saling melihat kepada sebagian yang lain, dan mereka saling mengenal antara yang satu dengan yang lainnya akan tetapi mereka tiada berkata barang sepatah pun. Jumlah ayat ini merupakan kalimat baru atau jumlah isti'naf. (Orang kafir ingin) ia berharap (kalau sekiranya) lafal lau di sini bermakna an, yakni bahwasanya (dia dapat menebus dirinya dari azab hari itu) dapat dibaca yaumi'idzin dan yauma'idzin (dengan anak-anaknya.)",[["يُبَصَّرُونَهُمْ ۚ","Mereka akan dibuat untuk melihat satu sama lain"],["يَوَدُّ","Ingin"],["ٱلْمُجْرِمُ","penjenayah itu"],["لَوْ","jika"],["يَفْتَدِى","dia (boleh) ditebus"],["مِنْ","daripada"],["عَذَابِ","azab"],["يَوْمِئِذٍۭ","(pada) hari itu"],["بِبَنِيهِ","oleh anak-anaknya"]]],"5387":["(Dan istrinya) atau teman hidupnya (dan saudaranya.)",[["وَصَـٰحِبَتِهِۦ","Dan pasangannya"],["وَأَخِيهِ","dan abangnya"]]],"5388":["(Dan kaum familinya) atau famili-familinya, mereka dinamakan fashiilah karena orang yang bersangkutan terpisah hubungannya dengan mereka (yang melindunginya) yang pernah mengasuhnya.",[["وَفَصِيلَتِهِ","Dan saudara terdekatnya"],["ٱلَّتِى","yang"],["تُـْٔوِيهِ","menaunginya"]]],"5389":["(Dan orang-orang di atas bumi seluruhnya, kemudian mengharapkan tebusan itu dapat menyelamatkannya) dapat membebaskannya dari azab itu. Lafal ayat ini diathafkan kepada lafal yaftadii.",[["وَمَن","Dan sesiapa"],["فِى","(berada) di atas"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["ثُمَّ","kemudian"],["يُنجِيهِ","ia (boleh) menyelamatkannya"]]],"5390":["(Sekali-kali tidak dapat) lafal ini merupakan sanggahan terhadap apa yang dia harapkan itu (sesungguhnya neraka ini) neraka yang mereka saksikan itu (adalah api yang bergejolak) lafal lazhaa adalah nama lain dari neraka Jahanam, dinamakan demikian karena apinya bergejolak membakar orang-orang kafir.",[["كَلَّآ ۖ","sama sekali tidak"],["إِنَّهَا","Sesungguhnya ia (adalah)"],["لَظَىٰ","sesungguhnya api neraka"]]],"5391":["(Yang mengelupaskan kulit kepala) asy-syawaa bentuk jamak dari lafal syawaatun, artinya kulit kepala.",[["نَزَّاعَةًۭ","Penghilang"],["لِّلشَّوَىٰ","daripada kulit kepala"]]],"5392":["(Yang memanggil orang yang membelakang dan yang berpaling) dari iman; sebab neraka Jahanam itu mengatakan kepada mereka kemarilah, kemarilah.",[["تَدْعُوا۟","Menjemput"],["مَنْ","(dia) siapa"],["أَدْبَرَ","berpaling ke belakang"],["وَتَوَلَّىٰ","dan pergi"]]],"5393":["(Serta mengumpulkan) harta (lalu menyimpannya) menaruhnya di dalam peti simpanan dan tidak menunaikan hak Allah yang ada pada harta bendanya itu.",[["وَجَمَعَ","Dan dikumpulkan"],["فَأَوْعَىٰٓ","dan ditimbun"]]],"5394":["(Sesungguhnya manusia diciptakan bersifat keluh-kesah) lafal haluu`an merupakan hal atau kata keterangan keadaan dari lafal yang tidak disebutkan, dan sekaligus sebagai penafsirnya.",[["۞ إِنَّ","Sesungguhnya"],["ٱلْإِنسَـٰنَ","lelaki itu"],["خُلِقَ","telah dicipta"],["هَلُوعًا","cemas"]]],"5395":["(Apabila ia ditimpa kesusahan ia berkeluh kesah) atau sewaktu ia ditimpa keburukan berkeluh kesah.",[["إِذَا","Apabila"],["مَسَّهُ","menyentuhnya"],["ٱلشَّرُّ","yang jahat"],["جَزُوعًۭا","tertekan"]]],"5396":["(Dan apabila ia mendapat kebaikan ia amat kikir) sewaktu ia mendapat harta benda ia kikir, tidak mau menunaikan hak Allah yang ada pada hartanya itu.",[["وَإِذَا","Dan apabila"],["مَسَّهُ","menyentuhnya"],["ٱلْخَيْرُ","yang baik"],["مَنُوعًا","penahanan"]]],"5397":["(Kecuali orang-orang yang mengerjakan salat) yakni, orang-orang yang beriman.",[["إِلَّا","Kecuali"],["ٱلْمُصَلِّينَ","mereka yang solat"]]],"5398":["(Yang mereka itu tetap mengerjakan salatnya) terus-menerus mengerjakannya.",[["ٱلَّذِينَ","Orang yang"],["هُمْ","[mereka]"],["عَلَىٰ","di"],["صَلَاتِهِمْ","doa mereka"],["دَآئِمُونَ","(adalah) tetap"]]],"5399":["(Dan orang-orang yang dalam hartanya tersedia bagian tertentu) yakni zakat.",[["وَٱلَّذِينَ","Dan orang yang"],["فِىٓ","dalam"],["أَمْوَٰلِهِمْ","kekayaan mereka"],["حَقٌّۭ","(adalah) hak"],["مَّعْلُومٌۭ","diketahui"]]],"5400":["(Bagi orang miskin yang meminta dan orang yang tidak mempunyai apa-apa) yang tidak mau meminta-minta, demi memelihara kehormatannya sekalipun ia tidak punya.",[["لِّلسَّآئِلِ","Bagi yang bertanya"],["وَٱلْمَحْرُومِ","dan yang terlantar"]]],"5401":["(Dan orang-orang yang mempercayai hari pembalasan) yaitu, hari ketika semua orang mendapatkan balasan amal perbuatannya.",[["وَٱلَّذِينَ","Dan orang yang"],["يُصَدِّقُونَ","menerima kebenaran"],["بِيَوْمِ","hari"],["ٱلدِّينِ","(dari) Penghakiman"]]],"5402":["(Dan orang-orang yang takut terhadap azab Rabbnya) mereka takut akan azab-Nya.",[["وَٱلَّذِينَ","Dan orang yang"],["هُم","[mereka]"],["مِّنْ","daripada"],["عَذَابِ","azab"],["رَبِّهِم","(dari) Tuhan mereka"],["مُّشْفِقُونَ","(adalah) takut"]]],"5403":["(Karena sesungguhnya azab Rabb mereka tidak dapat orang merasa aman) dari kedatangannya.",[["إِنَّ","Sesungguhnya"],["عَذَابَ","azab"],["رَبِّهِمْ","Tuhanmu"],["غَيْرُ","(adalah) tidak"],["مَأْمُونٍۢ","untuk berasa selamat (dari)"]]],"5404":["(Dan orang-orang yang memelihara kemaluannya.)",[["وَٱلَّذِينَ","Dan orang yang"],["هُمْ","[mereka]"],["لِفُرُوجِهِمْ","kesederhanaan mereka"],["حَـٰفِظُونَ","(adalah) penjaga"]]],"5405":["(Kecuali terhadap istri-istri mereka atau budak-budak yang mereka miliki) yakni budak-budak perempuan (maka sesungguhnya mereka dalam hal ini tidak tercela.)",[["إِلَّا","Kecuali"],["عَلَىٰٓ","daripada"],["أَزْوَٰجِهِمْ","pasangan mereka"],["أَوْ","atau"],["مَا","apa"],["مَلَكَتْ","mereka miliki"],["أَيْمَـٰنُهُمْ","secara wajar"],["فَإِنَّهُمْ","maka sesungguhnya mereka"],["غَيْرُ","(adalah) tidak"],["مَلُومِينَ","patut dipersalahkan"]]],"5406":["(Barang siapa mencari yang di balik itu, maka mereka itulah orang-orang yang melampaui batas) melanggar batas kehalalan menuju kepada keharaman.",[["فَمَنِ","Tetapi siapa pun"],["ٱبْتَغَىٰ","mencari"],["وَرَآءَ","di luar"],["ذَٰلِكَ","bahawa"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْعَادُونَ","(ialah) orang-orang yang melampaui batas"]]],"5407":["(Dan orang-orang yang terhadap amanat-amanat mereka) menurut suatu qiraat lafal amaanaatihim dibaca dalam bentuk mufrad atau tunggal, sehingga bacaannya menjadi amaanatihim, yakni perkara agama dan duniawi yang dipercayakan kepadanya untuk menunaikannya (dan janji mereka) yang telah diambil dari mereka dalam hal tersebut (mereka memeliharanya) benar-benar menjaganya.",[["وَٱلَّذِينَ","Dan orang yang"],["هُمْ","[mereka]"],["لِأَمَـٰنَـٰتِهِمْ","daripada amanah mereka"],["وَعَهْدِهِمْ","dan janji mereka"],["رَٰعُونَ","(adalah) pemerhati"]]],"5408":["(Dan orang-orang yang terhadap kesaksiannya) menurut suatu qiraat dibaca dalam bentuk jamak, sehingga bacaannya menjadi syahaadaatihim (mereka menunaikannya) mereka menegakkannya dan tidak menyembunyikannya.",[["وَٱلَّذِينَ","Dan orang yang"],["هُم","[mereka]"],["بِشَهَـٰدَٰتِهِمْ","dalam kesaksian mereka"],["قَآئِمُونَ","berdiri teguh"]]],"5409":["(Dan orang-orang yang memelihara salatnya) yaitu dengan mengerjakan pada waktunya.",[["وَٱلَّذِينَ","Dan orang yang"],["هُمْ","[mereka]"],["عَلَىٰ","pada"],["صَلَاتِهِمْ","doa mereka"],["يُحَافِظُونَ","jaga jaga"]]],"5410":["(Mereka itu dimasukkan ke dalam surga lagi dimuliakan.)",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["فِى","(akan) masuk"],["جَنَّـٰتٍۢ","Taman-taman"],["مُّكْرَمُونَ","dihormati"]]],"5411":["(Mengapakah orang-orang kami itu ke arahmu) menuju kepadamu (dengan bersegera) lafal muhthi`iina berkedudukan sebagai hal atau kata keterangan keadaan, yakni mereka selalu menatapkan pandangannya ke arahmu secara terus-menerus.",[["فَمَالِ","Jadi apa dengan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["قِبَلَكَ","sebelum kamu"],["مُهْطِعِينَ","(mereka) bersegera"]]],"5412":["(Dari kanan dan dari kiri) dari sebelah kananmu dan sebelah kirimu (dengan berkelompok-kelompok) secara bergerombol dan membentuk lingkaran di sekitarmu. Mereka berbuat demikian seraya mengatakan dengan nada mengejek, \"Sungguh jika mereka, yakni orang-orang yang beriman, masuk ke dalam surga, niscaya kami benar-benar akan masuk ke dalamnya sebelum mereka.\" Maka Allah berfirman:",[["عَنِ","hidup"],["ٱلْيَمِينِ","yang betul"],["وَعَنِ","dan seterusnya"],["ٱلشِّمَالِ","sebelah kiri"],["عِزِينَ","(dalam) kumpulan berasingan"]]],"5413":["(\"Adakah setiap orang dari orang-orang kafir itu ingin masuk ke dalam surga yang penuh dengan kenikmatan?\")",[["أَيَطْمَعُ","Lama"],["كُلُّ","setiap"],["ٱمْرِئٍۢ","orang"],["مِّنْهُمْ","antara mereka"],["أَن","bahawa"],["يُدْخَلَ","dia masuk"],["جَنَّةَ","sebuah Taman"],["نَعِيمٍۢ","(dari) Kegembiraan"]]],"5414":["(Sekali-kali tidak!) kalimat ini merupakan sanggahan terhadap mereka yang ingin masuk surga, padahal mereka kafir. (Sesungguhnya Kami ciptakan mereka) sama dengan selain mereka (dari apa yang mereka ketahui) yakni dari air mani; maka tidak cukup hanya dengan itu mereka mengharapkan surga, karena sesungguhnya surga itu hanya dapat diharapkan bagi orang-orang yang bertakwa.",[["كَلَّآ ۖ","sama sekali tidak"],["إِنَّا","Sesungguhnya Kami"],["خَلَقْنَـٰهُم","[Kami] telah menciptakan mereka"],["مِّمَّا","daripada apa"],["يَعْلَمُونَ","mereka tahu"]]],"5415":["(Maka) huruf laa di sini adalah huruf zaidah (Aku bersumpah dengan nama Rabb yang memiliki arah timur dan arah barat) yang memiliki matahari, bulan dan bintang-bintang lainnya (sesungguhnya Kami benar-benar Maha Kuasa.)",[["فَلَآ","Tetapi tidak"],["أُقْسِمُ","aku bersumpah"],["بِرَبِّ","oleh (Tuhan)."],["ٱلْمَشَـٰرِقِ","(dari) kebangkitan"],["وَٱلْمَغَـٰرِبِ","dan tetapan"],["إِنَّا","bahawa Kami"],["لَقَـٰدِرُونَ","(adalah) pasti Mampu"]]],"5416":["(Untuk mengganti) mereka (dengan kaum yang lebih baik dari mereka, dan sekali-kali Kami tidak dapat dikalahkan) tidak ada yang dapat mengalahkan Kami dalam hal ini.",[["عَلَىٰٓ","[Hidup]"],["أَن","kepada"],["نُّبَدِّلَ","[Kami] ganti"],["خَيْرًۭا","(dengan) lebih baik"],["مِّنْهُمْ","daripada mereka"],["وَمَا","dan bukan"],["نَحْنُ","Kami"],["بِمَسْبُوقِينَ","(adalah) akan lari lebih cepat"]]],"5417":["(Maka biarkanlah mereka) tinggalkanlah mereka (tenggelam) dalam kebatilan (dan bermain-main) dalam keduniaan (sampai mereka menjumpai) menemui (hari yang diancamkan kepada mereka) yang pada hari itu ada azab bagi mereka.",[["فَذَرْهُمْ","Jadi tinggalkan mereka"],["يَخُوضُوا۟","(untuk) bercakap-cakap dengan sia-sia"],["وَيَلْعَبُوا۟","dan menghiburkan diri mereka"],["حَتَّىٰ","sehingga"],["يُلَـٰقُوا۟","mereka berjumpa"],["يَوْمَهُمُ","Hari mereka"],["ٱلَّذِى","yang"],["يُوعَدُونَ","mereka dijanjikan"]]],"5418":["(Yaitu pada hari mereka keluar dari kubur) dari tempat-tempat mereka dikubur (dengan cepat) menuju ke padang Mahsyar tempat mereka dihimpunkan (seakan-akan mereka pergi kepada berhala-berhala) menurut suatu qiraat dibaca nushubin, artinya sesuatu yang dibangun untuk pertanda atau tugu, yang dimaksud adalah berhala-berhala (dengan cepatnya) mereka pergi dengan cepat seakan-akan pergi kepada berhala-berhala mereka.",[["يَوْمَ","(The) Hari"],["يَخْرُجُونَ","mereka akan keluar"],["مِنَ","daripada"],["ٱلْأَجْدَاثِ","kubur"],["سِرَاعًۭا","dengan pantas"],["كَأَنَّهُمْ","seolah-olah mereka (adalah)"],["إِلَىٰ","kepada"],["نُصُبٍۢ","satu matlamat"],["يُوفِضُونَ","menyegerakan"]]],"5419":["(Dalam keadaan hina) atau nista (pandangan mereka karena diliputi) diselimuti (oleh rasa hina. Itulah hari yang dahulunya diancamkan kepada mereka) lafal dzaalika menjadi mubtada, dan lafal-lafal sesudahnya berkedudukan menjadi khabarnya; makna yang dimaksud adalah hari kiamat.",[["خَـٰشِعَةً","Merendah diri"],["أَبْصَـٰرُهُمْ","penglihatan mereka"],["تَرْهَقُهُمْ","akan menutupi mereka"],["ذِلَّةٌۭ ۚ","penghinaan"],["ذَٰلِكَ","Itu"],["ٱلْيَوْمُ","(ialah) hari itu"],["ٱلَّذِى","yang"],["كَانُوا۟","mereka adalah"],["يُوعَدُونَ","dijanjikan"]]],"5420":["(Sesungguhnya Kami telah mengutus Nuh kepada kaumnya, dengan memerintahkan, berilah peringatan) dengan memperingatkan (kepada kaummu sebelum datang kepada mereka) jika mereka tetap tidak mau beriman (azab yang pedih) siksaan yang menyakitkan di dunia dan akhirat.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَا","[Kami] hantar"],["نُوحًا","Nuh"],["إِلَىٰ","kepada"],["قَوْمِهِۦٓ","umatnya"],["أَنْ","bahawa"],["أَنذِرْ","Beri amaran"],["قَوْمَكَ","orang kamu"],["مِن","daripada"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَأْتِيَهُمْ","datang kepada mereka"],["عَذَابٌ","azab"],["أَلِيمٌۭ","yang pedih"]]],"5421":["(Nuh berkata, \"Hai kaumku! Sesungguhnya aku adalah pemberi peringatan yang menjelaskan kepada kalian.\") Jelas peringatannya.",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["إِنِّى","Memang aku"],["لَكُمْ","kepada kamu"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌ","yang nyata"]]],"5422":["(Yaitu hendaknya) artinya aku perintahkan kepada kalian hendaknya (kalian menyembah Allah, bertakwalah kalian kepada-Nya dan taat kepadaku.)",[["أَنِ","Itu"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["وَٱتَّقُوهُ","dan takut kepada-Nya"],["وَأَطِيعُونِ","dan taat kepadaku"]]],"5423":["(Niscaya Allah akan mengampuni sebagian dosa-dosa kalian) huruf min di sini dapat dianggap sebagai huruf zaidah, karena sesungguhnya Islam itu mengampuni semua dosa yang terjadi sebelumnya; yakni semua dosa kalian. Sebagaimana dapat pula dianggap sebagai min yang mengandung makna sebagian, hal ini karena mengecualikan hak-hak yang bersangkutan dengan orang lain (dan menangguhkan kalian) tanpa diazab (sampai kepada waktu yang ditentukan) yaitu ajal kematiannya. (Sesungguhnya ketetapan Allah) yang memutuskan untuk mengazab kalian, jika kalian tidak beriman kepada-Nya (apabila telah datang tidak dapat ditangguhkan, kalau kalian mengetahui) seandainya kalian mengetahui hal tersebut, niscaya kalian beriman kepada-Nya.",[["يَغْفِرْ","Dia akan memaafkan"],["لَكُم","bagi kamu"],["مِّن","[daripada]"],["ذُنُوبِكُمْ","dosa kamu"],["وَيُؤَخِّرْكُمْ","dan memberi kamu tangguh"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّى ۚ","ditentukan"],["إِنَّ","Sesungguhnya"],["أَجَلَ","(the) istilah"],["ٱللَّهِ","(milik) Allah"],["إِذَا","apabila"],["جَآءَ","ia datang"],["لَا","tidak"],["يُؤَخَّرُ ۖ","tertangguh"],["لَوْ","jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"5424":["(Nuh berkata, \"Ya Rabbku! Sesungguhnya aku telah menyeru kaumku malam dan siang) terus-menerus tanpa mengenal waktu.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["إِنِّى","Sesungguhnya aku"],["دَعَوْتُ","dijemput"],["قَوْمِى","bangsaku"],["لَيْلًۭا","malam"],["وَنَهَارًۭا","dan hari"]]],"5425":["(Maka seruanku itu hanyalah menambah mereka lari) dari iman.",[["فَلَمْ","Tetapi tidak"],["يَزِدْهُمْ","meningkat mereka"],["دُعَآءِىٓ","jemputan aku"],["إِلَّا","kecuali"],["فِرَارًۭا","(dalam) penerbangan"]]],"5426":["(Dan sesungguhnya setiap kali aku menyeru mereka, agar Engkau mengampuni mereka, mereka memasukkan anak jari mereka ke dalam telinganya) supaya mereka tidak dapat mendengar seruanku (dan menutupkan bajunya ke mukanya) supaya mereka tidak melihatku (dan mereka tetap) dalam kekafiran mereka (dan menyombongkan diri) tidak mau beriman (dengan sangat.)",[["وَإِنِّى","Dan sesungguhnya, aku"],["كُلَّمَا","setiap masa"],["دَعَوْتُهُمْ","Aku menjemput mereka"],["لِتَغْفِرَ","agar Engkau mengampuni"],["لَهُمْ","mereka"],["جَعَلُوٓا۟","mereka meletakkan"],["أَصَـٰبِعَهُمْ","jari mereka"],["فِىٓ","dalam"],["ءَاذَانِهِمْ","telinga mereka"],["وَٱسْتَغْشَوْا۟","dan menutup diri"],["ثِيَابَهُمْ","(dengan) pakaian mereka"],["وَأَصَرُّوا۟","dan berterusan"],["وَٱسْتَكْبَرُوا۟","dan bersikap sombong"],["ٱسْتِكْبَارًۭا","(dengan) bangga"]]],"5427":["(Kemudian sesungguhnya aku telah menyeru mereka dengan terang-terangan) dengan sekuat suaraku.",[["ثُمَّ","Kemudian"],["إِنِّى","sesungguhnya, aku"],["دَعَوْتُهُمْ","menjemput mereka"],["جِهَارًۭا","secara terbuka"]]],"5428":["(Kemudian sesungguhnya aku telah mengeraskan kepada mereka) suaraku (dan pula telah membisikkan) suaraku atau seruanku (kepada mereka dengan sangat rahasia.)",[["ثُمَّ","Kemudian"],["إِنِّىٓ","sesungguhnya, aku"],["أَعْلَنتُ","diumumkan"],["لَهُمْ","kepada mereka"],["وَأَسْرَرْتُ","dan aku curhat"],["لَهُمْ","kepada mereka"],["إِسْرَارًۭا","secara rahsia"]]],"5429":["(Maka aku katakan, \"Mohonlah ampun kepada Rabb kalian) dari kemusyrikan kalian (sesungguhnya Dia adalah Maha Pengampun.\")",[["فَقُلْتُ","Kemudian aku berkata"],["ٱسْتَغْفِرُوا۟","Minta ampun"],["رَبَّكُمْ","(dari) Tuhanmu"],["إِنَّهُۥ","Sesungguhnya Dia"],["كَانَ","ialah"],["غَفَّارًۭا","Selalu Memaafkan"]]],"5430":["(Niscaya Dia akan mengirimkan hujan) pada saat itu mereka sedang mengalami kekeringan karena terlalu lama tidak ada hujan (kepada kalian dengan lebat) dengan deras.",[["يُرْسِلِ","Dia akan turunkan"],["ٱلسَّمَآءَ","(hujan dari) langit"],["عَلَيْكُم","ke atas kamu"],["مِّدْرَارًۭا","(dalam) kelimpahan"]]],"5431":["(Dan membanyakkan harta dan anak-anak kalian dan mengadakan untuk kalian kebun-kebun) ladang-ladang (dan mengadakan pula bagi kalian sungai-sungai) yang mengalir di dalamnya.",[["وَيُمْدِدْكُم","Dan menyediakan kamu"],["بِأَمْوَٰلٍۢ","dengan kekayaan"],["وَبَنِينَ","dan kanak-kanak"],["وَيَجْعَل","dan buat"],["لَّكُمْ","bagi kamu"],["جَنَّـٰتٍۢ","taman-taman"],["وَيَجْعَل","dan buat"],["لَّكُمْ","bagi kamu"],["أَنْهَـٰرًۭا","sungai-sungai"]]],"5432":["(Mengapa kalian tidak mengharapkan keagungan dari Allah?) tidak mengharapkan Allah mengangkat derajat kalian, agar kalian beriman kepada-Nya.",[["مَّا","Apa"],["لَكُمْ","(adalah) untuk kamu"],["لَا","tidak"],["تَرْجُونَ","kamu sifatkan"],["لِلَّهِ","kepada Allah"],["وَقَارًۭا","kemegahan"]]],"5433":["(Padahal sesungguhnya Dia telah menciptakan kalian dalam beberapa tingkatan kejadian) lafal athwaaran bentuk jamak dari lafal thaurun, artinya tahap; yakni mulai dari tahap air mani terus menjadi darah kental atau alaqah, hingga menjadi manusia yang sempurna bentuknya. Dan memperhatikan kejadian makhluk-Nya seharusnya menuntun mereka iman kepada yang telah menciptakannya.",[["وَقَدْ","Dan sesungguhnya"],["خَلَقَكُمْ","Dia mencipta kamu"],["أَطْوَارًا","(dalam) peringkat"]]],"5434":["(Tidakkah kalian perhatikan) kalian lihat (bagaimana Allah telah menciptakan tujuh langit bertingkat-tingkat?) sebagian di antaranya berada di atas sebagian yang lain.",[["أَلَمْ","Jangan"],["تَرَوْا۟","kamu lihat"],["كَيْفَ","bagaimana"],["خَلَقَ","memang mencipta"],["ٱللَّهُ","Allah"],["سَبْعَ","(yang) tujuh"],["سَمَـٰوَٰتٍۢ","syurga"],["طِبَاقًۭا","(dalam) lapisan"]]],"5435":["(Dan Allah menciptakan padanya bulan) yaitu pada langit yang paling terdekat di antara keseluruhan langit itu (sebagai cahaya dan menjadikan matahari sebagai pelita?) yang memancarkan sinar terang yang jauh lebih kuat daripada sinar bulan.",[["وَجَعَلَ","Dan dibuat"],["ٱلْقَمَرَ","bulan"],["فِيهِنَّ","di dalamnya"],["نُورًۭا","sebuah cahaya"],["وَجَعَلَ","dan dibuat"],["ٱلشَّمْسَ","matahari"],["سِرَاجًۭا","sebuah lampu"]]],"5436":["(Dan Allah menumbuhkan kalian) Dia telah menciptakan kalian (dari tanah) karena Dia telah menciptakan bapak moyang kalian, yaitu Nabi Adam daripadanya (dengan sebaik-baiknya.)",[["وَٱللَّهُ","Dan Allah"],["أَنۢبَتَكُم","telah menyebabkan kamu berkembang"],["مِّنَ","daripada"],["ٱلْأَرْضِ","bumi"],["نَبَاتًۭا","(sebagai) pertumbuhan"]]],"5437":["(Kemudian Dia mengembalikan kalian ke dalam tanah) dalam keadaan terkubur di dalamnya (dan mengeluarkan kalian) dari dalamnya menjadi hidup kembali pada hari kiamat (dengan sebenar-benarnya.)",[["ثُمَّ","Kemudian"],["يُعِيدُكُمْ","Dia akan mengembalikan kamu"],["فِيهَا","ke dalamnya"],["وَيُخْرِجُكُمْ","dan membawa kamu keluar"],["إِخْرَاجًۭا","(yang baru) melahirkan"]]],"5438":["(Dan Allah menjadikan bagi kalian bumi sebagai hamparan) yakni dalam keadaan terhampar.",[["وَٱللَّهُ","Dan Allah"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَرْضَ","bumi"],["بِسَاطًۭا","suatu hamparan"]]],"5439":["(Supaya kalian menempuh padanya jalan-jalan) atau menempuh jalan-jalan (yang luas.\") yang lebar.",[["لِّتَسْلُكُوا۟","Supaya kamu boleh pergi bersama"],["مِنْهَا","di dalamnya"],["سُبُلًۭا","(dalam) laluan"],["فِجَاجًۭا","luas"]]],"5440":["(Nuh berkata, \"Ya Rabbku! Sesungguhnya mereka telah mendurhakaiku, dan mereka telah mengikuti) orang-orang yang hina dan orang-orang yang miskin di antara mereka (orang-orang yang harta dan anak-anaknya tidak menambah kepadanya) maksudnya orang-orang yang rendah dan orang-orang miskin dari kalangan kaum Nabi Nuh itu, lebih senang mengikuti pemimpin-pemimpin yang diberi nikmat akan hal-hal tersebut, yakni banyak harta dan anaknya. Lafal wuldun dengan didamahkan huruf waunya dan sukun pada lamnya, atau waladun dengan difatahkan kedua-duanya; kalau bentuk yang pertama menurut suatu pendapat, bahwa itu adalah bentuk jamak dari lafal waladun. Dalam arti kata disamakan dengan wazan lafal khasyabun yang jamaknya khusybun. Menurut pendapat yang lain, lafal wuldun mempunyai arti yang sama dengan lafal waladun, karena wazannya dianggap sama dengan lafal bukhlun dan bakhiilun (melainkan kerugian belaka) yaitu keangkaramurkaan dan kekafiran.",[["قَالَ","Berkata"],["نُوحٌۭ","Nuh"],["رَّبِّ","Tuhanku"],["إِنَّهُمْ","Sesungguhnya mereka"],["عَصَوْنِى","menderhaka kepadaku"],["وَٱتَّبَعُوا۟","dan diikuti"],["مَن","(yang) siapa"],["لَّمْ","(tidak) tidak"],["يَزِدْهُ","tambah dia"],["مَالُهُۥ","kekayaannya"],["وَوَلَدُهُۥٓ","dan anak-anaknya"],["إِلَّا","kecuali"],["خَسَارًۭا","(dalam) kerugian"]]],"5441":["(Dan mereka melakukan tipu daya) yaitu para pemimpin mereka (yang amat besar.\") Tipu daya mereka sangat besar, yaitu mereka telah mendustakan Nabi Nuh dan menyakitinya serta menyakiti orang-orang yang beriman kepadanya.",[["وَمَكَرُوا۟","Dan mereka telah merancang"],["مَكْرًۭا","sesuatu rancangan"],["كُبَّارًۭا","yang besar"]]],"5442":["(Dan mereka berkata) kepada orang-orang yang menjadi bawahan mereka (\"Jangan sekali-kali kalian meninggalkan tuhan-tuhan sesembahan kalian dan jangan pula sekali-kali kalian meninggalkan wadd) dapat dibaca waddan dan wuddan (dan jangan pula suwa', yaghuts, ya'uq dan nasr\") nama-nama tersebut adalah nama-nama berhala-berhala mereka.",[["وَقَالُوا۟","Dan mereka berkata"],["لَا","Jangan"],["تَذَرُنَّ","pergi"],["ءَالِهَتَكُمْ","tuhan-tuhan kamu"],["وَلَا","dan jangan"],["تَذَرُنَّ","pergi"],["وَدًّۭا","Wadd"],["وَلَا","dan bukan"],["سُوَاعًۭا","Suwa"],["وَلَا","dan bukan"],["يَغُوثَ","Yaguth"],["وَيَعُوقَ","dan Yauq"],["وَنَسْرًۭا","dan Nasr"]]],"5443":["(Dan sesungguhnya mereka telah menyesatkan) dengan nama-nama tersebut (kebanyakan manusia) karena mereka telah memerintahkan manusia untuk menyembahnya (dan janganlah Engkau tambahkan bagi orang-orang yang lalim itu selain kesesatan) ayat ini diathafkan kepada lafal qad adhalluu, yakni merupakan doa Nabi Nuh setelah Allah mewahyukan kepadanya, bahwasanya sekali-kali tidak ada orang yang mau beriman di antara kaummu, melainkan orang-orang yang telah beriman saja.",[["وَقَدْ","Dan sesungguhnya"],["أَضَلُّوا۟","mereka telah menyesatkan"],["كَثِيرًۭا ۖ","ramai"],["وَلَا","Dan tidak"],["تَزِدِ","bertambah"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["إِلَّا","kecuali"],["ضَلَـٰلًۭا","(dalam) kesilapan"]]],"5444":["(Disebabkan) huruf maa di sini adalah huruf shilah atau penghubung (kesalahan-kesalahan mereka) menurut suatu qiraat dibaca khathii'aatihim dengan memakai huruf hamzah sesudah huruf ya (mereka ditenggelamkan) oleh banjir besar (lalu dimasukkan ke dalam neraka) yaitu mereka diazab sesudah mereka ditenggelamkan di bawah air (maka mereka tidak dapat menemukan selain) selain daripada (Allah, seseorang pun yang menolong mereka) yang dapat melindungi mereka dari azab.",[["مِّمَّا","Kerana"],["خَطِيٓـَٔـٰتِهِمْ","dosa mereka"],["أُغْرِقُوا۟","mereka lemas"],["فَأُدْخِلُوا۟","kemudian disuruh masuk"],["نَارًۭا","(the) Api"],["فَلَمْ","dan bukan"],["يَجِدُوا۟","mereka jumpa"],["لَهُم","untuk diri mereka sendiri"],["مِّن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَنصَارًۭا","mana-mana pembantu"]]],"5445":["(Nuh berkata, \"Ya Rabbku! Janganlah Engkau biarkan seorang pun di antara orang-orang kafir itu tinggal di atas bumi) bertempat tinggal, makna yang dimaksud ialah jangan biarkan seorang pun di antara mereka.",[["وَقَالَ","Dan berkata"],["نُوحٌۭ","Nuh"],["رَّبِّ","Tuhanku"],["لَا","Jangan"],["تَذَرْ","pergi"],["عَلَى","pada"],["ٱلْأَرْضِ","bumi"],["مِنَ","sebarang"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"],["دَيَّارًا","(sebagai) penduduk"]]],"5446":["(Sesungguhnya jika Engkau biarkan mereka tinggal, niscaya mereka akan menyesatkan hamba-hamba-Mu, dan mereka tidak akan melahirkan selain anak yang berbuat maksiat lagi sangat kafir) lafal faajiran dan kaffaaran berasal dari yafjuru dan yakfuru. Nabi Nuh berdoa demikian setelah ada wahyu mengenai keadaan mereka yang telah disebutkan tadi yakni, bahwa mereka tidak akan beriman, kecuali hanya orang-orang yang telah beriman kepadanya.",[["إِنَّكَ","Sesungguhnya, Engkau"],["إِن","jika"],["تَذَرْهُمْ","Kamu tinggalkan mereka"],["يُضِلُّوا۟","mereka akan menyesatkan"],["عِبَادَكَ","hambamu"],["وَلَا","dan bukan"],["يَلِدُوٓا۟","mereka akan beranak"],["إِلَّا","kecuali"],["فَاجِرًۭا","seorang yang jahat"],["كَفَّارًۭا","seorang kafir"]]],"5447":["(Ya Rabbku! Ampunilah aku, ibu bapakku) kedua orang tua Nabi Nuh termasuk orang-orang yang beriman (orang yang masuk ke dalam rumahku) atau mesjidku (dengan beriman, dan semua orang yang beriman laki-laki dan perempuan) hingga hari kiamat nanti (dan janganlah Engkau tambahkan kepada orang-orang yang zalim itu selain kebinasaan.\") Atau kehancuran, akhirnya mereka benar-benar dibinasakan.",[["رَّبِّ","Tuhanku"],["ٱغْفِرْ","maafkan"],["لِى","aku"],["وَلِوَٰلِدَىَّ","dan ibu bapa aku"],["وَلِمَن","dan sesiapa"],["دَخَلَ","masuk"],["بَيْتِىَ","rumah aku"],["مُؤْمِنًۭا","seorang yang beriman"],["وَلِلْمُؤْمِنِينَ","dan orang-orang yang beriman"],["وَٱلْمُؤْمِنَـٰتِ","dan wanita yang beriman"],["وَلَا","Dan jangan"],["تَزِدِ","bertambah"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["إِلَّا","kecuali"],["تَبَارًۢا","(dalam) kemusnahan"]]],"5448":["(Katakanlah) hai Muhammad! (\"Telah diwahyukan kepadaku) maksudnya aku telah diberitahu oleh Allah melalui wahyu-Nya (bahwasanya) dhamir yang terdapat pada lafal annahu ini adalah dhamir sya'n (telah mendengarkan) bacaan Alquranku (sekumpulan jin.\") yakni jin dari Nashibin; demikian itu terjadi sewaktu Nabi saw. sedang melakukan salat Subuh di lembah Nakhlah, yang terletak di tengah-tengah antara Mekah dan Thaif. Jin itulah yang disebutkan di dalam firman-Nya, \"Dan (ingatlah) ketika Kami hadapkan serombongan jin kepadamu.\" (Q.S. Al-Ahqaf 29) (lalu mereka berkata) kepada kaum mereka setelah mereka kembali kepada kaumnya: (\"Sesungguhnya kami telah mendengarkan Alquran yang menakjubkan) artinya mereka takjub akan kefasihan bahasanya dan kepadatan makna-makna yang dikandungnya, serta hal-hal lainnya.",[["قُلْ","Katakanlah"],["أُوحِىَ","Ia telah didedahkan"],["إِلَىَّ","kepada aku"],["أَنَّهُ","bahawa"],["ٱسْتَمَعَ","mendengar"],["نَفَرٌۭ","satu kumpulan"],["مِّنَ","daripada"],["ٱلْجِنِّ","jin"],["فَقَالُوٓا۟","dan mereka berkata"],["إِنَّا","Sesungguhnya kami"],["سَمِعْنَا","didengari"],["قُرْءَانًا","sebuah Al-Quran"],["عَجَبًۭا","menakjubkan"]]],"5449":["(Yang memberi petunjuk kepada jalan yang benar) yaitu kepada keimanan dan kebenaran (lalu kami beriman kepadanya. Dan kami sekali-kali tidak akan mempersekutukan) sesudah hari ini (seorang pun dengan Rabb kami.)",[["يَهْدِىٓ","Ia membimbing"],["إِلَى","kepada"],["ٱلرُّشْدِ","cara yang betul"],["فَـَٔامَنَّا","jadi kami beriman"],["بِهِۦ ۖ","di dalamnya"],["وَلَن","dan tidak pernah"],["نُّشْرِكَ","kita akan bergaul"],["بِرَبِّنَآ","dengan Tuhan kita"],["أَحَدًۭا","sesiapa sahaja"]]],"5450":["(Dan bahwasanya) dhamir yang terdapat pada ayat ini adalah dhamir sya'n, demikian pula pada dua tempat lain sesudahnya (Maha Tinggi Kebesaran Rabb kami) Maha Suci kebesaran dan keagungan-Nya dari apa-apa yang dinisbatkan kepada-Nya (Dia tidak beristri) tidak mempunyai istri (dan tidak pula beranak.)",[["وَأَنَّهُۥ","Dan bahawa Dia"],["تَعَـٰلَىٰ","Maha Tinggi adalah"],["جَدُّ","(yang) Yang Mulia"],["رَبِّنَا","(dari) Tuhan kami"],["مَا","tidak"],["ٱتَّخَذَ","Dia telah mengambil"],["صَـٰحِبَةًۭ","seorang isteri"],["وَلَا","dan bukan"],["وَلَدًۭا","seorang anak lelaki"]]],"5451":["(Dan bahwasanya orang yang kurang akal daripada kami selalu mengatakan) maksudnya orang yang bodoh di antara kami (perkataan yang melampaui batas terhadap Allah) dusta yang berlebihan, yaitu dengan menyifati Allah punya istri dan anak.",[["وَأَنَّهُۥ","Dan bahawa dia"],["كَانَ","dulu"],["يَقُولُ","bercakap"],["سَفِيهُنَا","orang bodoh di kalangan kita"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["شَطَطًۭا","pelanggaran yang berlebihan"]]],"5452":["(Dan sesungguhnya kami mengira, bahwa) huruf an di sini adalah bentuk takhfif dari anna, yakni annahu (manusia dan jin sekali-kali tidak akan mengatakan perkataan yang dusta terhadap Allah) yakni menyifati-Nya dengan hal-hal tersebut hingga kami dapat buktikan kedustaan mereka dalam hal itu. Allah berfirman:",[["وَأَنَّا","Dan bahawa kita"],["ظَنَنَّآ","terfikir"],["أَن","bahawa"],["لَّن","tidak pernah"],["تَقُولَ","akan berkata"],["ٱلْإِنسُ","kaum lelaki"],["وَٱلْجِنُّ","dan jin"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًۭا","sebarang pembohongan"]]],"5453":["(Dan bahwasanya ada beberapa orang laki-laki di antara manusia meminta perlindungan) memohon perlindungan (kepada beberapa laki-laki di antara jin) di dalam perjalanan mereka sewaktu mereka beristirahat di tempat yang menyeramkan, lalu masing-masing orang mengatakan, aku berlindung kepada penunggu tempat ini dari gangguan penunggu lainnya yang jahat (maka jin-jin itu menambah bagi mereka) dengan permintaan perlindungannya kepada jin-jin itu (dosa dan kesalahan) karena mereka mengatakan, bahwa kami telah dilindungi oleh jin anu dan orang anu.",[["وَأَنَّهُۥ","Dan bahawa"],["كَانَ","(ada) ada"],["رِجَالٌۭ","lelaki"],["مِّنَ","antara"],["ٱلْإِنسِ","manusia"],["يَعُوذُونَ","yang mencari perlindungan"],["بِرِجَالٍۢ","dalam (kaum) lelaki"],["مِّنَ","daripada"],["ٱلْجِنِّ","jin"],["فَزَادُوهُمْ","maka mereka menambahnya"],["رَهَقًۭا","(dalam) beban"]]],"5454":["(Dan sesungguhnya mereka) yakni jin-jin itu (menyangka sebagaimana sangkaan kalian) hai manusia (bahwa) bentuk takhfif dari anna, asalnya annahu (Allah sekali-kali tidak akan membangkitkan seorang pun.\") sesudah matinya.",[["وَأَنَّهُمْ","Dan bahawa mereka"],["ظَنُّوا۟","terfikir"],["كَمَا","seperti"],["ظَنَنتُمْ","kamu fikir"],["أَن","bahawa"],["لَّن","tidak pernah"],["يَبْعَثَ","akan menaikkan"],["ٱللَّهُ","Allah"],["أَحَدًۭا","sesiapa sahaja"]]],"5455":["Jin mengatakan: (\"Dan sesungguhnya kami telah mencoba menyentuh langit) maksudnya kami telah bermaksud untuk mencuri pendengaran di langit (maka kami menjumpainya penuh dengan penjaga) para malaikat (yang kuat dan panah-panah api) yakni bintang-bintang yang membakar; hal ini terjadi setelah Nabi saw. diutus menjadi rasul.",[["وَأَنَّا","Dan bahawa kita"],["لَمَسْنَا","cuba disentuh"],["ٱلسَّمَآءَ","syurga itu"],["فَوَجَدْنَـٰهَا","tetapi kami menemuinya"],["مُلِئَتْ","diisi (dengan)"],["حَرَسًۭا","pengawal"],["شَدِيدًۭا","teruk"],["وَشُهُبًۭا","dan api yang menyala-nyala"]]],"5456":["(Dan sesungguhnya kami dahulu) sebelum Nabi saw. diutus (dapat menduduki beberapa tempat di langit itu untuk mendengar-dengarkan) berita-beritanya dan untuk mencurinya. (Tetapi sekarang barang siapa yang mencoba mendengar-dengarkan, seperti itu, tentu akan menjumpai panah api yang mengintai) panah-panah api yang terdiri dari meteor-meteor itu telah mengintainya dalam keadaan siap untuk memburunya.",[["وَأَنَّا","Dan bahawa kita"],["كُنَّا","dulu"],["نَقْعُدُ","duduk"],["مِنْهَا","ada dalam"],["مَقَـٰعِدَ","jawatan"],["لِلسَّمْعِ ۖ","untuk pendengaran"],["فَمَن","tetapi (dia) yang"],["يَسْتَمِعِ","mendengar"],["ٱلْـَٔانَ","sekarang"],["يَجِدْ","akan jumpa"],["لَهُۥ","baginya"],["شِهَابًۭا","api yang menyala"],["رَّصَدًۭا","menunggu"]]],"5457":["(Dan sesungguhnya kami tidak mengetahui apakah keburukan yang dikehendaki) sesudah terjaganya langit dari pencurian pendengaran (bagi orang yang di bumi ataukah Rabb mereka menghendaki kebaikan bagi mereka) lafal rasyadan artinya khairan, yaitu kebaikan.",[["وَأَنَّا","Dan bahawa kita"],["لَا","tidak"],["نَدْرِىٓ","kita tahu"],["أَشَرٌّ","sama ada jahat"],["أُرِيدَ","adalah bertujuan"],["بِمَن","untuk (mereka) yang"],["فِى","(ada) dalam"],["ٱلْأَرْضِ","bumi"],["أَمْ","atau"],["أَرَادَ","berniat"],["بِهِمْ","bagi mereka"],["رَبُّهُمْ","Tuhan mereka"],["رَشَدًۭا","jalan yang betul"]]],"5458":["(Dan sesungguhnya di antara kami ada orang-orang yang saleh) sesudah mendengarkan Alquran ini (dan di antara kami ada pula yang tidak demikian halnya) ada kaum yang tidak saleh. (Adalah kami menempuh jalan yang berbeda-beda) terdiri dari golongan yang berbeda-beda; ada yang muslim dan ada pula yang kafir.",[["وَأَنَّا","Dan bahawa [kita]"],["مِنَّا","antara kita"],["ٱلصَّـٰلِحُونَ","(adalah) orang-orang yang soleh"],["وَمِنَّا","dan di antara kita"],["دُونَ","(adalah) selain daripada"],["ذَٰلِكَ ۖ","bahawa"],["كُنَّا","Kami"],["طَرَآئِقَ","(sedang dalam) jalan"],["قِدَدًۭا","berbeza"]]],"5459":["(Dan sesungguhnya kami yakin, bahwa) huruf an ini adalah bentuk takhfif dari anna, asalnya annahu (kami sekali-kali tidak akan dapat melepaskan diri, dari kekuasaan, Allah di muka bumi, dan sekali-kali tidak pula dapat melepaskan diri daripada-Nya dengan lari) maksudnya, kami tidak akan dapat menyelamatkan diri daripada-Nya, apakah kami berada di bumi atau kami lari dari bumi menuju ke langit.",[["وَأَنَّا","Dan bahawa kita"],["ظَنَنَّآ","[kita] sudah pasti"],["أَن","bahawa"],["لَّن","tidak pernah"],["نُّعْجِزَ","kita akan menyebabkan kegagalan"],["ٱللَّهَ","(kepada) Allah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَن","dan tidak pernah"],["نُّعْجِزَهُۥ","kita boleh lari dari Dia"],["هَرَبًۭا","(dengan) penerbangan"]]],"5460":["(Dan sesungguhnya kami tatkala mendengar petunjuk) yakni Alquran (kami beriman kepadanya. Barang siapa beriman kepada Rabbnya, maka ia tidak usah takut) sesudah lafal yakhaafu diperkirakan adanya lafal huwa (akan kekurangan) pengurangan pahala kebaikannya (dan tidak pula takut akan dizalimi) diperlakukan secara zalim, yaitu dengan penambahan kesalahan dan dosanya.",[["وَأَنَّا","Dan bahawa [kita]"],["لَمَّا","apabila"],["سَمِعْنَا","kami dengar"],["ٱلْهُدَىٰٓ","Petunjuk"],["ءَامَنَّا","kami beriman"],["بِهِۦ ۖ","di dalamnya"],["فَمَن","Dan sesiapa"],["يُؤْمِنۢ","beriman"],["بِرَبِّهِۦ","pada Tuhannya"],["فَلَا","maka tidak"],["يَخَافُ","dia akan takut"],["بَخْسًۭا","sebarang kerugian"],["وَلَا","dan bukan"],["رَهَقًۭا","sebarang beban"]]],"5461":["(Dan sesungguhnya di antara kami ada orang-orang yang taat dan ada pula orang-orang yang menyimpang dari kebenaran) yakni melewati batas disebabkan kekafiran mereka. (Barang siapa yang taat, maka mereka itu benar-benar telah memilih jalan petunjuk) atau menuju ke jalan hidayah.",[["وَأَنَّا","Dan bahawa kita"],["مِنَّا","antara kita"],["ٱلْمُسْلِمُونَ","(adalah) orang Islam"],["وَمِنَّا","dan di antara kita"],["ٱلْقَـٰسِطُونَ ۖ","(adalah) tidak adil"],["فَمَنْ","Dan sesiapa"],["أَسْلَمَ","menyerahkan"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["تَحَرَّوْا۟","telah mencari"],["رَشَدًۭا","(jalan) yang benar"]]],"5462":["(Adapun orang-orang yang menyimpang dari kebenaran, maka mereka menjadi kayu api bagi neraka Jahanam.\") atau sebagai bahan bakarnya. Dhamir anna dan annahum serta annahu yang terdapat pada dua belas tempat kembali kepada jin. Dan firman-Nya, \"Wa innaa minnal muslimuuna wa minnal qaasithuuna,\" dibaca kasrah huruf hamzahnya, yaitu innaa berarti merupakan jumlah isti'naf atau kalimat baru. Jika dibaca fathah yaitu menjadi anna berarti kedudukannya disamakan dengan kalimat-kalimat sebelumnya.",[["وَأَمَّا","Dan untuk"],["ٱلْقَـٰسِطُونَ","yang zalim"],["فَكَانُوا۟","mereka akan menjadi"],["لِجَهَنَّمَ","untuk Neraka"],["حَطَبًۭا","kayu api"]]],"5463":["Allah swt. berfirman mengenai orang-orang kafir Mekah: (Dan bahwasanya) mereka; adalah bentuk takhfif dari anna, sedangkan isimnya tidak disebutkan, yakni annahum, artinya, bahwasanya mereka; diathafkan kepada lafal annahus tama`a (jika mereka tetap berjalan lurus di atas jalan itu) yaitu agama Islam (benar-benar Kami akan memberi minum kepada mereka air yang banyak) dari langit. Demikian itu setelah hujan dihentikan dari mereka selama tujuh tahun.",[["وَأَلَّوِ","Dan itu jika"],["ٱسْتَقَـٰمُوا۟","mereka telah kekal"],["عَلَى","pada"],["ٱلطَّرِيقَةِ","Jalan"],["لَأَسْقَيْنَـٰهُم","sesungguhnya Kami (akan) memberi mereka minum"],["مَّآءً","air"],["غَدَقًۭا","(dalam) kelimpahan"]]],"5464":["(Untuk Kami beri cobaan kepada mereka) untuk Kami uji mereka (dengan melaluinya) hingga Kami mengetahui bagaimana kesyukuran mereka, dengan pengetahuan yang nyata. (Dan barang siapa yang berpaling dari peringatan Rabbnya) yakni Alquran (niscaya Kami akan memasukkannya) (ke dalam azab yang amat berat.)",[["لِّنَفْتِنَهُمْ","Supaya Kami menguji mereka"],["فِيهِ ۚ","di dalamnya"],["وَمَن","Dan sesiapa"],["يُعْرِضْ","berpaling"],["عَن","daripada"],["ذِكْرِ","Zikir itu"],["رَبِّهِۦ","(dari) Tuhannya"],["يَسْلُكْهُ","Dia akan menyuruhnya masuk"],["عَذَابًۭا","azab"],["صَعَدًۭا","teruk"]]],"5465":["(Dan sesungguhnya mesjid-mesjid itu) atau tempat-tempat salat itu (adalah kepunyaan Allah. Maka janganlah kalian menyembah) di dalamnya (seseorang pun di samping Allah) seumpamanya kalian berbuat kemusyrikan di dalamnya, sebagaimana yang telah dilakukan oleh orang-orang Yahudi dan orang-orang Nasrani, yaitu apabila mereka memasuki gereja dan sinagog mereka, maka mereka menyekutukan-Nya.",[["وَأَنَّ","Dan bahawa"],["ٱلْمَسَـٰجِدَ","masjid-masjid"],["لِلَّهِ","(adalah) untuk Allah"],["فَلَا","jadi (jangan)"],["تَدْعُوا۟","panggilan"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["أَحَدًۭا","sesiapa sahaja"]]],"5466":["(Dan bahwasanya) dapat dibaca annahu dan innahu; juga merupakan kalimat baru, sedangkan dhamir yang ada ialah dhamir sya'n (tatkala hamba Allah berdiri) yakni Nabi Muhammad saw. (menyembah-Nya) beribadah kepada-Nya di lembah Nakhl (hampir saja mereka) yakni jin-jin yang mendengarkan bacaan Alquran itu (desak-mendesak mengerumuninya) yaitu sebagian di antara mereka menindih sebagian yang lain berjejal-jejal karena keinginan mereka yang sangat untuk mendengarkan bacaan Alquran. Lafal libadan dapat pula dibaca lubadan; dan merupakan bentuk jamak dari lubdatun.",[["وَأَنَّهُۥ","Dan bahawa"],["لَمَّا","apabila"],["قَامَ","berdiri"],["عَبْدُ","(yang) hamba"],["ٱللَّهِ","(milik) Allah"],["يَدْعُوهُ","menyeru (kepada)Nya"],["كَادُوا۟","mereka hampir"],["يَكُونُونَ","menjadi"],["عَلَيْهِ","sekeliling dia"],["لِبَدًۭا","jisim yang dipadatkan"]]],"5467":["(Berkatalah dia) Nabi Muhammad berkata sebagai jawabannya terhadap orang-orang kafir yang mengatakan kepadanya, kembalilah kamu dari apa yang kamu lakukan sekarang ini. Akan tetapi menurut qiraat yang lain lafal qaala dibaca qul, artinya katakanlah: (\"Sesungguhnya aku hanya menyembah Rabbku) sebagai Tuhanku (dan aku tidak mempersekutukan sesuatu pun dengan-Nya.\")",[["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أَدْعُوا۟","Aku menyeru"],["رَبِّى","Tuhanku"],["وَلَآ","dan bukan"],["أُشْرِكُ","aku kaitkan"],["بِهِۦٓ","dengan Dia"],["أَحَدًۭا","sesiapa sahaja"]]],"5468":["(Katakanlah, \"Sesungguhnya aku tidak kuasa untuk mendatangkan sesuatu kemudaratan pun kepada kalian) atau keburukan (dan tidak pula sesuatu kemanfaatan.\") Atau kebaikan.",[["قُلْ","Katakanlah"],["إِنِّى","Sesungguhnya aku"],["لَآ","jangan"],["أَمْلِكُ","memiliki"],["لَكُمْ","bagi kamu"],["ضَرًّۭا","sebarang kemudaratan"],["وَلَا","dan bukan"],["رَشَدًۭا","jalan yang betul"]]],"5469":["(Katakanlah, \"Sesungguhnya aku sekali-kali tiada yang dapat melindungiku dari Allah) dari azab-Nya jika aku mendurhakai-Nya (seseorang pun, dan sekali-kali aku tiada akan memperoleh selain dari-Nya) atau selain-Nya (tempat untuk berlindung) maksudnya, tempat aku berlindung.",[["قُلْ","Katakanlah"],["إِنِّى","Sesungguhnya aku"],["لَن","tidak pernah"],["يُجِيرَنِى","boleh melindungi aku"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["أَحَدٌۭ","sesiapa sahaja"],["وَلَنْ","dan tidak pernah"],["أَجِدَ","boleh aku cari"],["مِن","daripada"],["دُونِهِۦ","selain Dia"],["مُلْتَحَدًا","mana-mana tempat perlindungan"]]],"5470":["(Akan tetapi, aku hanya, menyampaikan peringatan) makna yang dikandung dalam lafal ini merupakan pengecualian atau istitsna dari maf'ul atau objek yang terdapat di dalam lafal amliku. Yakni aku tiada memiliki bagi kalian selain hanya menyampaikan peringatan (dari Allah) yang aku terima dari-Nya (dan risalah-Nya) lafal ini diathafkan kepada lafal balaaghan dan lafal-lafal yang terdapat di antara mustatsna minhu dan istitsna merupakan jumlah mu`taridhah atau kalimat sisipan yang berfungsi untuk mengukuhkan makna tiada memiliki. (Dan barang siapa yang mendurhakai Allah dan Rasul-Nya) dalam hal ketauhidan, lalu ia tidak beriman (maka sesungguhnya baginya neraka Jahanam, mereka kekal) lafal khaalidiina adalah hal atau kata keterangan keadaan dari dhamir man. Sehubungan dengan lafal lahuu dhamir yang ada padanya adalah untuk menyesuaikan maknanya dengan lafal man. Lafal khaalidiina ini merupakan hal dari lafal yang tidak disebutkan, lengkapnya mereka memasukinya dalam keadaan pasti kekal (di dalamnya untuk selama-lamanya.)",[["إِلَّا","Tetapi"],["بَلَـٰغًۭا","(the) pemberitahuan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَرِسَـٰلَـٰتِهِۦ ۚ","dan Risalah-risalahNya"],["وَمَن","Dan sesiapa"],["يَعْصِ","ingkar"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["فَإِنَّ","maka sesungguhnya"],["لَهُۥ","baginya"],["نَارَ","(ialah) Api"],["جَهَنَّمَ","(dari) Neraka"],["خَـٰلِدِينَ","(mereka akan) tinggal"],["فِيهَآ","di dalamnya"],["أَبَدًا","selama-lamanya"]]],"5471":["(Sehingga apabila mereka melihat) lafal hattaa di sini mengandung makna ibtidaiyah atau permulaan, dan sekaligus mengandung makna ghayah atau tujuan terakhir dari lafal yang diperkirakan sebelumnya; lengkapnya, mereka masih tetap berada di dalam kekafirannya sehingga mereka melihat (apa yang diancamkan kepada mereka) yaitu azab (maka mereka akan mengetahui) manakala azab itu datang menimpa mereka, yaitu dalam perang Badar atau pada hari kiamat nanti (siapakah yang lebih lemah penolongnya dan lebih sedikit bilangannya.\") maksudnya pembantu-pembantunya, apakah mereka ataukah orang-orang mukmin; penafsiran ini menurut pendapat yang pertama, yaitu dalam perang Badar. Aku ataukah mereka; penafsiran ini berdasarkan pendapat yang kedua, yaitu pada hari kiamat nanti. Sebagian di antara mereka, atau di antara orang-orang kafir itu ada yang bertanya, kapankah datangnya ancaman yang dijanjikan itu? Kemudian turunlah firman selanjutnya, yaitu:",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["رَأَوْا۟","mereka lihat"],["مَا","apa"],["يُوعَدُونَ","mereka dijanjikan"],["فَسَيَعْلَمُونَ","maka mereka akan tahu"],["مَنْ","yang"],["أَضْعَفُ","(adalah) lebih lemah"],["نَاصِرًۭا","(dalam) pembantu"],["وَأَقَلُّ","dan lebih sedikit"],["عَدَدًۭا","(dalam) nombor"]]],"5472":["(Katakanlah, \"Tiadalah) tidaklah (aku mengetahui apa yang diancamkan kepada kalian itu dekat) artinya, apakah azab itu dekat (ataukah Rabbku menjadikan bagi kedatangannya masa yang panjang?) Yang tidak diketahui oleh siapa pun kecuali hanya Dia.",[["قُلْ","Katakanlah"],["إِنْ","Tidak"],["أَدْرِىٓ","aku tahu"],["أَقَرِيبٌۭ","sama ada dekat"],["مَّا","apa"],["تُوعَدُونَ","kamu dijanjikan"],["أَمْ","atau (sama ada)"],["يَجْعَلُ","akan melantik"],["لَهُۥ","baginya"],["رَبِّىٓ","Tuhanku"],["أَمَدًا","istilah (jauh)."]]],"5473":["(Dia adalah Tuhan Yang Mengetahui yang gaib) mengetahui semua hal yang gaib di mata hamba-hamba-Nya (maka Dia tidak memperlihatkan) tidak menampakkan (kepada seorang pun tentang yang gaib itu) di antara manusia ini.",[["عَـٰلِمُ","(Yang) Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["فَلَا","jadi tidak"],["يُظْهِرُ","Dia mendedahkan"],["عَلَىٰ","daripada"],["غَيْبِهِۦٓ","ghaibnya"],["أَحَدًا","(kepada) sesiapa sahaja"]]],"5474":["(Kecuali kepada rasul yang diridai-Nya, maka sesungguhnya Dia) di samping Dia memperhatikan hal yang gaib kepada Rasul-Nya sesuai dengan apa yang dikehendaki-Nya sebagai mukjizat bagi rasul itu (mengadakan) menjadikan dan memberlakukan (di muka) rasul itu (dan di belakangnya penjaga-penjaga) yang terdiri dari malaikat-malaikat untuk menjaganya, hingga rasul itu dapat menyampaikan hal tersebut, di antara sejumlah wahyu-wahyu-Nya kepada manusia.",[["إِلَّا","Kecuali"],["مَنِ","yang"],["ٱرْتَضَىٰ","Dia telah meluluskan"],["مِن","daripada"],["رَّسُولٍۢ","seorang Rasul"],["فَإِنَّهُۥ","dan sesungguhnya, Dia"],["يَسْلُكُ","membuat untuk berarak"],["مِنۢ","daripada"],["بَيْنِ","sebelum"],["يَدَيْهِ","dia"],["وَمِنْ","dan daripada"],["خَلْفِهِۦ","belakang dia"],["رَصَدًۭا","seorang pengawal"]]],"5475":["(Supaya Dia mengetahui) yakni supaya Allah menampakkan (bahwa) adalah bentuk takhfif dari anna. (sesungguhnya mereka itu telah menyampaikan) yakni rasul-rasul itu (risalah-risalah Rabbnya) di sini dipakai dhamir hum karena memandang segi makna yang terkandung di dalam lafal man (sedangkan, sebenarnya, ilmu-Nya meliputi apa yang ada pada mereka) diathafkan kepada lafal yang tidak disebutkan, lengkapnya ilmu mengenai hal tersebut telah diliputi oleh ilmu-Nya (dan Dia menghitung segala sesuatu satu per satu.\") lafal `adadan adalah tamyiz yang mengganti kedudukan maf`ulnya, asalnya ialah \"ahshaa `adada kulli syai'in,\" yakni Dia telah menghitung bilangan segala sesuatu.",[["لِّيَعْلَمَ","Supaya Dia nyatakan"],["أَن","bahawa"],["قَدْ","sesungguhnya"],["أَبْلَغُوا۟","mereka telah sampaikan"],["رِسَـٰلَـٰتِ","(the) Mesej"],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَأَحَاطَ","dan Dia telah meliputi"],["بِمَا","apa"],["لَدَيْهِمْ","(ada) bersama mereka"],["وَأَحْصَىٰ","dan Dia mengambil kira"],["كُلَّ","(dari) semua"],["شَىْءٍ","benda"],["عَدَدًۢا","(dalam) nombor"]]],"5476":["(Hai orang yang berselimut) yakni Nabi Muhammad. Asal kata al-muzzammil ialah al-mutazammil, kemudian huruf ta diidghamkan kepada huruf za sehingga jadilah al-muzzammil, artinya, orang yang menyelimuti dirinya dengan pakaian sewaktu wahyu datang kepadanya karena merasa takut akan kehebatan wahyu itu.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلْمُزَّمِّلُ","yang membungkus dirinya"]]],"5477":["(Bangunlah di malam hari) maksudnya, salatlah di malam hari (kecuali sedikit.)",[["قُمِ","Berdiri"],["ٱلَّيْلَ","(dalam) malam"],["إِلَّا","kecuali"],["قَلِيلًۭا","sedikit"]]],"5478":["(Yaitu seperduanya) menjadi badal dari lafal qaliilan; pengertian sedikit ini bila dibandingkan dengan keseluruhan waktu malam hari (atau kurangilah daripadanya) dari seperdua itu (sedikit) hingga mencapai sepertiganya.",[["نِّصْفَهُۥٓ","Separuh daripadanya"],["أَوِ","atau"],["ٱنقُصْ","kurangkan"],["مِنْهُ","daripadanya"],["قَلِيلًا","sedikit"]]],"5479":["(Atau lebih dari seperdua) hingga mencapai dua pertiganya; pengertian yang terkandung di dalam lafal au menunjukkan makna boleh memilih. (Dan bacalah Alquran itu) mantapkanlah bacaannya (dengan perlahan-lahan.)",[["أَوْ","Atau"],["زِدْ","tambah"],["عَلَيْهِ","kepadanya"],["وَرَتِّلِ","dan mengaji"],["ٱلْقُرْءَانَ","al-Quran"],["تَرْتِيلًا","(dengan) bacaan berirama terukur"]]],"5480":["(Sesungguhnya Kami akan menurunkan kepadamu perkataan) atau bacaan Alquran (yang berat) yang hebat. Dikatakan berat mengingat kewajiban-kewajiban yang terkandung di dalamnya.",[["إِنَّا","Sesungguhnya Kami"],["سَنُلْقِى","akan membuang"],["عَلَيْكَ","ke atas kamu"],["قَوْلًۭا","sebuah Firman"],["ثَقِيلًا","berat"]]],"5481":["(Sesungguhnya bangun di waktu malam) maksudnya, melakukan salat sunah di malam hari sesudah tidur (lebih tepat) untuk khusyuk di dalam memahami bacaan Alquran (dan bacaan di waktu itu lebih berkesan) lebih jelas dan lebih mantap serta lebih berkesan.",[["إِنَّ","Sesungguhnya"],["نَاشِئَةَ","(yang) meningkat"],["ٱلَّيْلِ","(pada) malam"],["هِىَ","ia"],["أَشَدُّ","(adalah) sangat sukar"],["وَطْـًۭٔا","dan paling mujarab"],["وَأَقْوَمُ","dan lebih sesuai"],["قِيلًا","(untuk) Firman"]]],"5482":["(Sesungguhnya kamu pada siang hari mempunyai urusan yang panjang) mempunyai banyak kesibukan, sehingga kamu tidak mempunyai cukup waktu untuk banyak membaca Alquran.",[["إِنَّ","Sesungguhnya"],["لَكَ","bagi kamu"],["فِى","dalam"],["ٱلنَّهَارِ","hari itu"],["سَبْحًۭا","(adalah) pekerjaan"],["طَوِيلًۭا","berpanjangan"]]],"5483":["(Sebutlah nama Rabbmu) katakanlah bismillahirrahmanirrahiim di awal bacaan Alquranmu (dan curahkanlah) kerahkanlah dirimu (untuk beribadat kepada-Nya dengan ketekunan yang penuh) lafal tabtiilan ini adalah mashdar dari lafal batula, sengaja didatangkan demi untuk memelihara fawashil, dan merupakan lafal yang berakar dari lafal tabattul.",[["وَٱذْكُرِ","Dan ingat"],["ٱسْمَ","(nama)"],["رَبِّكَ","Tuhanmu"],["وَتَبَتَّلْ","dan mengabdikan diri"],["إِلَيْهِ","kepada-Nya"],["تَبْتِيلًۭا","(dengan) berbakti"]]],"5484":["Dialah (Rabb masyriq dan magrib, tiada Tuhan melainkan Dia, maka ambillah Dia sebagai pelindung) artinya serahkanlah semua urusan-urusanmu di bawah perlindungan-Nya.",[["رَّبُّ","(Tuhan)"],["ٱلْمَشْرِقِ","(dari) timur"],["وَٱلْمَغْرِبِ","dan barat"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ","Dia"],["فَٱتَّخِذْهُ","maka ambillah Dia"],["وَكِيلًۭا","(sebagai) Pelupus Hal Ehwal"]]],"5485":["(Dan bersabarlah terhadap apa yang mereka ucapkan) bersabarlah kamu di dalam menghadapi gangguan orang-orang kafir Mekah (dan jauhilah mereka dengan cara yang baik) tanpa keluh-kesah; ayat ini diturunkan sebelum ada perintah memerangi mereka.",[["وَٱصْبِرْ","Dan bersabarlah"],["عَلَىٰ","atas"],["مَا","apa"],["يَقُولُونَ","mereka berkata"],["وَٱهْجُرْهُمْ","dan elakkan mereka"],["هَجْرًۭا","suatu pengelakan"],["جَمِيلًۭا","pemurah"]]],"5486":["(Dan biarkanlah Aku) maksudnya biar Aku saja yang bertindak (terhadap orang-orang yang mendustakan itu) lafal al-mukadzdzibiin diathafkan kepada maf`ul atau kepada maf'ul ma`ah. Maknanya Akulah yang akan bertindak terhadap mereka; mereka adalah pemimpin-pemimpin kaum Quraisy (orang-orang yang mempunyai kemewahan) kemewahan hidup (dan beri tangguhlah mereka barang sebentar) dalam jangka waktu yang tidak lama, dan ternyata selang beberapa waktu kemudian, akhirnya mereka mati terbunuh dalam perang Badar.",[["وَذَرْنِى","Dan tinggalkan Aku"],["وَٱلْمُكَذِّبِينَ","dan orang-orang yang mendustakan"],["أُو۟لِى","pemilik"],["ٱلنَّعْمَةِ","(dari) kemudahan"],["وَمَهِّلْهُمْ","dan biarkan mereka berehat"],["قَلِيلًا","sedikit"]]],"5487":["(Karena sesungguhnya pada sisi Kami ada belenggu-belenggu) merupakan bentuk jamak dari lafal niklun, artinya belenggu-belenggu yang berat (dan neraka Jahim) yaitu neraka yang apinya sangat membakar.",[["إِنَّ","Sesungguhnya"],["لَدَيْنَآ","dengan Kami"],["أَنكَالًۭا","(adalah) belenggu"],["وَجَحِيمًۭا","dan api yang menyala"]]],"5488":["(Dan makanan yang menyumbat di kerongkongan) mengganjal di kerongkongan, itu adalah buah pohon zaqum atau buah pohon dhari' atau buah pohon ghislin atau berupa duri api, apabila dimakan tidak dapat dikeluarkan dan pula tidak dapat masuk ke dalam perut (dan azab yang pedih) di samping azab yang telah disebutkan tadi, hal ini disediakan bagi orang-orang yang mendustakan Nabi saw.",[["وَطَعَامًۭا","Dan makanan"],["ذَا","bahawa"],["غُصَّةٍۢ","tercekik"],["وَعَذَابًا","dan hukuman"],["أَلِيمًۭا","yang pedih"]]],"5489":["(Pada hari berguncang) karena gempa yang dahsyat (bumi dan gunung-gunung, dan menjadilah gunung-gunung itu tumpukan-tumpukan) tumpukan-tumpukan pasir (yang beterbangan) menjadi debu yang beterbangan yang pada sebelumnya kokoh bersatu. Lafal mahiilan berasal dari lafal haala, yahiilu; bentuk asalnya adalah mahyuulun, kemudian karena mengingat harakat dhammah dianggap berat atas huruf ya, maka dipindahkan kepada huruf ha, sehingga jadilah mahuwylun. Kemudian huruf wawu dibuang karena mengingat kedudukannya yang zaidah, sehingga jadilah mahuylun, selanjutnya harakat damah diganti menjadi kasrah untuk menyesuaikannya dengan huruf ya, sehingga jadilah mahiilun.",[["يَوْمَ","(Pada) Hari"],["تَرْجُفُ","akan bergegar"],["ٱلْأَرْضُ","bumi"],["وَٱلْجِبَالُ","dan pergunungan"],["وَكَانَتِ","dan akan menjadi"],["ٱلْجِبَالُ","pergunungan"],["كَثِيبًۭا","timbunan pasir"],["مَّهِيلًا","mencurah-curah"]]],"5490":["(Sesungguhnya Kami telah mengutus kepada kalian) hai penduduk Mekah (seorang rasul) yakni Nabi Muhammad saw. (yang menjadi saksi terhadap kalian) kelak di hari kiamat, tentang kedurhakaan-kedurhakaan yang telah kalian kerjakan (sebagaimana Kami telah mengutus, dahulu, seorang rasul kepada Firaun) yakni Nabi Musa a.s.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَآ","[Kami] telah menghantar"],["إِلَيْكُمْ","kepada kamu"],["رَسُولًۭا","seorang Rasul"],["شَـٰهِدًا","(sebagai) saksi"],["عَلَيْكُمْ","ke atas kamu"],["كَمَآ","seperti"],["أَرْسَلْنَآ","Kami utus"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["رَسُولًۭا","seorang Rasul"]]],"5491":["(Maka Firaun mendurhakai rasul itu, lalu Kami siksa dia dengan siksaan yang berat) atau azab yang keras.",[["فَعَصَىٰ","Tetapi menderhaka"],["فِرْعَوْنُ","Firaun"],["ٱلرَّسُولَ","Rasul"],["فَأَخَذْنَـٰهُ","maka Kami menangkapnya"],["أَخْذًۭا","(dengan) sawan"],["وَبِيلًۭا","merosakkan"]]],"5492":["(Maka bagaimanakah kalian dapat memelihara diri kalian jika tetap kafir) di dunia (kepada hari) lafal yauman menjadi maf'ul kedua dari lafal tattaquuna. Yakni memelihara diri dari azab hari itu. Atau dengan kata lain, dengan benteng apakah kalian memelihara diri dari azab pada hari itu (yang menjadikan anak-anak beruban) lafal syiiban bentuk jamak dari lafal asyyab; dikatakan anak-anak beruban, sebagai gambaran tentang hari itu yang penuh dengan kengerian yang sangat mencekam; hari yang dimaksud adalah hari kiamat. Bentuk asal lafal syiiban adalah syuyban, dengan memakai harakat damah pada huruf syin. Kemudian harakat itu diganti menjadi kasrah demi untuk menyelaraskannya dengan huruf ya yang jatuh sesudahnya, sehingga jadilah syiiban. Dikatakan di dalam menggambarkan hari yang penuh dengan malapetaka, yaumun yusyiibu nawaashial athfaali, yakni hari yang dapat membuat ubun-ubun anak-anak beruban. Ungkapan ini adalah ungkapan majaz atau kata kiasan. Akan tetapi boleh juga makna yang terkandung di dalam ayat ini dimaksud adalah makna hakiki bukan majazi.",[["فَكَيْفَ","Kemudian bagaimana"],["تَتَّقُونَ","adakah kamu akan menjaga diri kamu"],["إِن","jika"],["كَفَرْتُمْ","kamu tidak beriman"],["يَوْمًۭا","sehari"],["يَجْعَلُ","(yang) akan membuat"],["ٱلْوِلْدَٰنَ","anak-anak"],["شِيبًا","berambut kelabu"]]],"5493":["(Langit pun menjadi pecah belah) menjadi retak dan pecah-pecah (pada hari itu) mengingat beratnya hari itu. (Adalah janji Dia) janji Allah swt. mengenai kedatangan hari itu (pasti terlaksana) pasti terjadi.",[["ٱلسَّمَآءُ","Syurga"],["مُنفَطِرٌۢ","(akan) pecah"],["بِهِۦ ۚ","daripadanya"],["كَانَ","ialah"],["وَعْدُهُۥ","JanjiNya"],["مَفْعُولًا","untuk dipenuhi"]]],"5494":["(Sesungguhnya ini) yaitu ayat-ayat yang memperingatkan ini (adalah suatu peringatan) suatu nasihat bagi semua makhluk. (Maka barang siapa yang menghendaki niscaya ia menempuh jalan kepada Rabbnya) menempuh jalan yang menyampaikan kepada-Nya, yaitu melalui iman dan taat kepada-Nya.",[["إِنَّ","Sesungguhnya"],["هَـٰذِهِۦ","ini"],["تَذْكِرَةٌۭ ۖ","(adalah) Peringatan"],["فَمَن","maka sesiapa"],["شَآءَ","wasiat"],["ٱتَّخَذَ","(biarkan dia) ambil"],["إِلَىٰ","kepada"],["رَبِّهِۦ","Tuhannya"],["سَبِيلًا","satu cara"]]],"5495":["(Sesungguhnya Rabbmu mengetahui bahwasanya kamu berdiri, salat, kurang) kurang sedikit (dari dua pertiga malam, atau seperdua malam, atau sepertiganya) jika dibaca nishfihi dan tsulutsihi berarti diathafkan kepada lafal tsulutsay; dan jika dibaca nishfahu dan tsulutsahu berarti diathafkan kepada lafal adnaa. Pengertian berdiri atau melakukan salat sunat di malam hari di sini pengertiannya sama dengan apa yang terdapat di awal surah ini, yakni sesuai dengan apa yang telah diperintahkan Allah kepadanya (dan segolongan dari orang-orang yang bersama kamu) lafal ayat ini diathafkan kepada dhamir yang terkandung di dalam lafal taquumu, demikian pula sebagian orang-orang yang bersamamu. Pengathafan ini diperbolehkan sekalipun tanpa mengulangi huruf taukidnya, demikian itu karena mengingat adanya fashl atau pemisah. Makna ayat secara lengkap, dan segolongan orang-orang yang bersama kamu yang telah melakukan hal yang sama. Mereka melakukan demikian mengikuti jejak Nabi saw. sehingga disebutkan, bahwa ada di antara mereka orang-orang yang tidak menyadari berapa rakaat salat malam yang telah mereka kerjakan, dan waktu malam tinggal sebentar lagi. Sesungguhnya Nabi saw. selalu melakukan salat sunah sepanjang malam, karena demi melaksanakan perintah Allah secara hati-hati. Para sahabat mengikuti jejaknya selama satu tahun, atau lebih dari satu tahun, sehingga disebutkan bahwa telapak-telapak kaki mereka bengkak-bengkak karena terlalu banyak salat. Akhirnya Allah swt. memberikan keringanan kepada mereka. (Dan Allah menetapkan) menghitung (ukuran malam dan siang. Dia mengetahui bahwa) huruf an adalah bentuk takhfif dari anna sedangkan isimnya tidak disebutkan, asalnya ialah annahu (kalian sekali-kali tidak dapat menentukan batas waktu-waktu itu) yaitu waktu malam hari. Kalian tidak dapat melakukan salat malam sesuai dengan apa yang diwajibkan atas kalian melainkan kalian harus melakukannya sepanjang malam. Dan yang demikian itu memberatkan kalian (maka Dia mengampuni kalian) artinya, Dia mencabut kembali perintah-Nya dan memberikan keringanan kepada kalian (karena itu bacalah apa yang mudah dari Alquran) dalam salat kalian (Dia mengetahui, bahwa) huruf an adalah bentuk takhfif dari anna, lengkapnya annahu (akan ada di antara kalian orang-orang yang sakit dan orang-orang yang berjalan di muka bumi) atau melakukan perjalanan (mencari sebagian karunia Allah) dalam rangka mencari rezeki-Nya melalui berniaga dan lain-lainnya (dan orang-orang yang lain lagi, mereka berperang di jalan Allah) ketiga golongan orang-orang tersebut, amat berat bagi mereka hal-hal yang telah disebutkan tadi menyangkut salat malam. Akhirnya Allah memberikan keringanan kepada mereka, yaitu mereka diperbolehkan melakukan salat malam sebatas kemampuan masing-masing. Kemudian ayat ini dinasakh oleh ayat yang mewajibkan salat lima waktu (maka bacalah apa yang mudah dari Alquran) sebagaimana yang telah disebutkan di atas (dan dirikanlah salat) fardu (tunaikanlah zakat dan berikanlah pinjaman kepada Allah) seumpamanya kalian membelanjakan sebagian harta kalian yang bukan zakat kepada jalan kebajikan (pinjaman yang baik) yang ditunaikan dengan hati yang tulus ikhlas. (Dan kebaikan apa saja yang kalian perbuat untuk diri kalian, niscaya kalian akan memperoleh balasannya di sisi Allah sebagai balasan yang jauh lebih baik) dari apa yang telah kalian berikan. Lafal huwa adalah dhamir fashal. Lafal maa sekalipun bukan termasuk isim makrifat akan tetapi diserupakan dengan isim makrifat karena tidak menerima takrif (dan yang paling besar pahalanya. Mohonlah ampun kepada Allah, sesungguhnya Allah Maha Pengampun lagi Maha Penyayang) kepada orang-orang mukmin.",[["۞ إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["يَعْلَمُ","mengetahui"],["أَنَّكَ","bahawa kamu"],["تَقُومُ","berdiri"],["أَدْنَىٰ","(sedikit) kurang"],["مِن","daripada"],["ثُلُثَىِ","dua pertiga"],["ٱلَّيْلِ","(dari) malam"],["وَنِصْفَهُۥ","dan separuh daripadanya"],["وَثُلُثَهُۥ","dan satu pertiga daripadanya"],["وَطَآئِفَةٌۭ","dan (begitu juga) kumpulan"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["مَعَكَ ۚ","(ada) bersama kamu"],["وَٱللَّهُ","Dan Allah"],["يُقَدِّرُ","menentukan"],["ٱلَّيْلَ","malam"],["وَٱلنَّهَارَ ۚ","dan hari"],["عَلِمَ","Dia tahu"],["أَن","bahawa"],["لَّن","tidak"],["تُحْصُوهُ","kamu mengiranya"],["فَتَابَ","maka Dia telah berpaling"],["عَلَيْكُمْ ۖ","kepada kamu"],["فَٱقْرَءُوا۟","jadi mengaji"],["مَا","apa"],["تَيَسَّرَ","adalah mudah"],["مِنَ","daripada"],["ٱلْقُرْءَانِ ۚ","al-Quran"],["عَلِمَ","Dia tahu"],["أَن","bahawa"],["سَيَكُونُ","akan ada"],["مِنكُم","antara kamu"],["مَّرْضَىٰ ۙ","sakit"],["وَءَاخَرُونَ","dan lain-lain"],["يَضْرِبُونَ","melancong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["يَبْتَغُونَ","mencari"],["مِن","daripada"],["فَضْلِ","(the) Bounty"],["ٱللَّهِ ۙ","(milik) Allah"],["وَءَاخَرُونَ","dan lain-lain"],["يُقَـٰتِلُونَ","bergaduh"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ ۖ","(milik) Allah"],["فَٱقْرَءُوا۟","Jadi mengaji"],["مَا","apa"],["تَيَسَّرَ","adalah mudah"],["مِنْهُ ۚ","daripadanya"],["وَأَقِيمُوا۟","dan menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ","zakat tersebut"],["وَأَقْرِضُوا۟","dan pinjaman"],["ٱللَّهَ","Allah"],["قَرْضًا","pinjaman"],["حَسَنًۭا ۚ","dengan baik"],["وَمَا","Dan apa sahaja"],["تُقَدِّمُوا۟","kamu hantar"],["لِأَنفُسِكُم","untuk diri kamu sendiri"],["مِّنْ","daripada"],["خَيْرٍۢ","kebaikan"],["تَجِدُوهُ","kamu akan menemuinya"],["عِندَ","dengan"],["ٱللَّهِ","Allah"],["هُوَ","Ia"],["خَيْرًۭا","(akan menjadi) lebih baik"],["وَأَعْظَمَ","dan lebih besar"],["أَجْرًۭا ۚ","(dalam) ganjaran"],["وَٱسْتَغْفِرُوا۟","Dan minta ampun"],["ٱللَّهَ ۖ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۢ","Maha Mengasihani"]]],"5496":["(Hai orang yang berselimut!) yakni Nabi saw. Bentuk asal lafal al-muddatstsir ialah al-mutadatstsir, kemudian huruf ta diidgamkan kepada huruf dal sehingga jadilah al-Muddatstsir, artinya orang yang menyelimuti dirinya dengan pakaiannya sewaktu wahyu turun kepadanya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلْمُدَّثِّرُ","yang menutup diri"]]],"5497":["(Bangunlah, lalu berilah peringatan) maksudnya pertakutilah penduduk Mekah dengan neraka jika mereka tidak mau beriman.",[["قُمْ","Berdiri"],["فَأَنذِرْ","dan memberi amaran"]]],"5498":["(Dan Rabbmu agungkanlah) agungkanlah Dia dari persekutuan yang diada-adakan oleh orang-orang musyrik.",[["وَرَبَّكَ","Dan Tuhanmu"],["فَكَبِّرْ","membesarkan"]]],"5499":["(Dan pakaianmu bersihkanlah) dari najis, atau pendekkanlah pakaianmu sehingga berbeda dengan kebiasaan orang-orang Arab yang selalu menguntaikan pakaian mereka hingga menyentuh tanah di kala mereka menyombongkan diri, karena dikhawatirkan akan terkena barang yang najis.",[["وَثِيَابَكَ","Dan pakaian kamu"],["فَطَهِّرْ","menyucikan"]]],"5500":["(Dan perbuatan dosa) lafal Ar-Rujza ditafsirkan oleh Nabi saw. berhala-berhala (tinggalkanlah) hal itu untuk selama-lamanya.",[["وَٱلرُّجْزَ","Dan najis"],["فَٱهْجُرْ","elakkan"]]],"5501":["(Dan janganlah kamu memberi dengan maksud memperoleh balasan yang lebih banyak) lafal Tastaktsiru dibaca Rafa' berkedudukan sebagai Haal atau kata keterangan keadaan. Maksudnya, janganlah kamu memberi sesuatu dengan tujuan untuk memperoleh balasan yang lebih banyak dari apa yang telah kamu berikan. Hal ini khusus berlaku hanya bagi Nabi saw. karena sesungguhnya dia diperintahkan untuk mengerjakan akhlak-akhlak yang paling mulia dan pekerti yang paling baik.",[["وَلَا","Dan jangan"],["تَمْنُن","berilah nikmat"],["تَسْتَكْثِرُ","(untuk) memperoleh lebih banyak"]]],"5502":["(Dan kepada Rabbmu bersabarlah) di dalam melaksanakan perintah-perintah dan menjauhi larangan-larangan-Nya.",[["وَلِرَبِّكَ","Dan untuk Tuhanmu"],["فَٱصْبِرْ","bersabarlah"]]],"5503":["(Apabila ditiup sangkakala) untuk tiupan yang kedua, guna membangkitkan manusia.",[["فَإِذَا","Kemudian apabila"],["نُقِرَ","ditiup"],["فِى","dalam"],["ٱلنَّاقُورِ","sangkakala"]]],"5504":["(Maka waktu itu) waktu peniupan sangkakala yang kedua (adalah waktu) lafal Yaumaidzin berkedudukan menjadi Badal dari lafal yang sebelumnya, dan sekaligus menjadi Mubtada. Lafal Yaumaidzin dimabnikan karena mengingat dimudhafkan kepada Isim yang Ghairu Mutamakkin. Kemudian yang menjadi Khabarnya ialah (datangnya hari yang sulit) Amil yang mempengaruhi lafal Idza adalah kalimat yang disimpulkan dari pengertian keseluruhannya. Yakni pada hari itu perkara dirasakan amat berat.",[["فَذَٰلِكَ","Itu"],["يَوْمَئِذٍۢ","Hari"],["يَوْمٌ","(akan menjadi) hari"],["عَسِيرٌ","susah"]]],"5505":["(Bagi orang-orang kafir lagi tidak mudah) di dalam ungkapan ini terkandung pengertian, bahwa keadaan pada hari itu dirasakan amat ringan oleh orang-orang yang beriman di balik kesulitan yang dirasakan oleh orang-orang kafir.",[["عَلَى","Untuk"],["ٱلْكَـٰفِرِينَ","orang-orang kafir"],["غَيْرُ","tidak"],["يَسِيرٍۢ","mudah"]]],"5506":["(Biarkanlah Aku) artinya, serahkanlah kepada-Ku (untuk menindak orang yang Aku ciptakan) lafal Waman di'athafkan kepada Maf'ul atau kepada Maf'ul Ma'ah (dalam keadaan sendirian) menjadi Haal atau kata keterangan keadaan bagi lafal Man, atau bagi Dhamirnya yang tidak disebutkan. Maksudnya, orang yang diciptakan-Nya hanya dia sendiri, tanpa keluarga, tanpa harta benda, dia adalah Walid bin Mughirah Al-Makhzumi.",[["ذَرْنِى","Tinggalkan Aku"],["وَمَنْ","dan siapa"],["خَلَقْتُ","aku cipta"],["وَحِيدًۭا","bersendirian"]]],"5507":["(Dan Aku jadikan baginya harta benda yang banyak) harta yang luas dan berlimpah, berupa tanam-tanaman, susu perahan, dan perniagaan.",[["وَجَعَلْتُ","Dan aku mengizinkan"],["لَهُۥ","kepadanya"],["مَالًۭا","kekayaan"],["مَّمْدُودًۭا","meluas"]]],"5508":["(Dan anak-anak) yang jumlahnya sepuluh orang atau lebih (yang selalu bersama dia) di kala menyaksikan perayaan-perayaan dan kamu pun mendengar tentang persaksian mereka itu.",[["وَبَنِينَ","Dan kanak-kanak"],["شُهُودًۭا","hadir"]]],"5509":["(Dan Kulapangkan) Kuluaskan (baginya) kehidupan, umurnya dan anak-anak yang dimilikinya (dengan selapang-lapangnya.)",[["وَمَهَّدتُّ","Dan aku menyebarkan"],["لَهُۥ","baginya"],["تَمْهِيدًۭا","memudahkan"]]],"5510":["(Kemudian dia ingin sekali supaya Aku menambahkannya.)",[["ثُمَّ","Kemudian"],["يَطْمَعُ","dia berhajat"],["أَنْ","bahawa"],["أَزِيدَ","Aku (harus) menambah lagi"]]],"5511":["(Sekali-kali tidak) Aku tidak akan memberikan tambahan lagi kepadanya selain dari hal tersebut (karena sesungguhnya dia terhadap ayat-ayat Kami) yakni terhadap Alquran (selalu menentang) selalu melawan dan ingkar.",[["كَلَّآ ۖ","sama sekali tidak"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","telah"],["لِـَٔايَـٰتِنَا","kepada Ayat-ayat Kami"],["عَنِيدًۭا","degil"]]],"5512":["(Aku akan membebaninya) Aku akan memberatinya (mendaki pendakian yang memayahkan) yaitu kepayahan karena azab; atau gunung api yang dia daki, kemudian dia jatuh, demikianlah untuk selama-lamanya.",[["سَأُرْهِقُهُۥ","Tidak lama lagi aku akan menutupi Dia"],["صَعُودًا","(dengan) hukuman yang berat"]]],"5513":["(Sesungguhnya dia telah memikirkan) tentang apa yang dikatakannya mengenai Alquran yang ia dengar dari Nabi saw. (dan menetapkan) di dalam dirinya hal tersebut.",[["إِنَّهُۥ","Sesungguhnya dia"],["فَكَّرَ","terfikir"],["وَقَدَّرَ","dan diplot"]]],"5514":["(Maka celakalah dia) dikutuk dan diazablah dia. (Bagaimanakah dia menetapkan?) maksudnya, keadaan apakah yang telah ditetapkannya itu?",[["فَقُتِلَ","Maka semoga dia dimusnahkan"],["كَيْفَ","bagaimana"],["قَدَّرَ","dia merancang"]]],"5515":["(Kemudian celakalah dia. Bagaimanakah dia menetapkan?)",[["ثُمَّ","Kemudian"],["قُتِلَ","semoga dia musnah"],["كَيْفَ","bagaimana"],["قَدَّرَ","dia merancang"]]],"5516":["(Kemudian ia memikirkan) rencana yang ditekuninya itu, atau dia melayangkan pandangannya ke muka kaumnya.",[["ثُمَّ","Kemudian"],["نَظَرَ","dia tengok"]]],"5517":["(Sesudah itu dia bermasam muka) mukanya cemberut dan suram karena merasa sempit dengan apa yang dikatakannya (dan merengut) makin bertambah masam mukanya.",[["ثُمَّ","Kemudian"],["عَبَسَ","dia berkerut dahi"],["وَبَسَرَ","dan meraup muka"]]],"5518":["(Kemudian dia berpaling) dari iman (dan menyombongkan diri) sombong tidak mau mengikut Nabi saw.",[["ثُمَّ","Kemudian"],["أَدْبَرَ","dia berpatah balik"],["وَٱسْتَكْبَرَ","dan berbangga"]]],"5519":["(Lalu dia berkata) di dalam menanggapi apa yang didatangkan oleh Nabi saw. yakni Alquran (\"Tiada lain) (Alquran ini hanyalah sihir yang dipelajari\") maksudnya, yang diambil dari tukang-tukang sihir.",[["فَقَالَ","Kemudian dia berkata"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["سِحْرٌۭ","sihir"],["يُؤْثَرُ","ditiru"]]],"5520":["(\"Tiada lain) (ini hanyalah perkataan manusia\") sama dengan apa yang dikatakan oleh orang-orang musyrik lainnya, yaitu bahwasanya Alquran ini diajarkan kepadanya oleh manusia.",[["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["قَوْلُ","(perkataan)."],["ٱلْبَشَرِ","(dari) seorang manusia"]]],"5521":["(Aku akan memasukkannya) akan menjerumuskannya (ke dalam Saqar) yakni neraka Jahanam.",[["سَأُصْلِيهِ","Tidak lama lagi aku akan memandu dia"],["سَقَرَ","(ke) Neraka"]]],"5522":["(Tahukah kamu, apakah Saqar itu?) ungkapan ini menggambarkan tentang kedahsyatannya.",[["وَمَآ","Dan apa"],["أَدْرَىٰكَ","boleh membuat kamu tahu"],["مَا","apa"],["سَقَرُ","(ialah) Neraka"]]],"5523":["(Saqar itu tidak meninggalkan dan tidak membiarkan) sedikit pun dari daging dan otot melainkan dia melahapnya habis-habisan, kemudian daging dan otot itu kembali seperti semula, lalu dilahapnya lagi, demikianlah seterusnya.",[["لَا","Tidak"],["تُبْقِى","ia membiarkan kekal"],["وَلَا","dan bukan"],["تَذَرُ","ia pergi"]]],"5524":["(Lagi sangat membakar kulit manusia) membakar permukaan kulit dengan cepat.",[["لَوَّاحَةٌۭ","terik"],["لِّلْبَشَرِ","manusia (kulit)"]]],"5525":["(Di atasnya ada sembilan belas) malaikat yang bertugas menjaganya. Seorang di antara orang-orang kafir yang terkenal dengan kekuatan dan kekerasan tubuhnya mengatakan, \"Aku menjamin kalian untuk dapat mengalahkan tujuh belas malaikat itu, dan kalian harus menjamin aku untuk dapat mengalahkan dua malaikat lainnya.\" Maka Allah berfirman:",[["عَلَيْهَا","Di atasnya"],["تِسْعَةَ","(adalah) sembilan"],["عَشَرَ","remaja"]]],"5526":["(Dan tiada Kami jadikan penjaga neraka itu melainkan malaikat) yakni mereka tidak akan dapat dilawan, tidak sebagaimana yang diduga oleh orang-orang kafir (dan tidaklah Kami menjadikan bilangan mereka) yang sembilan belas itu (melainkan untuk jadi cobaan) atau membawa kepada kesesatan (bagi orang-orang kafir) seumpamanya mereka mengatakan, mengapa jumlah malaikat-malaikat penjaga neraka itu hanya sembilan belas? (supaya menjadi yakin) menjadi tambah jelas (orang-orang yang diberi Alkitab) artinya, supaya orang-orang Yahudi yakin akan kebenaran Nabi saw. yang telah menyatakan bahwa jumlah mereka sembilan belas malaikat, dan ini sesuai dengan keterangan yang terdapat di dalam kitab mereka (dan supaya orang-orang yang beriman bertambah) yaitu, orang-orang yang beriman dari kalangan ahli kitab (imannya) kepercayaannya, karena apa yang dijelaskan oleh Nabi saw. itu sesuai dan cocok dengan keterangan yang terdapat di dalam Kitab mereka (dan supaya orang-orang yang diberi Alkitab dan orang-orang mukmin itu tidak ragu-ragu) yaitu orang-orang yang beriman bukan dari kalangan mereka; tentang bilangan malaikat-malaikat penjaga neraka itu (dan supaya orang-orang yang di dalam hatinya ada penyakit) berupa keragu-raguan; mereka berada di Madinah (dan orang-orang kafir mengatakan) yaitu orang-orang kafir Mekah: (\"Apakah yang dikehendaki Allah dengan hal ini) yakni bilangan ini (sebagai suatu perumpamaan?\") mereka menamakannya sebagai perumpamaan, karena hal itu amat aneh didengar oleh mereka. Lafal Matsalan berkedudukan sebagai Haal atau kata keterangan keadaan. (Demikianlah) sebagaimana disesatkan-Nya orang yang tidak mempercayai bilangan ini, dan diberi-Nya petunjuk orang yang percaya kepada-Nya (Allah membiarkan sesat orang-orang yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan tidak ada yang mengetahui tentara Rabbmu) yaitu malaikat-malaikat tentang kekuatan dan kemampuan mereka (melainkan Dia sendiri. Dan Saqar itu tiada lain) neraka itu (hanyalah peringatan bagi manusia.)",[["وَمَا","Dan tidak"],["جَعَلْنَآ","Kami telah membuat"],["أَصْحَـٰبَ","penjaga"],["ٱلنَّارِ","(dari) api"],["إِلَّا","kecuali"],["مَلَـٰٓئِكَةًۭ ۙ","malaikat"],["وَمَا","Dan tidak"],["جَعَلْنَا","Kami telah membuat"],["عِدَّتَهُمْ","nombor mereka"],["إِلَّا","kecuali"],["فِتْنَةًۭ","(sebagai) percubaan"],["لِّلَّذِينَ","bagi mereka yang"],["كَفَرُوا۟","tak beriman"],["لِيَسْتَيْقِنَ","itu mungkin pasti"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab Suci"],["وَيَزْدَادَ","dan mungkin bertambah"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟","beriman"],["إِيمَـٰنًۭا ۙ","(dalam) iman"],["وَلَا","dan bukan"],["يَرْتَابَ","mungkin ragu"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab Suci"],["وَٱلْمُؤْمِنُونَ ۙ","dan orang-orang yang beriman"],["وَلِيَقُولَ","dan itu boleh dikatakan"],["ٱلَّذِينَ","mereka"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["وَٱلْكَـٰفِرُونَ","dan orang-orang kafir"],["مَاذَآ","Apa"],["أَرَادَ","(ada) berniat"],["ٱللَّهُ","Allah"],["بِهَـٰذَا","oleh ini"],["مَثَلًۭا ۚ","contoh"],["كَذَٰلِكَ","Demikianlah"],["يُضِلُّ","memang melepaskan sesat"],["ٱللَّهُ","Allah"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَهْدِى","dan panduan"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَمَا","Dan tiada"],["يَعْلَمُ","mengetahui"],["جُنُودَ","(the) tuan rumah"],["رَبِّكَ","Tuhanmu"],["إِلَّا","kecuali"],["هُوَ ۚ","Dia"],["وَمَا","Dan tidak"],["هِىَ","ia"],["إِلَّا","(adalah) tetapi"],["ذِكْرَىٰ","peringatan"],["لِلْبَشَرِ","kepada (para) manusia"]]],"5527":["(Ingatlah) lafal Kallaa pada ayat ini merupakan lafal yang mengandung makna Istiftah atau kata pembuka, artinya, ingatlah (demi bulan.)",[["كَلَّا","Bahkan"],["وَٱلْقَمَرِ","Oleh bulan"]]],"5528":["(Dan malam ketika) dibaca Idzaa bukan Idz (datang) sesudah siang hari habis. Akan tetapi menurut suatu qiraat dibaca Adbara, yakni telah berlalu.",[["وَٱلَّيْلِ","Dan malam"],["إِذْ","apabila"],["أَدْبَرَ","ia berlepas"]]],"5529":["(Dan subuh apabila mulai terang) mulai menampakkan sinarnya.",[["وَٱلصُّبْحِ","Dan pagi"],["إِذَآ","apabila"],["أَسْفَرَ","ia mencerahkan"]]],"5530":["(Sesungguhnya Saqar itu) neraka Saqar itu (adalah salah satu bencana yang amat besar) malapetaka yang paling besar.",[["إِنَّهَا","Sesungguhnya, ia"],["لَإِحْدَى","(adalah) pasti satu"],["ٱلْكُبَرِ","(dari) yang terbesar"]]],"5531":["(Sebagai ancaman) berkedudukan menjadi Haal dari lafal Ihdaa, disebutkan karena mengingat di dalamnya terkandung makna azab (bagi manusia.)",[["نَذِيرًۭا","Amaran"],["لِّلْبَشَرِ","kepada (manusia)."]]],"5532":["(Yaitu bagi siapa di antara kalian) lafal ayat ini berkedudukan sebagai Badal dari lafal Al-Basyar (yang berkehendak akan maju) kepada kebaikan atau surga dengan beriman (atau mundur) menuju kepada perbuatan dosa, atau neraka dengan melakukan kekafiran.",[["لِمَن","Kepada sesiapa sahaja"],["شَآءَ","wasiat"],["مِنكُمْ","antara kamu"],["أَن","kepada"],["يَتَقَدَّمَ","teruskan"],["أَوْ","atau"],["يَتَأَخَّرَ","tinggal di belakang"]]],"5533":["(Tiap-tiap diri bertanggung jawab atas apa yang telah diperbuatnya) dia tergadaikan, yaitu diazab di dalam neraka disebabkan amal perbuatannya sendiri.",[["كُلُّ","Setiap"],["نَفْسٍۭ","jiwa"],["بِمَا","bagi apa"],["كَسَبَتْ","ia telah memperolehi"],["رَهِينَةٌ","(adalah) dicagarkan"]]],"5534":["(Kecuali golongan kanan) mereka adalah orang-orang yang beriman, mereka selamat dari siksa neraka, di mana mereka berada.",[["إِلَّآ","Kecuali"],["أَصْحَـٰبَ","(para) sahabat"],["ٱلْيَمِينِ","(dari) hak"]]],"5535":["(Di dalam surga saling tanya-menanya) di antara sesama mereka.",[["فِى","Dalam"],["جَنَّـٰتٍۢ","Taman-taman"],["يَتَسَآءَلُونَ","saling bertanya"]]],"5536":["(Tentang orang-orang yang berdosa) tentang keadaan orang-orang yang berdosa, lalu mereka berkata kepada ahli neraka sesudah orang-orang yang bertauhid dikeluarkan daripadanya:",[["عَنِ","Tentang"],["ٱلْمُجْرِمِينَ","penjenayah"]]],"5537":["(\"Apakah yang memasukkan kalian) yang menjerumuskan kalian (ke dalam Saqar?\")",[["مَا","Apa"],["سَلَكَكُمْ","memimpin kamu"],["فِى","ke dalam"],["سَقَرَ","Neraka"]]],"5538":["(Mereka menjawab, \"Kami dahulu tidak termasuk orang-orang yang mengerjakan salat,)",[["قَالُوا۟","Mereka akan berkata"],["لَمْ","Tidak"],["نَكُ","kami"],["مِنَ","daripada"],["ٱلْمُصَلِّينَ","mereka yang solat"]]],"5539":["(dan Kami tidak pula memberi makan orang miskin.)",[["وَلَمْ","Dan tidak"],["نَكُ","kita dulu"],["نُطْعِمُ","suapan"],["ٱلْمِسْكِينَ","orang miskin"]]],"5540":["(Dan adalah Kami tenggelam ke dalam pembicaraan) yang batil (bersama dengan orang-orang yang membicarakannya.)",[["وَكُنَّا","Dan kami pernah"],["نَخُوضُ","asyik bercakap sia-sia"],["مَعَ","dengan"],["ٱلْخَآئِضِينَ","orang yang bercakap sia-sia"]]],"5541":["(Dan adalah Kami mendustakan hari pembalasan) yakni hari berbangkit dan hari pembalasan.",[["وَكُنَّا","Dan kami pernah"],["نُكَذِّبُ","menafikan"],["بِيَوْمِ","(the) Hari"],["ٱلدِّينِ","(dari) Penghakiman"]]],"5542":["(Hingga datang kepada kami kematian\") ajal kami.",[["حَتَّىٰٓ","Sehinggalah"],["أَتَىٰنَا","datang kepada kami"],["ٱلْيَقِينُ","kepastian"]]],"5543":["(Maka tidak berguna lagi bagi mereka syafaat dari orang-orang yang memberi syafaat) baik dari kalangan malaikat, para nabi atau pun orang-orang saleh. Makna yang dimaksud ialah bahwa tiada syafaat bagi mereka.",[["فَمَا","Kemudian tidak"],["تَنفَعُهُمْ","akan memberi manfaat kepada mereka"],["شَفَـٰعَةُ","syafaat"],["ٱلشَّـٰفِعِينَ","(dari) pemberi syafaat"]]],"5544":["(Maka mengapa) berkedudukan menjadi Mubtada (mereka) menjadi Khabar dari Mubtada, berta'alluq kepada lafal yang tidak disebutkan yang Dhamirnya dipindahkan kepadanya (berpaling dari peringatan?) lafal Mu'ridhiina menjadi Haal atau kata keterangan keadaan dari Dhamir Lahum. Makna yang dimaksud, apakah gerangan sesuatu yang terjadi pada diri mereka sehingga mereka berpaling dari peringatan?",[["فَمَا","Kemudian apa"],["لَهُمْ","(adalah) untuk mereka"],["عَنِ","(itu) daripada"],["ٱلتَّذْكِرَةِ","Peringatan itu"],["مُعْرِضِينَ","mereka (sedang) berpaling"]]],"5545":["(Seakan-akan mereka itu keledai liar yang lari terkejut) keledai-keledai liar yang larat.",[["كَأَنَّهُمْ","Seolah-olah mereka (adalah)"],["حُمُرٌۭ","keldai"],["مُّسْتَنفِرَةٌۭ","ketakutan"]]],"5546":["(Lari dari singa) lari sekencang-kencangnya karena menghindar dan menyelamatkan diri dari singa.",[["فَرَّتْ","melarikan diri"],["مِن","daripada"],["قَسْوَرَةٍۭ","seekor singa"]]],"5547":["(Bahkan tiap-tiap orang dari mereka berkehendak supaya diberikan kepadanya lembaran-lembaran yang terbuka) dari Allah swt. disebabkan mengikuti Nabi saw. Sebagaimana yang telah mereka katakan, bahwa tidak sekali-kali kami beriman kepadamu sebelum kamu menurunkan kepada kami sebuah kitab yang kami baca.",[["بَلْ","Bahkan"],["يُرِيدُ","Keinginan"],["كُلُّ","setiap"],["ٱمْرِئٍۢ","orang"],["مِّنْهُمْ","daripada mereka"],["أَن","bahawa"],["يُؤْتَىٰ","dia boleh diberi"],["صُحُفًۭا","muka surat"],["مُّنَشَّرَةًۭ","tersebar"]]],"5548":["(Sekali-kali tidak) lafal ini merupakan sanggahan terhadap apa yang mereka kehendaki itu. (Sebenarnya mereka tidak takut kepada negeri akhirat) kepada azabnya.",[["كَلَّا ۖ","Bahkan"],["بَل","Tetapi"],["لَّا","tidak"],["يَخَافُونَ","mereka takut"],["ٱلْـَٔاخِرَةَ","akhirat"]]],"5549":["(Ingatlah) Kallaa di sini menunjukkan makna Istiftah atau kata pembukaan (sesungguhnya dia itu) Alquran itu (adalah peringatan) nasihat dan pelajaran.",[["كَلَّآ","Bahkan"],["إِنَّهُۥ","Sesungguhnya, ia"],["تَذْكِرَةٌۭ","(adalah) Peringatan"]]],"5550":["(Maka barang siapa menghendaki, niscaya dia mengambil pelajaran daripadanya) niscaya dia membacanya kemudian mengambil pelajaran daripadanya.",[["فَمَن","Jadi sesiapa"],["شَآءَ","wasiat"],["ذَكَرَهُۥ","(boleh) memberi perhatian kepadanya"]]],"5551":["(Dan mereka tidak akan mengambil pelajaran daripadanya) dapat dibaca Yadzkuruuna dan Tadzkuruuna (kecuali bila Allah menghendakinya. Dia adalah Tuhan Yang patut kita bertakwa kepada-Nya) Dia adalah yang harus ditakwai (dan berhak memberi ampun) seumpamanya Dia memberikan ampunan-Nya kepada orang-orang yang bertakwa kepada-Nya.",[["وَمَا","Dan tidak"],["يَذْكُرُونَ","akan memberi perhatian"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَشَآءَ","wasiat"],["ٱللَّهُ ۚ","Allah"],["هُوَ","Dia"],["أَهْلُ","(adalah) layak"],["ٱلتَّقْوَىٰ","untuk ditakuti"],["وَأَهْلُ","dan layak"],["ٱلْمَغْفِرَةِ","untuk memaafkan"]]],"5552":["(Aku bersumpah dengan hari kiamat) huruf Laa di sini adalah huruf Zaidah.",[["لَآ","Bahkan"],["أُقْسِمُ","aku bersumpah"],["بِيَوْمِ","oleh (the) Day"],["ٱلْقِيَـٰمَةِ","Kiamat"]]],"5553":["(Dan Aku bersumpah dengan jiwa yang amat menyesali) dirinya sendiri sekalipun ia berupaya sekuat tenaga di dalam kebaikan. Jawab Qasam tidak disebutkan; lengkapnya, Aku bersumpah dengan nama hari kiamat dan dengan nama jiwa yang banyak mencela, bahwa niscaya jiwa itu pasti akan dibangkitkan. Pengertian Jawab ini ditunjukkan oleh firman selanjutnya, yaitu:",[["وَلَآ","Dan tidak"],["أُقْسِمُ","aku bersumpah"],["بِٱلنَّفْسِ","oleh jiwa"],["ٱللَّوَّامَةِ","menuduh diri sendiri"]]],"5554":["(Apakah manusia mengira) yakni, orang kafir (bahwa Kami tidak akan mengumpulkan kembali tulang belulangnya) untuk dibangkitkan menjadi hidup kembali.",[["أَيَحْسَبُ","Adakah berfikir"],["ٱلْإِنسَـٰنُ","lelaki itu"],["أَلَّن","itu tidak"],["نَّجْمَعَ","Kami akan berhimpun"],["عِظَامَهُۥ","tulangnya"]]],"5555":["(Bukan demikian) Kami akan mengumpulkannya kembali (Kami kuasa) di samping mengumpulkan kembali tulang-tulangnya itu (menyusun kembali jari-jemarinya dengan sempurna) artinya, Kami dapat mengembalikan tulang jari-jemari itu sekalipun bentuknya kecil, maka terlebih lagi tulang-tulang lainnya yang lebih besar daripadanya.",[["بَلَىٰ","Bahkan"],["قَـٰدِرِينَ","(Kami) Mampu"],["عَلَىٰٓ","pada"],["أَن","bahawa"],["نُّسَوِّىَ","Kita boleh pulihkan"],["بَنَانَهُۥ","hujung jarinya"]]],"5556":["(Bahkan manusia itu hendak membuat maksiat terus-menerus) huruf Lam yang ada pada lafal Liyafjura adalah Zaidah, sedangkan lafal Yafjuru dinashabkan oleh An yang diperkirakan keberadaannya. Yakni dia selalu berbuat dusta (di dalam menghadapinya) di dalam menghadapi hari kiamat. Pengertian ini ditunjukkan oleh firman selanjutnya, yaitu:",[["بَلْ","Bahkan"],["يُرِيدُ","Keinginan"],["ٱلْإِنسَـٰنُ","lelaki itu"],["لِيَفْجُرَ","untuk memberi (berdusta)."],["أَمَامَهُۥ","(kepada) apa yang ada di hadapannya"]]],"5557":["(Ia bertanya, \"Bilakah) Kapan (hari kiamat itu?\") pertanyaannya itu mengandung nada mengejek dan mendustakannya.",[["يَسْـَٔلُ","Dia bertanya"],["أَيَّانَ","Apabila"],["يَوْمُ","(ialah) Hari"],["ٱلْقِيَـٰمَةِ","Kiamat"]]],"5558":["(Maka apabila mata terbelalak) dapat dibaca Bariqa dan Baraqa, artinya kaget dan bimbang setelah ia melihat apa yang dahulu selalu ia dustakan.",[["فَإِذَا","Maka apabila"],["بَرِقَ","terpesona"],["ٱلْبَصَرُ","penglihatan itu"]]],"5559":["(Dan apabila bulan telah hilang cahayanya) yakni menjadi gelap dan lenyap sinarnya.",[["وَخَسَفَ","Dan menjadi gelap"],["ٱلْقَمَرُ","bulan"]]],"5560":["(Dan matahari dan bulan dikumpulkan) maka kedua-duanya terbit dari arah barat; atau kedua-duanya telah hilang sinarnya, yang demikian itu terjadi pada hari kiamat.",[["وَجُمِعَ","Dan disertai"],["ٱلشَّمْسُ","matahari"],["وَٱلْقَمَرُ","dan bulan"]]],"5561":["(Pada hari itu manusia berkata, \"Ke mana tempat lari?\")",[["يَقُولُ","Akan berkata"],["ٱلْإِنسَـٰنُ","lelaki itu"],["يَوْمَئِذٍ","hari itu"],["أَيْنَ","di mana"],["ٱلْمَفَرُّ","(ialah) melarikan diri"]]],"5562":["(Sekali-kali tidak) lafal ini menunjukkan kata tolakan terhadap pencarian jalan lari. (Tidak ada tempat berlindung) tidak ada tempat mengungsi yang dapat dijadikan perlindungan baginya.",[["كَلَّا","sama sekali tidak"],["لَا","(Ada) tidak"],["وَزَرَ","tempat perlindungan"]]],"5563":["(Hanya kepada Rabbmu sajalah pada hari itu tempat kembali) bagi semua makhluk, lalu mereka dihisab dan menerima pembalasan.",[["إِلَىٰ","Kepada"],["رَبِّكَ","Tuhanmu"],["يَوْمَئِذٍ","hari itu"],["ٱلْمُسْتَقَرُّ","(ialah) tempat rehat"]]],"5564":["(Pada hari itu diberitakan kepada manusia apa yang telah dikerjakannya dan apa yang dilalaikannya) yaitu semua amal perbuatannya dari mulai awal hingga akhir, diberitakan kepadanya.",[["يُنَبَّؤُا۟","Akan dimaklumkan"],["ٱلْإِنسَـٰنُ","lelaki itu"],["يَوْمَئِذٍۭ","hari itu"],["بِمَا","tentang apa"],["قَدَّمَ","dia menghantar"],["وَأَخَّرَ","dan disimpan kembali"]]],"5565":["(Bahkan manusia itu menjadi saksi atas dirinya sendiri) yakni semua anggota tubuhnya memberikan kesaksian terhadap semua amal perbuatannya, sehingga ia tidak dapat mengingkarinya lagi. Huruf Ha yang ada pada lafal Bashiirah menunjukkan makna Mubalaghah.",[["بَلِ","Bahkan"],["ٱلْإِنسَـٰنُ","Lelaki itu"],["عَلَىٰ","terhadap"],["نَفْسِهِۦ","dirinya sendiri"],["بَصِيرَةٌۭ","(akan) menjadi saksi"]]],"5566":["(Meskipun dia mengemukakan alasan-alasannya) lafal Ma'aadziir bentuk jamak dari lafal Ma'dzirah, akan tetapi tidak menurut cara yang beraturan. Makna ayat, seandainya dia mengemukakan semua alasannya, niscaya alasan-alasannya itu tidak akan diterima. Allah berfirman kepada Nabi-Nya:",[["وَلَوْ","Walaupun"],["أَلْقَىٰ","dia mempersembahkan"],["مَعَاذِيرَهُۥ","alasan dia"]]],"5567":["(Janganlah kamu gerakkan untuk membacanya) membaca Alquran, sebelum malaikat Jibril selesai daripadanya (lisanmu karena hendak cepat-cepat menguasainya) karena kamu merasa khawatir bacaannya tidak dapat kamu kuasai.",[["لَا","Tidak"],["تُحَرِّكْ","bergerak"],["بِهِۦ","dengannya"],["لِسَانَكَ","lidah kamu"],["لِتَعْجَلَ","untuk menyegerakan"],["بِهِۦٓ","dengannya"]]],"5568":["(Sesungguhnya atas tanggungan Kamilah mengumpulkannya) di dadamu, maksudnya membuat kamu dapat menghafalnya (dan bacaannya) yakni membuatmu pandai membacanya; atau membuat mudah dibaca olehmu.",[["إِنَّ","Sesungguhnya"],["عَلَيْنَا","atas Kami"],["جَمْعَهُۥ","(adalah) koleksinya"],["وَقُرْءَانَهُۥ","dan bacaannya"]]],"5569":["(Apabila Kami telah selesai membacakannya) kepada kamu melalui bacaan malaikat Jibril (maka ikutilah bacaannya itu) artinya, dengarlah dengan seksama bacaan Jibril kepadamu terlebih dahulu. Sesungguhnya Nabi saw. setelah itu mendengarkannya terlebih dahulu dengan seksama, kemudian membacanya.",[["فَإِذَا","Dan apabila"],["قَرَأْنَـٰهُ","Kami telah membacakannya"],["فَٱتَّبِعْ","kemudian ikuti"],["قُرْءَانَهُۥ","bacaannya"]]],"5570":["(Kemudian, sesungguhnya atas tanggungan Kamilah penjelasannya) dengan memberikan pemahaman mengenainya kepadamu. Kaitan atau hubungan korelasi antara ayat ini dengan ayat-ayat sebelumnya ialah bahwasanya ayat-ayat sebelumnya itu mengandung makna berpaling dari ayat-ayat Allah. Sedangkan pada ayat ini terkandung pengertian bersegera menguasai ayat-ayat Allah dengan cara menghafalnya.",[["ثُمَّ","Kemudian"],["إِنَّ","sesungguhnya"],["عَلَيْنَا","atas Kami"],["بَيَانَهُۥ","(adalah) penjelasannya"]]],"5571":["(Sekali-kali jangan) lafal Kallaa menunjukkan makna Istiftah, yakni ingatlah (sebenarnya kalian mencintai kehidupan dunia) dapat dibaca Tuhibbuuna dan Yuhibbuuna, kalau dibaca Yuhibbuuna artinya, mereka mencintai kehidupan dunia.",[["كَلَّا","Tidak"],["بَلْ","Tetapi"],["تُحِبُّونَ","kamu sayang"],["ٱلْعَاجِلَةَ","yang segera"]]],"5572":["(Dan meninggalkan kehidupan akhirat) karena itu mereka tidak beramal untuk menyambut hari akhirat.",[["وَتَذَرُونَ","Dan pergi"],["ٱلْـَٔاخِرَةَ","akhirat"]]],"5573":["(Wajah-wajah pada hari itu) pada hari kiamat (ada yang berseri-seri) tampak cerah dan bercahaya.",[["وُجُوهٌۭ","Muka"],["يَوْمَئِذٍۢ","hari itu"],["نَّاضِرَةٌ","(akan) bercahaya"]]],"5574":["(Kepada Rabbnyalah mereka melihat) mereka akan melihat Allah swt. di akhirat.",[["إِلَىٰ","Ke arah"],["رَبِّهَا","Tuhan mereka"],["نَاظِرَةٌۭ","mencari"]]],"5575":["(Dan wajah-wajah pada hari itu ada yang muram) tampak gelap dan sangat muram.",[["وَوُجُوهٌۭ","Dan muka"],["يَوْمَئِذٍۭ","hari itu"],["بَاسِرَةٌۭ","(akan) diputarbelitkan"]]],"5576":["(Mereka yakin) merasa yakin (bahwa akan ditimpakan kepadanya malapetaka yang amat dahsyat) bencana yang sangat besar, yang dapat meremukkan tulang-tulang punggung.",[["تَظُنُّ","Berfikir"],["أَن","bahawa"],["يُفْعَلَ","akan dilakukan"],["بِهَا","kepada mereka"],["فَاقِرَةٌۭ","patah balik"]]],"5577":["(Sekali-kali jangan) bermakna Alaa, yakni ingatlah. (Apabila telah sampai) napas (pada tenggorokan) atau kerongkongan.",[["كَلَّآ","Tidak"],["إِذَا","Apabila"],["بَلَغَتِ","ia sampai"],["ٱلتَّرَاقِىَ","tulang selangka"]]],"5578":["(Dan dikatakan) kepadanya oleh yang ada di sekitarnya: (\"Siapakah yang dapat mengobati?\") hingga sembuh.",[["وَقِيلَ","Dan dikatakan"],["مَنْ ۜ","Siapa"],["رَاقٍۢ","(akan) menyembuhkan"]]],"5579":["(Dan dia yakin) yakni orang yang napasnya telah sampai di tenggorokan itu merasa yakin akan hal tersebut (bahwa sesungguhnya itulah waktu perpisahan) yaitu meninggalkan dunia.",[["وَظَنَّ","Dan dia pasti"],["أَنَّهُ","bahawa ia"],["ٱلْفِرَاقُ","(ialah) perpisahan"]]],"5580":["(Dan bertaut betis dengan betis) betis kanan dan betis kirinya bertaut ketika ia mati. Atau makna yang dimaksud ialah saling bertaut antara sakit berpisah dengan dunia dan sakit menghadapi akhirat di dalam dirinya.",[["وَٱلْتَفَّتِ","Dan terluka"],["ٱلسَّاقُ","kaki"],["بِٱلسَّاقِ","tentang kaki"]]],"5581":["(Kepada Rabbmulah pada hari itu mereka dihalau) atau kepada-Nyalah mereka digiring; hal ini menunjukkan tentang adanya Amil dalam lafal Idzaa. Lengkapnya, apabila nyawa telah sampai di tenggorokan, maka ia akan dihalau menuju kepada keputusan Rabbnya.",[["إِلَىٰ","Kepada"],["رَبِّكَ","Tuhanmu"],["يَوْمَئِذٍ","hari itu"],["ٱلْمَسَاقُ","(akan) memandu"]]],"5582":["(Dan ia tidak mau membenarkan) yaitu manusia (dan tidak mau mengerjakan salat) ia tidak mau mempercayai rasul dan tidak pula mau mendirikan salat.",[["فَلَا","Dan tidak"],["صَدَّقَ","dia menerima kebenaran"],["وَلَا","dan bukan"],["صَلَّىٰ","dia berdoa"]]],"5583":["(Tetapi ia mendustakan) Alquran (dan berpaling) dari iman.",[["وَلَـٰكِن","Tetapi"],["كَذَّبَ","dia menafikan"],["وَتَوَلَّىٰ","dan berpaling"]]],"5584":["(Kemudian ia pergi kepada ahlinya dengan berlagak) dengan langkah-langkah yang sombong.",[["ثُمَّ","Kemudian"],["ذَهَبَ","dia pergi"],["إِلَىٰٓ","kepada"],["أَهْلِهِۦ","keluarganya"],["يَتَمَطَّىٰٓ","sombong"]]],"5585":["(Kecelakaanlah bagimu) di dalam ungkapan kalimat ini terkandung Iltifat dari Ghaibah, kalimat ini adalah Isim Fi'il, sedangkan huruf Lamnya menunjukkan makna Tabyin, artinya: dia menyerahkan kepadamu apa-apa yang tidak kamu sukai (maka kecelakaanlah bagimu) yakni dia lebih utama untuk diprioritaskan olehmu.",[["أَوْلَىٰ","celaka"],["لَكَ","kepada kamu"],["فَأَوْلَىٰ","dan celaka"]]],"5586":["(Kemudian kecelakaanlah bagimu dan kecelakaanlah bagimu) mengukuhkan makna ayat di atas.",[["ثُمَّ","Kemudian"],["أَوْلَىٰ","celaka"],["لَكَ","kepada kamu"],["فَأَوْلَىٰٓ","dan celaka"]]],"5587":["(Apakah manusia mengira) menduga (bahwa ia akan dibiarkan begitu saja) tanpa dibebani dengan syariat-syariat; janganlah ia menduga seperti itu.",[["أَيَحْسَبُ","Adakah berfikir"],["ٱلْإِنسَـٰنُ","lelaki"],["أَن","bahawa"],["يُتْرَكَ","dia akan ditinggalkan"],["سُدًى","diabaikan"]]],"5588":["(Bukankah dia dahulu) sebelum itu (setetes mani yang ditumpahkan) ke dalam rahim; lafal Yumnaa dapat pula dibaca Tumnaa.",[["أَلَمْ","Bukan"],["يَكُ","dia"],["نُطْفَةًۭ","titisan air mani"],["مِّن","daripada"],["مَّنِىٍّۢ","air mani"],["يُمْنَىٰ","dipancarkan"]]],"5589":["(Kemudian adalah) mani itu (menjadi segumpal darah lalu Allah menciptakannya) dari air mani itu menjadi manusia (dan menyempurnakannya) melengkapinya dengan anggota-anggota tubuh yang diperlukannya.",[["ثُمَّ","Kemudian"],["كَانَ","dia adalah"],["عَلَقَةًۭ","bahan yang melekat"],["فَخَلَقَ","kemudian Dia menciptakan"],["فَسَوَّىٰ","dan berkadar"]]],"5590":["(Lalu Allah menjadikan daripadanya) dari air mani yang telah menjadi segumpal darah, segumpal daging (sepasang) dua jenis (laki-laki dan perempuan) terkadang menjadi satu dan terkadang tersendiri.",[["فَجَعَلَ","Kemudian dibuat"],["مِنْهُ","daripada dia"],["ٱلزَّوْجَيْنِ","dua jenis"],["ٱلذَّكَرَ","(yang) lelaki"],["وَٱلْأُنثَىٰٓ","dan perempuan"]]],"5591":["(Bukankah yang berbuat demikian) yang mengerjakan kesemuanya itu (berkuasa pula menghidupkan orang mati?) Nabi saw. menjawab, tentu saja dapat.",[["أَلَيْسَ","bukan"],["ذَٰلِكَ","[bahawa]"],["بِقَـٰدِرٍ","(Dia) Sanggup"],["عَلَىٰٓ","[lebih]"],["أَن","kepada"],["يُحْـِۧىَ","memberi kehidupan"],["ٱلْمَوْتَىٰ","(kepada) orang mati"]]],"5592":["(Bukankah) artinya, sesungguhnya (telah datang atas manusia) Nabi Adam (satu waktu dari masa) empat puluh tahun (sedangkan dia belum merupakan) ketika itu (sesuatu yang dapat disebut) maksudnya, Nabi Adam selama empat puluh tahun masih tetap berbentuk tanah dan bukan berarti apa-apa. Atau bila yang dimaksud dengan manusia adalah jenis manusia selain dia, maka yang dimaksud dengan lafal Al-Hiin atau masa ialah masa mengandung, jadi bukan empat puluh tahun.",[["هَلْ","Mempunyai"],["أَتَىٰ","(sana) datang"],["عَلَى","ke atas"],["ٱلْإِنسَـٰنِ","lelaki"],["حِينٌۭ","tempoh"],["مِّنَ","daripada"],["ٱلدَّهْرِ","masa"],["لَمْ","tidak"],["يَكُن","dia adalah"],["شَيْـًۭٔا","sesuatu perkara"],["مَّذْكُورًا","disebutkan"]]],"5593":["(Sesungguhnya Kami telah menciptakan manusia) artinya, jenis manusia (dari setetes mani yang bercampur) yang bercampur dengan indung telur, yaitu air mani laki-laki bercampur menjadi satu dengan air mani perempuan (yang Kami hendak mengujinya) dengan membebankan kewajiban-kewajiban kepadanya; jumlah ayat ini merupakan jumlah Isti`naf yakni kalimat permulaan; atau dianggap sebagai Hal dari lafal yang diperkirakan. Yaitu, Kami bermaksud hendak mengujinya ketika Kami mempersiapkan kejadiannya (karena itu Kami jadikan dia) Kami menjadikan dia dapat (mendengar dan melihat.)",[["إِنَّا","Sesungguhnya Kami"],["خَلَقْنَا","[Kami] mencipta"],["ٱلْإِنسَـٰنَ","lelaki"],["مِن","daripada"],["نُّطْفَةٍ","titisan air mani"],["أَمْشَاجٍۢ","suatu campuran"],["نَّبْتَلِيهِ","(bahawa) Kami uji dia"],["فَجَعَلْنَـٰهُ","maka Kami jadikan (untuk) dia"],["سَمِيعًۢا","pendengaran"],["بَصِيرًا","dan penglihatan"]]],"5594":["(Sesungguhnya Kami telah menunjukinya jalan petunjuk) maksudnya, Kami telah menjelaskan kepadanya jalan hidayah dengan mengutus rasul-rasul kepada manusia (ada yang bersyukur) yaitu menjadi orang mukmin (dan ada pula yang kafir) kedua lafal ini, yakni Syaakiran dan Kafuuran merupakan Haal dari Maf'ul; yakni Kami telah menjelaskan jalan hidayah kepadanya, baik sewaktu ia dalam keadaan bersyukur atau pun sewaktu ia kafir sesuai dengan kepastian Kami. Lafal Immaa di sini menunjukkan rincian tentang keadaan.",[["إِنَّا","Sesungguhnya Kami"],["هَدَيْنَـٰهُ","membimbingnya"],["ٱلسَّبِيلَ","(ke) jalan"],["إِمَّا","sama ada"],["شَاكِرًۭا","(dia) bersyukur"],["وَإِمَّا","dan sama ada"],["كَفُورًا","(dia) tidak bersyukur"]]],"5595":["(Sesungguhnya Kami menyediakan) telah mempersiapkan (bagi orang-orang kafir rantai) untuk menyeret mereka ke dalam neraka (dan belenggu-belenggu) pada leher mereka dan rantai itu diikatkan kepadanya (serta neraka Sair) yaitu neraka yang apinya menyala-nyala dengan besarnya, tempat mereka diazab.",[["إِنَّآ","Sesungguhnya Kami"],["أَعْتَدْنَا","[Kami] telah bersedia"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"],["سَلَـٰسِلَا۟","rantai"],["وَأَغْلَـٰلًۭا","dan belenggu"],["وَسَعِيرًا","dan api yang menyala-nyala"]]],"5596":["(Sesungguhnya orang-orang yang berbuat kebaikan) lafal Al-Abraar bentuk jamak dari lafal Barrun atau Baarrun, artinya orang-orang yang taat (mereka minum dari gelas) atau tempat minum, yang berisikan khamar. Maksudnya, mereka meminum khamar. Hal ini diungkapkan dengan memakai nama alat peminumnya. Huruf Min bermakna Tab'idh (yang campurannya) yakni khamar itu dicampur dengan (kafur.)",[["إِنَّ","Sesungguhnya"],["ٱلْأَبْرَارَ","orang yang soleh"],["يَشْرَبُونَ","akan minum"],["مِن","daripada"],["كَأْسٍۢ","secawan"],["كَانَ","ialah"],["مِزَاجُهَا","campurannya"],["كَافُورًا","(daripada) Kafur"]]],"5597":["(Yaitu mata air) menjadi Badal dari lafal Kaafuur artinya, mata air itu berbau kafur (yang meminum daripadanya) dari mata air itu (hamba-hamba Allah) yakni kekasih-kekasih-Nya (yang mereka dapat mengalirkannya dengan sebaik-baiknya) mereka dapat mengalirkan air dari telaga itu menurut kehendaknya dari tempat-tempat tinggal mereka.",[["عَيْنًۭا","Sebuah musim bunga"],["يَشْرَبُ","akan minum"],["بِهَا","daripadanya"],["عِبَادُ","(para) hamba"],["ٱللَّهِ","(milik) Allah"],["يُفَجِّرُونَهَا","menyebabkan ia terpancut keluar"],["تَفْجِيرًۭا","dengan banyaknya"]]],"5598":["(Mereka menunaikan nazar) untuk taat kepada Allah (dan takut akan suatu hari yang azabnya merata di mana-mana) menyebar di semua tempat.",[["يُوفُونَ","Mereka memenuhi"],["بِٱلنَّذْرِ","nazar"],["وَيَخَافُونَ","dan ketakutan"],["يَوْمًۭا","sehari"],["كَانَ","(yang) ialah"],["شَرُّهُۥ","jahatnya"],["مُسْتَطِيرًۭا","meluas"]]],"5599":["(Dan mereka memberikan makanan yang disukainya) atau yang digemarinya (kepada orang miskin) atau orang fakir (anak yatim) anak yang ayahnya sudah tiada (dan orang yang ditawan) orang yang ditahan karena membela perkara yang hak.",[["وَيُطْعِمُونَ","Dan mereka memberi makan"],["ٱلطَّعَامَ","makanan itu"],["عَلَىٰ","walaupun"],["حُبِّهِۦ","suka (untuk) itu"],["مِسْكِينًۭا","(kepada) yang memerlukan"],["وَيَتِيمًۭا","dan (anak) yatim"],["وَأَسِيرًا","dan (yang) tawanan"]]],"5600":["(Sesungguhnya kami memberi makanan kepada kalian hanyalah demi karena Allah) demi untuk mengharapkan pahala-Nya (kami tidak menghendaki balasan dari kalian dan tidak pula ucapan terima kasih) berterima kasih atas pemberian makanan itu. Apakah mereka benar-benar mengucapkan demikian ataukah hal itu telah diketahui oleh Allah swt. kemudian Allah memuji mereka. Sesungguhnya dengan masalah ini ada dua pendapat.",[["إِنَّمَا","Hanya"],["نُطْعِمُكُمْ","kami memberi kamu makan"],["لِوَجْهِ","untuk (the) Countenance"],["ٱللَّهِ","(milik) Allah"],["لَا","Tidak"],["نُرِيدُ","kita inginkan"],["مِنكُمْ","daripada kamu"],["جَزَآءًۭ","sebarang ganjaran"],["وَلَا","dan bukan"],["شُكُورًا","terima kasih"]]],"5601":["(Sesungguhnya kami takut kepada Rabb kami akan suatu hari yang penuh dengan kemasaman) yaitu muka-muka pada saat itu bermuram durja dan tidak enak dipandang karena kepahitannya (lagi penuh dengan kesulitan) yakni hari itu penuh dengan penderitaan yang sangat parah.",[["إِنَّا","Sesungguhnya kami"],["نَخَافُ","bertakwa"],["مِن","daripada"],["رَّبِّنَا","Tuhan kami"],["يَوْمًا","sehari"],["عَبُوسًۭا","keras"],["قَمْطَرِيرًۭا","dan menyusahkan"]]],"5602":["(Maka Allah memelihara mereka dari kesusahan hari itu, dan memberikan kepada mereka) atau menghadiahkan kepada mereka (kejernihan) yaitu keindahan dan kecemerlangan pada wajah-wajah mereka (dan kegembiraan hati.)",[["فَوَقَىٰهُمُ","Tetapi akan melindungi mereka"],["ٱللَّهُ","Allah"],["شَرَّ","(dari) kejahatan"],["ذَٰلِكَ","(daripada) itu"],["ٱلْيَوْمِ","Hari"],["وَلَقَّىٰهُمْ","dan akan menyebabkan mereka bertemu"],["نَضْرَةًۭ","sinaran"],["وَسُرُورًۭا","dan kebahagiaan"]]],"5603":["(Dan Dia memberi balasan kepada mereka karena kesabaran mereka) disebabkan kesabaran mereka dari perbuatan maksiat (surga) yang mereka dimasukkan ke dalamnya (dan sutera) yang menjadi pakaian mereka.",[["وَجَزَىٰهُم","Dan akan memberi ganjaran kepada mereka"],["بِمَا","kerana"],["صَبَرُوا۟","mereka bersabar"],["جَنَّةًۭ","(dengan) Taman"],["وَحَرِيرًۭا","dan sutera"]]],"5604":["(Seraya bersandarkan) menjadi Haal atau kata keterangan keadaan dari Isim yang dirafa'kan oleh lafal Udkhiluuha. Lafal Udkhiluuhaa ini keberadaannya diperkirakan (di dalamnya di atas dipan-dipan) atau ranjang-ranjang yang empuk (mereka tidak melihat) tidak menemukan; menjadi Haal yang kedua (di dalamnya matahari dan tidak pula dingin yang bersangatan) maksudnya, di dalam surga mereka tidak merasakan panasnya matahari yang menyengat, dan tidak pula dingin yang mencekam. Tetapi menurut suatu pendapat bahwa lafal Zamhariiran ini artinya bulan. Maknanya, surga tetap terang-benderang sekalipun tanpa matahari dan bulan.",[["مُّتَّكِـِٔينَ","Berbaring"],["فِيهَا","di dalamnya"],["عَلَى","pada"],["ٱلْأَرَآئِكِ ۖ","pelamin"],["لَا","Tidak"],["يَرَوْنَ","mereka akan melihat"],["فِيهَا","di dalamnya"],["شَمْسًۭا","matahari"],["وَلَا","dan bukan"],["زَمْهَرِيرًۭا","sejuk beku"]]],"5605":["(Dan dekatlah) di'athafkan secara Mahall kepada lafal Yarauna (di atas mereka) maksudnya, di antara mereka (naungannya) yaitu naungan pohon-pohon surga (dan buahnya dimudahkan memetiknya semudah-mudahnya) artinya, buah-buahannya didekatkan sehingga dapat dipetik baik oleh orang yang berdiri, atau orang yang duduk, bahkan orang yang sedang berbaring sekalipun.",[["وَدَانِيَةً","Dan dekat"],["عَلَيْهِمْ","di atas mereka"],["ظِلَـٰلُهَا","(adalah) naungannya"],["وَذُلِّلَتْ","dan akan tergantung rendah"],["قُطُوفُهَا","gugusan buahnya"],["تَذْلِيلًۭا","berjuntai rendah"]]],"5606":["(Dan diedarkan kepada mereka) di dalam surga itu (bejana-bejana dari perak dan piala-piala) atau gelas-gelas yang tanpa pengikat (yang bening laksana kaca.)",[["وَيُطَافُ","Dan akan diedarkan"],["عَلَيْهِم","antara mereka"],["بِـَٔانِيَةٍۢ","kapal"],["مِّن","daripada"],["فِضَّةٍۢ","perak"],["وَأَكْوَابٍۢ","dan cawan"],["كَانَتْ","(iaitu) adalah"],["قَوَارِيرَا۠","(daripada) kristal"]]],"5607":["(Yaitu kaca-kaca dari perak) gelas-gelas dan piala-piala itu terbuat dari perak yang bagian dalamnya dapat dilihat dari luar, sehingga tampak bening sebening kaca (yang telah diukur mereka) yakni oleh pelayan-pelayan yang mengedarkannya (dengan sebaik-baiknya) sesuai dengan kecukupan minum orang-orang yang meminumnya, tidak lebih dan tidak pula kurang; cara minum yang demikian itu merupakan cara minum yang paling nikmat.",[["قَوَارِيرَا۟","Sejernih kristal"],["مِن","daripada"],["فِضَّةٍۢ","perak"],["قَدَّرُوهَا","Mereka akan menentukannya"],["تَقْدِيرًۭا","mengukur"]]],"5608":["(Di dalam surga itu mereka diberi minum segelas) khamar (yang campurannya) atau sesuatu yang dicampurkan ke dalam minuman itu (adalah jahe.)",[["وَيُسْقَوْنَ","Dan mereka akan diberi minum"],["فِيهَا","di dalamnya"],["كَأْسًۭا","secawan"],["كَانَ","ialah"],["مِزَاجُهَا","campurannya"],["زَنجَبِيلًا","(dari) Zanjabil"]]],"5609":["(Yaitu dari mata air) menjadi Badal dari lafal Zanjabiilaa (yang dinamakan salsabil) yaitu air telaga itu rasanya seperti jahe yang sangat disukai oleh orang-orang Arab, dan minuman ini sangat mudah diteguknya.",[["عَيْنًۭا","Sebuah musim bunga"],["فِيهَا","di dalamnya"],["تُسَمَّىٰ","bernama"],["سَلْسَبِيلًۭا","Salsabil"]]],"5610":["(Dan mereka dikelilingi oleh pelayan-pelayan muda yang tetap muda) mereka sama sekali tidak akan menjadi tua. (Apabila kamu melihat mereka, kamu akan mengira mereka) karena penampilan mereka yang indah dan jumlah mereka yang menyebar dengan sangat banyaknya (mutiara yang bertaburan) dari untaiannya atau dari tempat asalnya, yang demikian itu lebih indah dibandingkan berada di tempat lain.",[["۞ وَيَطُوفُ","Dan akan beredar"],["عَلَيْهِمْ","antara mereka"],["وِلْدَٰنٌۭ","budak-budak muda"],["مُّخَلَّدُونَ","dijadikan abadi"],["إِذَا","Apabila"],["رَأَيْتَهُمْ","kamu melihat mereka"],["حَسِبْتَهُمْ","kamu akan fikir mereka"],["لُؤْلُؤًۭا","(menjadi) mutiara"],["مَّنثُورًۭا","bertaburan"]]],"5611":["(Dan apabila kamu melihat di sana) maksudnya, kamu diizinkan untuk melihat surga (niscaya kamu akan melihat) menjadi Jawab Syarath dari Idzaa (berbagai macam kenikmatan) yang tak dapat digambarkan (dan kerajaan yang besar) yang luas dan tak terbatas.",[["وَإِذَا","Dan apabila"],["رَأَيْتَ","kamu tengok"],["ثَمَّ","kemudian"],["رَأَيْتَ","kamu akan melihat"],["نَعِيمًۭا","berkat"],["وَمُلْكًۭا","dan sebuah kerajaan"],["كَبِيرًا","yang besar"]]],"5612":["(Pakaian luar mereka) dinashabkan karena menjadi Zharaf, dan menjadi Khabar dari Mubtada sesudahnya. Menurut qiraat lain dibaca 'Aaliyhim karena dianggap menjadi Mubtada sedangkan lafal sesudahnya menjadi Khabarnya, dan Dhamir Muttashilnya kembali kepada Ma'thuf 'Alaih (dari sutera halus) terbuat daripadanya (yang hijau) dibaca Rafa' yakni Khudhrun (dan sutera tebal) dibaca Jaar yakni Istabraqin artinya, sutera yang tebal. Yakni pakaian bagian luar mereka terbuat dari sutera halus, sedangkan bagian dalamnya terbuat dari sutera tebal. Menurut suatu qiraat dibaca Khudhrin Waistabraqun; menurut qiraat lainnya dibaca Khudhrun Waistabraqun; dan menurut suatu qiraat lain lagi dibaca Khudrin Waistabraqin (dan mereka diberi perhiasan dari gelang-gelang perak) tetapi pada ayat lainnya disebutkan terbuat dari emas; hal ini menunjukkan bahwa mereka diberi perhiasan yang terbuat dari emas dan perak secara berbarengan, tetapi terpisah-pisah (dan Rabb mereka memberikan kepada mereka minuman yang bersih) atau sangat bersih, berbeda dengan keadaan khamar di dunia.",[["عَـٰلِيَهُمْ","atas mereka"],["ثِيَابُ","(akan menjadi) pakaian"],["سُندُسٍ","(dari) sutera halus"],["خُضْرٌۭ","hijau"],["وَإِسْتَبْرَقٌۭ ۖ","dan brokat berat"],["وَحُلُّوٓا۟","Dan mereka akan berhias"],["أَسَاوِرَ","(dengan) gelang"],["مِن","daripada"],["فِضَّةٍۢ","perak"],["وَسَقَىٰهُمْ","dan akan memberi mereka minum"],["رَبُّهُمْ","Tuhan mereka"],["شَرَابًۭا","minuman"],["طَهُورًا","tulen"]]],"5613":["(Sesungguhnya ini) yakni kenikmatan ini (adalah balasan untuk kalian, dan usaha kalian adalah disyukuri.)",[["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["كَانَ","ialah"],["لَكُمْ","bagi kamu"],["جَزَآءًۭ","ganjaran"],["وَكَانَ","dan telah"],["سَعْيُكُم","usaha kamu"],["مَّشْكُورًا","dihargai"]]],"5614":["(Sesungguhnya Kami) lafal Nahnu berfungsi mengukuhkan makna isimnya Inna, atau dianggap sebagai Dhamir Fashal (telah menurunkan Alquran kepadamu dengan berangsur-angsur) ayat ini menjadi Khabar dari Inna, yakni Kami menurunkannya secara berangsur-angsur, tidak sekaligus.",[["إِنَّا","Sesungguhnya Kami"],["نَحْنُ","[Kami]"],["نَزَّلْنَا","[Kami] mendedahkan"],["عَلَيْكَ","kepada kamu"],["ٱلْقُرْءَانَ","al-Quran"],["تَنزِيلًۭا","secara progresif"]]],"5615":["(Maka bersabarlah kamu untuk melaksanakan ketetapan Rabbmu) yang dibebankan kepadamu yaitu, menyampaikan risalah-Nya (dan janganlah kamu ikuti, di antara mereka) yakni orang-orang kafir (orang yang berdosa dan orang yang kafir) yang dimaksud adalah Atabah bin Rabi'ah dan Walid bin Mughirah, kedua-duanya telah berkata kepada Nabi saw., \"Kembalilah kamu dari perkara ini dari agama Islam.\" Dan dapat pula diartikan setiap orang yang berdosa dan setiap orang yang kafir; makna yang dimaksud ialah janganlah kamu mengikuti ajakan dan seruan kedua jenis orang tersebut dalam keadaan bagaimana pun, yang seruannya itu mengajakmu kepada perbuatan dosa atau kekafiran.",[["فَٱصْبِرْ","Jadi bersabarlah"],["لِحُكْمِ","untuk (the) Perintah"],["رَبِّكَ","Tuhanmu"],["وَلَا","dan jangan"],["تُطِعْ","patuh"],["مِنْهُمْ","daripada mereka"],["ءَاثِمًا","mana-mana pendosa"],["أَوْ","atau"],["كَفُورًۭا","orang kafir"]]],"5616":["(Dan sebutlah nama Rabbmu) di dalam salatmu (pada waktu pagi dan petang) yakni dalam salat Subuh, Zuhur dan Asar.",[["وَٱذْكُرِ","Dan ingat"],["ٱسْمَ","(nama)"],["رَبِّكَ","Tuhanmu"],["بُكْرَةًۭ","pagi"],["وَأَصِيلًۭا","dan petang"]]],"5617":["(Dan pada sebagian dari malam, maka sujudlah kamu kepada-Nya) artinya, dirikanlah salat Magrib dan Isyak (dan bertasbihlah kepada-Nya pada bagian yang panjang di malam hari) lakukanlah salat sunat di malam hari, sebagaimana keterangan yang telah kami sebutkan yaitu, sepertiganya atau separohnya atau dua pertiganya.",[["وَمِنَ","Dan daripada"],["ٱلَّيْلِ","malam"],["فَٱسْجُدْ","sujud"],["لَهُۥ","kepada-Nya"],["وَسَبِّحْهُ","dan bertasbih kepada-Nya"],["لَيْلًۭا","satu malam"],["طَوِيلًا","panjang"]]],"5618":["(Sesungguhnya mereka menyukai kehidupan dunia) (dan mereka tidak mempedulikan hari yang berat) yaitu hari yang penuh dengan penderitaan, yakni hari kiamat. Maksudnya, mereka tidak beramal untuk menyambut kedatangannya.",[["إِنَّ","Sesungguhnya"],["هَـٰٓؤُلَآءِ","ini"],["يُحِبُّونَ","cinta"],["ٱلْعَاجِلَةَ","yang segera"],["وَيَذَرُونَ","dan pergi"],["وَرَآءَهُمْ","belakang mereka"],["يَوْمًۭا","sehari"],["ثَقِيلًۭا","kubur"]]],"5619":["(Kami telah menciptakan mereka dan menguatkan) menjadikan kuat (persendian tubuh mereka) yakni semua anggota tubuh mereka dan sendi-sendinya (apabila Kami menghendaki, Kami sungguh-sungguh mengganti) Kami menjadikan (orang-orang yang serupa dengan mereka) dalam bentuknya sebagai pengganti mereka, seumpamanya Kami membinasakan mereka terlebih dahulu (dengan sebenar-benarnya) lafal ayat ini berfungsi mengukuhkan makna yang terdapat dalam lafal Baddalnaa. lafal Idzaa berkedudukan sama dengan lafal In seperti contoh lain, yaitu: In Yasya' Yudzhibkum, artinya; Seandainya Allah menghendaki niscaya Dia membinasakan kalian. Demikian itu karena pengertian yang terkandung di dalam lafal Idzaa hanya khusus dipakai untuk sesuatu yang pasti akan terjadi, sedangkan di sini Allah swt. tidak menghendaki hal tersebut.",[["نَّحْنُ","Kami"],["خَلَقْنَـٰهُمْ","mencipta mereka"],["وَشَدَدْنَآ","dan Kami kuatkan"],["أَسْرَهُمْ ۖ","bentuk mereka"],["وَإِذَا","dan apabila"],["شِئْنَا","Kami akan"],["بَدَّلْنَآ","Kita boleh berubah"],["أَمْثَـٰلَهُمْ","keserupaan mereka"],["تَبْدِيلًا","(dengan) perubahan"]]],"5620":["(Sesungguhnya ini) surah ini (adalah suatu peringatan) suatu nasihat dan pelajaran bagi makhluk (maka barang siapa menghendaki niscaya dia mengambil jalan kepada Rabbnya) yakni jalan yang dapat menyampaikan dia kepada-Nya, yaitu melalui ketaatan.",[["إِنَّ","Sesungguhnya"],["هَـٰذِهِۦ","ini"],["تَذْكِرَةٌۭ ۖ","(adalah) peringatan"],["فَمَن","jadi sesiapa"],["شَآءَ","wasiat"],["ٱتَّخَذَ","biar dia ambil"],["إِلَىٰ","kepada"],["رَبِّهِۦ","Tuhannya"],["سَبِيلًۭا","satu cara"]]],"5621":["(Dan kalian tidak menghendaki) dapat dibaca Tasyaa-uuna dan Yasyaa-uuna, kalau dibaca Yasyaa-uuna artinya, dan mereka tidak menghendaki untuk mengambil jalan kepada Rabbnya dengan mengerjakan ketaatan (kecuali bila dikehendaki Allah) hal tersebut. (Sesungguhnya Allah adalah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["وَمَا","Dan tidak"],["تَشَآءُونَ","kamu akan"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَشَآءَ","wasiat"],["ٱللَّهُ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["عَلِيمًا","Maha Mengetahui"],["حَكِيمًۭا","Maha Bijaksana"]]],"5622":["(Dia memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya) yakni surga-Nya, mereka adalah orang-orang yang beriman. (Dan bagi orang-orang lalim) dinashabkan oleh Fi'il atau kata kerja yang keberadaannya diperkirakan, lengkapnya, Dia telah menyediakan bagi mereka. Pengertian ini disimpulkan dari firman berikutnya (disediakan-Nya azab yang pedih) azab yang menyakitkan; mereka adalah orang-orang kafir.",[["يُدْخِلُ","Dia mengaku"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["فِى","ke dalam"],["رَحْمَتِهِۦ ۚ","rahmatNya"],["وَٱلظَّـٰلِمِينَ","tetapi (bagi) orang-orang yang zalim"],["أَعَدَّ","Dia dah sediakan"],["لَهُمْ","bagi mereka"],["عَذَابًا","azab"],["أَلِيمًۢا","yang pedih"]]],"5623":["(Demi angin yang bertiup sepoi-sepoi) yang bertiup secara beruntun bagaikan beruntunnya susunan rambut kuda yang satu sama lainnya saling beriring-iringan. Dinashabkan karena menjadi Haal atau kata keterangan keadaan.",[["وَٱلْمُرْسَلَـٰتِ","Oleh yang diutuskan"],["عُرْفًۭا","satu demi satu"]]],"5624":["(Dan demi angin yang bertiup dengan kencang) yang bertiup sangat kencang.",[["فَٱلْعَـٰصِفَـٰتِ","Dan angin yang bertiup"],["عَصْفًۭا","secara ganas"]]],"5625":["(Dan demi angin yang menyebarkan rahmat) yaitu angin yang menyebarkan hujan.",[["وَٱلنَّـٰشِرَٰتِ","Dan yang berselerak"],["نَشْرًۭا","jauh dan luas"]]],"5626":["(Dan demi yang membedakan sejelas-jelasnya) maksudnya, demi ayat-ayat Alquran yang membedakan antara perkara yang hak dan perkara yang batil, serta yang membedakan antara perkara yang halal dan perkara yang haram.",[["فَٱلْفَـٰرِقَـٰتِ","Dan mereka yang berpisah"],["فَرْقًۭا","(oleh) Kriteria"]]],"5627":["(Dan demi malaikat-malaikat yang menyampaikan peringatan) yakni malaikat-malaikat yang turun untuk menyampaikan wahyu kepada para nabi dan para rasul supaya wahyu tersebut disampaikan kepada umat-umat manusia.",[["فَٱلْمُلْقِيَـٰتِ","Dan mereka yang menjatuhkan"],["ذِكْرًا","(the) Peringatan"]]],"5628":["(Untuk menolak alasan-alasan atau memberi peringatan-peringatan) dari Allah swt. Menurut suatu qiraat dibaca 'Udzuran dan Nudzuran, dengan memakai harakat damah pada kedua huruf Dzalnya.",[["عُذْرًا","(Sebagai) justifikasi"],["أَوْ","atau"],["نُذْرًا","amaran"]]],"5629":["(Sesungguhnya apa yang dijanjikan kepada kalian itu) hai orang-orang kafir Mekah, yaitu mengenai hari berbangkit dan azab yang akan menimpa kalian (pasti terjadi) pasti akan terjadi.",[["إِنَّمَا","Memang apa"],["تُوعَدُونَ","kamu dijanjikan"],["لَوَٰقِعٌۭ","pasti akan berlaku"]]],"5630":["(Maka apabila bintang-bintang telah dihapuskan) dihilangkan cahayanya.",[["فَإِذَا","Maka apabila"],["ٱلنُّجُومُ","bintang"],["طُمِسَتْ","dilenyapkan"]]],"5631":["(Dan apabila langit dibelah) atau menjadi terbelah.",[["وَإِذَا","Dan apabila"],["ٱلسَّمَآءُ","syurga itu"],["فُرِجَتْ","terbelah"]]],"5632":["(Dan apabila gunung-gunung telah dihancurkan) diletuskan hingga menjadi debu yang beterbangan.",[["وَإِذَا","Dan apabila"],["ٱلْجِبَالُ","pergunungan"],["نُسِفَتْ","terpesona"]]],"5633":["(Dan apabila rasul-rasul telah dikumpulkan di dalam suatu waktu) memakai Wau dan Hamzah sebagai Badal daripadanya yaitu, pada satu ketika rasul-rasul akan dikumpulkan.",[["وَإِذَا","Dan apabila"],["ٱلرُّسُلُ","para Rasul"],["أُقِّتَتْ","dikumpulkan pada masa yang ditetapkan"]]],"5634":["(Sampai hari kapankah) yakni hari yang besar (ditangguhkan) persaksian terhadap umat-umat mereka tentang penyampaian mereka?",[["لِأَىِّ","Untuk apa"],["يَوْمٍ","Hari"],["أُجِّلَتْ","adalah (ini) ditangguhkan"]]],"5635":["(Sampai hari keputusan) di antara semua makhluk; dari pengertian ayat inilah diambil kesimpulan bagi Jawab lafal Idzaa yakni, terjadilah keputusan di antara semua makhluk.",[["لِيَوْمِ","Untuk (hari) itu"],["ٱلْفَصْلِ","(dari) Penghakiman"]]],"5636":["(Dan tahukah kamu apakah hari keputusan itu?) ayat ini menggambarkan tentang kengerian yang terdapat di dalam hari tersebut.",[["وَمَآ","Dan apa"],["أَدْرَىٰكَ","akan membuat kamu tahu"],["مَا","apa"],["يَوْمُ","(ialah) Hari"],["ٱلْفَصْلِ","(dari) Penghakiman"]]],"5637":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan) ayat ini mengandung makna ancaman bagi mereka yang tidak mempercayainya.",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5638":["(Bukankah Kami telah membinasakan orang-orang yang dahulu?) disebabkan kedustaan mereka.",[["أَلَمْ","tidak"],["نُهْلِكِ","Kita musnahkan"],["ٱلْأَوَّلِينَ","bekas (orang)"]]],"5639":["(Lalu Kami iringi mereka dengan orang-orang yang datang kemudian) di antara orang-orang yang mendustakan seperti orang-orang kafir Mekah, maka Kami kelak akan membinasakan mereka pula.",[["ثُمَّ","Kemudian"],["نُتْبِعُهُمُ","Kami mengikuti mereka"],["ٱلْـَٔاخِرِينَ","(dengan) yang terkemudian"]]],"5640":["(Demikianlah) sebagaimana Kami lakukan terhadap orang-orang yang mendustakan (Kami berbuat terhadap orang-orang yang berdosa) artinya, Kami akan melakukan hal yang sama terhadap orang-orang yang berdosa yang kelak akan datang, yaitu Kami pasti akan membinasakan mereka.",[["كَذَٰلِكَ","Demikianlah"],["نَفْعَلُ","Kita berurusan"],["بِٱلْمُجْرِمِينَ","dengan penjenayah"]]],"5641":["(Kecelakaan besarlah pada hari itu bagi orang-orang yang mendustakan) sebagai pengukuh terhadap ayat sebelumnya.",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5642":["(Bukankah Kami menciptakan kalian dari air yang hina?) yang lemah, yaitu air mani.",[["أَلَمْ","tidak"],["نَخْلُقكُّم","Kami mencipta kamu"],["مِّن","daripada"],["مَّآءٍۢ","sebuah air"],["مَّهِينٍۢ","keji"]]],"5643":["(Kemudian Kami letakkan dia dalam tempat yang kokoh) tempat yang terpelihara, yaitu dalam rahim.",[["فَجَعَلْنَـٰهُ","Kemudian Kami letakkannya"],["فِى","dalam"],["قَرَارٍۢ","sebuah tempat tinggal"],["مَّكِينٍ","selamat"]]],"5644":["(Sampai waktu yang ditentukan) yaitu sampai waktu kelahirannya.",[["إِلَىٰ","Untuk"],["قَدَرٍۢ","tempoh"],["مَّعْلُومٍۢ","diketahui"]]],"5645":["(Lalu Kami tentukan) waktu tersebut (maka sebaik-baik yang menentukan) adalah Kami.",[["فَقَدَرْنَا","Maka Kami mengukur"],["فَنِعْمَ","dan Terbaik"],["ٱلْقَـٰدِرُونَ","(adakah Kami) mengukur"]]],"5646":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5647":["(Bukankah Kami menjadikan bumi tempat berkumpul) lafal Kifaatan adalah Mashdar dari lafal Kafata yang artinya berkumpul atau tempat untuk berkumpul.",[["أَلَمْ","belum"],["نَجْعَلِ","Kami buat"],["ٱلْأَرْضَ","bumi"],["كِفَاتًا","sebuah bekas"]]],"5648":["(Orang-orang hidup) pada permukaannya (dan orang-orang mati) yang ada pada perutnya.",[["أَحْيَآءًۭ","(Untuk) hidup"],["وَأَمْوَٰتًۭا","dan (yang) mati"]]],"5649":["(Dan Kami jadikan padanya gunung-gunung yang tinggi) gunung-gunung yang menjulang tinggi (dan Kami beri minum kalian dengan air yang tawar) air yang segar dan tawar.",[["وَجَعَلْنَا","Dan Kami jadikan"],["فِيهَا","di dalamnya"],["رَوَٰسِىَ","gunung yang kukuh"],["شَـٰمِخَـٰتٍۢ","megah"],["وَأَسْقَيْنَـٰكُم","dan Kami beri kamu minum"],["مَّآءًۭ","air"],["فُرَاتًۭا","manis"]]],"5650":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan) kemudian pada hari kiamat dikatakan kepada orang-orang yang mendustakan:",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5651":["(\"Pergilah kamu sekalian mendapatkan azab yang dahulunya kalian mendustakannya.)",[["ٱنطَلِقُوٓا۟","Teruskan"],["إِلَىٰ","kepada"],["مَا","apa"],["كُنتُم","kamu pernah"],["بِهِۦ","di dalamnya"],["تُكَذِّبُونَ","menafikan"]]],"5652":["(Pergilah kalian mendapatkan naungan yang mempunyai tiga cabang) yang dimaksud adalah asap neraka Jahanam, apabila membubung terbagi menjadi tiga, karena sangat besarnya.",[["ٱنطَلِقُوٓا۟","Teruskan"],["إِلَىٰ","kepada"],["ظِلٍّۢ","sebuah bayang"],["ذِى","mempunyai"],["ثَلَـٰثِ","tiga"],["شُعَبٍۢ","lajur"]]],"5653":["(Yang tidak melindungi) asap itu tidak dapat menaungi mereka dari panas hari itu (dan tiada bermanfaat) barang sedikit pun bagi mereka (untuk menolak api\") yakni api neraka.",[["لَّا","Tidak"],["ظَلِيلٍۢ","teduh sejuk"],["وَلَا","dan bukan"],["يُغْنِى","memanfaatkan"],["مِنَ","terhadap"],["ٱللَّهَبِ","api itu"]]],"5654":["(Sesungguhnya neraka itu) maksudnya, api neraka itu (melontarkan bunga api) memercikkan bunga api (sebesar istana) yakni besar dan tingginya bagaikan istana.",[["إِنَّهَا","Sesungguhnya, ia"],["تَرْمِى","muntah"],["بِشَرَرٍۢ","percikan api"],["كَٱلْقَصْرِ","sebagai kubu"]]],"5655":["(Seolah-olah ia iringan unta) lafal Jimaalaatun bentuk jamak dari lafal Jimaalah, juga lafal Jimaalah ini adalah bentuk jamak dari lafal Jamalun. Menurut suatu qiraat dibaca Jimaalatun (yang kuning kehitam-hitaman) perwujudan dan warnanya. Di dalam sebuah hadis disebutkan: \"Manusia yang paling buruk ialah yang hitam bagaikan aspal.\" Orang-orang Arab menamakan unta yang berwarna hitam unta kuning, demikian itu karena warna hitamnya dicampuri dengan warna kuning. Tetapi menurut pendapat yang lain bahwa arti lafal Shufrun dalam ayat ini adalah hitam, karena alasan yang telah disebutkan tadi, tetapi menurut pendapat lainnya lagi bermakna kuning. Lafal Syararun adalah bentuk jamak dari lafal Syaraarah artinya percikan atau bunga api; dan lafal Al-Qiiru/Al-Qaaru artinya belakin atau aspal.",[["كَأَنَّهُۥ","Seolah-olah mereka (adalah)"],["جِمَـٰلَتٌۭ","unta"],["صُفْرٌۭ","kuning"]]],"5656":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5657":["(Ini) yakni hari kiamat ini (adalah hari yang mereka tidak dapat berbicara) sepatah kata pun.",[["هَـٰذَا","Ini"],["يَوْمُ","(adalah) sehari"],["لَا","tidak"],["يَنطِقُونَ","mereka akan bercakap"]]],"5658":["(Dan tidak diizinkan kepada mereka) mengemukakan alasannya (sehingga mereka dapat mengemukakan alasannya) lafal Faya'tadziruuna di'athafkan kepada lafal Yu'dzanu tanpa ada penyebab yang mengaitkannya, tetapi tetap termasuk ke dalam pengertian negatif. Artinya tiada berkenan bagi mereka untuk berbicara, maka tiada alasan bagi mereka.",[["وَلَا","Dan tidak"],["يُؤْذَنُ","adakah ia akan dibenarkan"],["لَهُمْ","bagi mereka"],["فَيَعْتَذِرُونَ","untuk membuat alasan"]]],"5659":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5660":["(Ini adalah hari keputusan; Kami mengumpulkan kalian) hai orang-orang yang mendustakan dari kalangan umat ini, yakni umat Nabi Muhammad (dan orang-orang yang terdahulu) dari kalangan orang-orang yang mendustakan sebelum kalian; lalu kalian semuanya akan dihisab kemudian diazab.",[["هَـٰذَا","Ini"],["يَوْمُ","(ialah) Hari"],["ٱلْفَصْلِ ۖ","(dari) Penghakiman"],["جَمَعْنَـٰكُمْ","Kami telah mengumpulkan kamu"],["وَٱلْأَوَّلِينَ","dan orang-orang dahulu"]]],"5661":["(Jika kalian mempunyai tipu daya) tipu muslihat untuk melindungi diri kalian dari azab (maka lakukanlah tipu daya kalian itu terhadap-Ku) perbuatlah tipu daya kalian itu.",[["فَإِن","Jadi jika"],["كَانَ","ialah"],["لَكُمْ","bagi kamu"],["كَيْدٌۭ","sesuatu rancangan"],["فَكِيدُونِ","maka rancanglah terhadap-Ku"]]],"5662":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5663":["(Sesungguhnya orang-orang yang bertakwa berada dalam naungan) berada dalam naungan pohon-pohon, yang pada hari itu bukan main panasnya, padahal tiada matahari (dan mata air-mata air) yang mengalir.",[["إِنَّ","Sesungguhnya"],["ٱلْمُتَّقِينَ","orang yang soleh"],["فِى","(akan) masuk"],["ظِلَـٰلٍۢ","warna"],["وَعُيُونٍۢ","dan mata air"]]],"5664":["(Dan mendapat buah-buahan dari jenis-jenis yang mereka sukai) di dalam ungkapan ayat ini terkandung pengertian bahwa makanan dan minuman di surga sesuai dengan selera penghuninya masing-masing. Berbeda dengan keadaan di dunia, makanan dan minuman sesuai dengan kemampuan masing-masing. Kemudian dikatakan kepada orang-orang yang bertakwa itu:",[["وَفَوَٰكِهَ","Dan buah-buahan"],["مِمَّا","daripada apa"],["يَشْتَهُونَ","mereka inginkan"]]],"5665":["(\"Makan dan minumlah kalian dengan enak) lafal Haniian merupakan Haal atau kata keterangan keadaan, yakni makan dan minumlah dengan seenak-enaknya (karena apa yang telah kalian kerjakan\") berupa ketaatan.",[["كُلُوا۟","makan"],["وَٱشْرَبُوا۟","dan minum"],["هَنِيٓـًٔۢا","(dalam) kepuasan"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"5666":["(Sesungguhnya demikianlah Kami) sebagaimana Kami memberikan balasan kepada orang-orang yang takwa (memberikan balasan kepada orang-orang yang berbuat baik.)",[["إِنَّا","Sesungguhnya Kami"],["كَذَٰلِكَ","dengan demikian"],["نَجْزِى","pahala"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"5667":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5668":["(\"Makanlah dan bersenang-senanglah kamu sekalian) khithab atau perintah ini ditujukan kepada orang-orang kafir di dunia (dalam waktu yang pendek) waktu yang singkat; yang batasnya adalah kematian mereka. Di dalam ungkapan ini terkandung makna ancaman terhadap mereka (sesungguhnya kalian adalah orang-orang yang berdosa.\")",[["كُلُوا۟","makan"],["وَتَمَتَّعُوا۟","dan berseronoklah"],["قَلِيلًا","sedikit"],["إِنَّكُم","sesungguhnya, kamu"],["مُّجْرِمُونَ","(adalah) penjenayah"]]],"5669":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5670":["(Dan apabila dikatakan kepada mereka, \"Rukuklah\") yakni salatlah kalian (niscaya mereka tidak mau rukuk) tidak mau salat.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمُ","kepada mereka"],["ٱرْكَعُوا۟","Tunduk"],["لَا","tidak"],["يَرْكَعُونَ","mereka tunduk"]]],"5671":["(Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.)",[["وَيْلٌۭ","celaka"],["يَوْمَئِذٍۢ","hari itu"],["لِّلْمُكَذِّبِينَ","kepada orang-orang yang mendustakan"]]],"5672":["(Maka kepada perkataan apakah sesudah ini) sesudah Alquran ini (mereka akan beriman?) maksudnya, tidak mungkin mereka akan beriman kepada kitab-kitab Allah lainnya sesudah mereka mendustakannya, karena di dalam Alquran terkandung unsur I'jaz atau mukjizat yang tidak terdapat pada kitab-kitab Allah lainnya.",[["فَبِأَىِّ","Kemudian dalam apa"],["حَدِيثٍۭ","kenyataan"],["بَعْدَهُۥ","selepas itu"],["يُؤْمِنُونَ","adakah mereka akan beriman"]]]});